    bad = [f for f in fields if not isinstance(f, str) or not f.isidentifier()]
    if bad:
        raise TypeError(f"field names must be valid identifiers: {bad!r}")

    # Build the class namespace
    ns = {}
    ns['__slots__'] = tuple(fields)

    # __init__ that accepts positional and keyword arguments for the fields
    def __init__(self, *args, **kwargs):
        if len(args) > len(fields):
            raise TypeError(f"expected at most {len(fields)} positional arguments")
        # assign positional args
        for field_name, value in zip(fields, args):
            setattr(self, field_name, value)
        # assign keyword args (overwriting if already set)
        for field_name in fields:
            if field_name in kwargs:
                setattr(self, field_name, kwargs.pop(field_name))
        if kwargs:
            raise TypeError(f"unexpected keyword argument(s): {list(kwargs.keys())}")
    ns['__init__'] = __init__

    # Property to expose the SRID for this point type
    def srid_property(self):
        return srid_map.get(name)
    ns['srid'] = property(srid_property)

    # Optional: Simple repr that shows the class name and field values
    def __repr__(self):
        values = ", ".join(f"{f}={getattr(self, f)!r}" for f in fields)
        return f"{name}({values})"
    ns['__repr__'] = __repr__

    # Optional: Iterable over field values
    def __iter__(self):
        return iter(getattr(self, f) for f in fields)
    ns['__iter__'] = __iter__

    # Create and return the new type
    return type(name, (object,), ns)

def point_type(name, fields, srid_map):
    """Dynamically create a Point subclass.

    Parameters
    ----------
    name : str
        The name of the new subclass.
    fields : iterable
        An iterable of field specifications. Each element may be:
        - a string field name,
        - a tuple (field_name, field_type),
        - a tuple (field_name, field_type, **kwargs) which will be set as class
          attributes. If field_type is omitted, its type annotation will be set
          to 'Any'.
    srid_map : dict
        A mapping from field names to SRID values that will be stored as the
        class attribute ``__srid_map__``. All keys must correspondent to a
        field name.
    Returns
    -------
    type
        A new subclass of ``Point`` with the specified fields and SRID
        mapping.
    """

    # Validate the class name
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    if not name.isidentifier():
        raise ValueError(f"Invalid class name: {name!r}")

    # Ensure fields is an iterable
    try:
        fields_iter = list(fields) if fields is not None else []
    except TypeError as exc:
        raise TypeError("fields must be iterable") from exc

    namespace = {}
    annotations = {}

    for item in fields_iter:
        # Resolve field name and type
        if isinstance(item, str):
            field_name = item
            field_type = 'Any'
        elif isinstance(item, tuple):
            if len(item) == 0:
                raise ValueError("field tuple must contain at least a name")
            field_name = item[0]
            if len(item) >= 2:
                field_type = item[1]
            else:
                field_type = 'Any'
            if len(item) > 2:
                # Remaining tuple items are treated as class attributes
                # e.g., field(name, type, spec)
                for spec_attr in item[2:]:
                    namespace[spec_attr] = None  # placeholder
        else:
            raise TypeError(f"Invalid field specification: {item!r}")

        # Validate the field name
        if not isinstance(field_name, str) or not field_name.isidentifier():
            raise TypeError(f"Field names must be valid identifiers: {field_name!r}")

        annotations[field_name] = field_type

    namespace['__annotations__'] = annotations

    # Attach SRID mapping
    if srid_map:
        if not isinstance(srid_map, dict):
            raise TypeError("srid_map must be a dict mapping field names to SRIDs")
        # Ensure all SRID keys correspond to defined fields
        for key in srid_map:
            if key not in annotations:
                raise ValueError(f"SRID map contains unknown field: {key!r}")
        namespace['__srid_map__'] = srid_map

    # Basic constructor that accepts keyword arguments for the defined fields
    def __init__(self, *args, **kwargs):
        # Allow the base ``Point`` to handle positional arguments
        super(cls, self).__init__(*args, **kwargs)
        for k, v in kwargs.items():
            if k in annotations:
                setattr(self, k, v)

    namespace['__init__'] = __init__

    # Create the new subclass of Point
    cls = type(name, (Point,), namespace)
    return cls

def deprecated(message):
    """Decorator for deprecating functions and methods.

    This decorator emits a :class:`DeprecationWarning` with the provided
    *message* every time the decorated function or method is called.
    It also appends a short deprecation notice to the wrapped function's
    docstring.

    Example::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass
    """
    import warnings
    import functools

    if not isinstance(message, str):
        raise TypeError("message must be a string")

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, DeprecationWarning, stacklevel=3)
            return func(*args, **kwargs)

        existing = func.__doc__ or ''
        deprecation_doc = f"Deprecated: {message}"
        wrapper.__doc__ = "\n\n".join([existing, deprecation_doc]).strip()
        return wrapper

    return decorator

