def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle"""
    import random as _random
    if seq is None:
        return []
    try:
        lst = list(seq)
    except TypeError:
        raise ValueError("seq must be a sequence of strings")
    rng = _random.Random(0)
    rng.shuffle(lst)
    return lst

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not isinstance(s, str):
        raise TypeError(f"Expected str, got {type(s).__name__}")
    s = s.strip()
    if not s:
        raise ValueError("Empty version string")
    def _extract(part: str):
        i = 0
        n = len(part)
        while i < n and not part[i].isdigit():
            i += 1
        if i == n:
            return None
        j = i
        while j < n and part[j].isdigit():
            j += 1
        return int(part[i:j])
    parts = s.split(".")
    result = []
    for part in parts:
        num = _extract(part)
        if num is not None:
            result.append(num)
    if not result:
        raise ValueError(f"Could not parse any numeric part from: {s!r}")
    return tuple(result)

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison

    Convert a dotted version string into a tuple of integers. Only numeric
    components are kept; any non‑digit suffixes are ignored. Empty strings
    (e.g., a trailing dot) are skipped.  Raises
    - TypeError if ``s`` is not a ``str``
    - ValueError if a component contains no digits
    """
    if not isinstance(s, str):
        raise TypeError(f"Expected str, got {type(s).__name__}")

    parts = s.split(".")
    nums: list[int] = []

    for part in parts:
        if part == "":
            # Skip empty fragments caused by leading/trailing dots
            continue

        # Direct numeric component
        if part.isdigit():
            nums.append(int(part))
            continue

        # Try to peel off leading digits (e.g. "2b" -> 2)
        stripped = ""
        for ch in part:
            if ch.isdigit():
                stripped += ch
            else:
                break

        if stripped:
            nums.append(int(stripped))
        else:
            raise ValueError(f"Invalid version component '{part}' in '{s}'")

    return tuple(nums)

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not isinstance(s, str):
        raise TypeError(f"parse_version expects a string, got {type(s).__name__}")
    s = s.strip()
    if not s:
        return ()
    nums = []
    for part in s.split('.'):
        # Remove any non-digit characters from the part
        digits = ''.join(ch for ch in part if ch.isdigit())
        if digits:
            nums.append(int(digits))
    return tuple(nums)

