                key += tuple(type(v) for v in args)
                if kwds:
                    key += tuple(type(v) for k, v in sorted_items)
            return key

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = make_key(args, kwargs)
            if key in cache:
                value, count = cache[key]
                cache[key] = (value, count + 1)
                return value
            result = func(*args, **kwargs)
            cache[key] = (result, 1)
            if len(cache) > maxsize:
                # Evict an entry with the lowest usage count
                evict_key = None
                min_count = None
                for k, (_, cnt) in cache.items():
                    if min_count is None or cnt < min_count:
                        min_count = cnt
                        evict_key = k
                if evict_key is not None:
                    cache.pop(evict_key, None)
            return result

        return wrapper

    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    if maxsize <= 0:
        # No caching
        def decorator(func):
            return func
        return decorator

    def _make_key(args, kwargs, typed):
        key = args
        if kwargs:
            key += tuple(sorted(kwargs.items()))
        if typed:
            key += tuple(type(v) for v in args)
        return key

    def decorator(func):
        from functools import wraps

        cache = {}
        freq = {}

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = _make_key(args, kwargs, typed)
            if key in cache:
                freq[key] += 1
                return cache[key]
            result = func(*args, **kwargs)
            if len(cache) >= maxsize:
                # Find least frequently used key(s)
                minfreq = min(freq.values())
                # If multiple keys share minfreq, evict the first one found
                evict_key = next(k for k, f in freq.items() if f == minfreq)
                del cache[evict_key]
                del freq[evict_key]
            cache[key] = result
            freq[key] = 1
            return result

        return wrapper

    return decorator

