def extostr(cls, e, max_level=30, max_path_level=5):
        """
        Format an exception.
        :param e: Any exception instance.
        :type e: Exception
        :param max_level: Maximum call stack level (default 30)
        :type max_level: int
        :param max_path_level: Maximum path level (default 5)
        :type max_path_level: int
        :return The exception readable string
        :rtype str
        """
        # Helper to shorten file paths
        def _shorten_path(path, max_parts):
            try:
                parts = path.split(os.sep)
                if len(parts) > max_parts:
                    return os.sep.join(parts[-max_parts:])
                return path
            except Exception:
                return path

        # Recursive formatter for exception chains
        def _format_exc(exc, depth=0, seen=None):
            if seen is None:
                seen = set()
            if id(exc) in seen:
                return ["<recursive exception reference>"]
            seen.add(id(exc))

            type_name = type(exc).__name__
            msg = str(exc)
            header = f"{'  '*depth}{type_name}: {msg}"
            lines = [header]

            tb = getattr(exc, "__traceback__", None)
            if tb is None:
                # Fall back to sys.exc_info() only on top-level
                if depth == 0:
                    tb = sys.exc_info()[2]
                else:
                    tb = None
            if tb:
                trace = traceback.extract_tb(tb)
                trace = trace[-max_level:]  # keep last max_level frames
                for frame in trace:
                    filename, lineno, func, text = frame
                    filename = _shorten_path(filename, max_path_level)
                    lines.append(f"{'  '*depth}  File \"{filename}\", line {lineno}, in {func}")
                    if text:
                        lines.append(f"{'  '*depth}    {text}")

            # Handle chained exceptions (__cause__ > __context__)
            cause = getattr(exc, "__cause__", None)
            context = getattr(exc, "__context__", None)
            next_exc = cause or (context if context and not cause else None)
            if next_exc and not getattr(exc, "__suppress_context__", False):
                lines.append(f"{'  '*depth}Caused by:")
                lines.extend(_format_exc(next_exc, depth=depth + 1, seen=seen))
            return lines

        try:
            return "\n".join(_format_exc(e))
        except Exception as fmt_exc:
            # Fallback in case formatting itself fails
            return f"Exception formatting failed: {fmt_exc}\nOriginal exception: {type(e).__name__}: {e}"

def file_to_textbuffer(file_name, encoding):
    """
    Load a file toward a text buffer (UTF-8), using the specify encoding while reading.
    CAUTION : This will read the whole file IN MEMORY.
    :param file_name: File name.
    :type file_name: str
    :param encoding: Encoding to use.
    :type encoding: str
    :return: A text buffer or None in case of error.
    :rtype str
    """
    try:
        with open(file_name, encoding=encoding) as f:
            return f.read()
    except Exception as e:
        try:
            logger.error("file_to_textbuffer: %s failed. Error: %s", file_name, e)
        except Exception:
            pass
        return None

