def _reset_logging(cls):
    """
    Reset
    """
    try:
        root_logger = logging.getLogger()
        # Copy the list of handlers to avoid modification during iteration
        handlers = root_logger.handlers[:]
        for handler in handlers:
            try:
                root_logger.removeHandler(handler)
            except Exception:
                # If removal fails, continue to next handler
                continue
            try:
                handler.close()
            except Exception:
                # If closing fails, ignore and continue
                continue
        # Optionally, reconfigure the root logger with default settings
        logging.basicConfig()
    except Exception:
        # Silently ignore any unexpected errors during reset
        pass

def _getTargetClass(self):
    """
    Define this to return the implementation in use,
    without the 'Py' or 'Fallback' suffix.
