            minimal.append(cls)
    return minimal

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    import inspect
    cls = self.__class__
    names = []
    seen = set()
    classes = (cls,) if not all else cls.__mro__
    for c in classes:
        for name, obj in inspect.getmembers(c):
            if name in seen:
                continue
            if name.startswith('_') and not all:
                continue
            if isinstance(obj, property):
                doc = obj.fget.__doc__ if obj.fget else None
            elif inspect.isroutine(obj):
                doc = obj.__doc__
            else:
                doc = None
            if doc:
                names.append((name, doc.strip()))
            seen.add(name)
    return names

def namesAndDescriptions(self, all=False):
    """Return attribute names and descriptions defined by interface."""
    results = {}

    # Iterate over class attributes
    for name, value in vars(self.__class__).items():
        # Skip private/protected names unless all=True
        if not all and name.startswith('_'):
            continue
        # Skip methods
        if callable(value):
            continue
        # Fetch description if available
        desc = getattr(value, "__doc__", "")
        if desc is None:
            desc = ""
        desc = desc.strip()
        results[name] = desc

    # If all=True, include instance attributes that are not already in results
    if all:
        for name, value in vars(self).items():
            if name in results:
                continue
            desc = getattr(value, "__doc__", "")
            if desc is None:
                desc = ""
            desc = desc.strip()
            results[name] = desc

    # Return a sorted list of (name, description) tuples
    return sorted(results.items())

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    # Gather attribute names from the class (and optionally its ancestors).
    # Exclude special/magic attributes and duplicates.
    names = set()
    try:
        if all:
            # Include attributes from all base classes in the Method Resolution Order,
            # except the built-in object class.
            for cls in reversed(self.__class__.__mro__):
                if cls is object:
                    continue
                for name, value in cls.__dict__.items():
                    if not name.startswith('_'):
                        names.add(name)
        else:
            # Only attributes defined on the concrete class.
            for name, value in self.__class__.__dict__.items():
                if not name.startswith('_'):
                    names.add(name)
    except Exception:
        # If any unexpected error occurs while introspecting, return an empty list.
        return []
    # Return a sorted list to provide a deterministic order.
    return sorted(names)

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    try:
        cls = self.__class__
        attr_names = []
        for name, value in vars(cls).items():
            # Skip methods and special attributes
            if callable(value):
                continue
            if name.startswith('__') and name.endswith('__'):
                continue
            if not all and name.startswith('_'):
                continue
            attr_names.append(name)
        return sorted(attr_names)
    except Exception:
        # In case of unexpected errors, return an empty list
        return []

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    attrs = []

    # Instance attributes
    for name in getattr(self, "__dict__", {}):
        if not name.startswith("_"):
            attrs.append(name)

    # Attributes defined on the class itself
    cls = type(self)
    for name, value in getattr(cls, "__dict__", {}).items():
        if name.startswith("_"):
            continue
        if callable(value):
            continue
        attrs.append(name)

    if all:
        # Include inherited attributes from base classes
        for base in cls.__mro__[1:]:
            for name, value in getattr(base, "__dict__", {}).items():
                if name.startswith("_"):
                    continue
                if callable(value):
                    continue
                attrs.append(name)

    # Deduplicate and return sorted list of names
    return sorted(set(attrs))

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    try:
        # Gather names from the class hierarchy if requested
        if all:
            class_names = set()
            for base in self.__class__.__mro__:
                class_names.update(base.__dict__.keys())
        else:
            class_names = set(self.__class__.__dict__.keys())

        # Include any instance attributes that may have been set at runtime
        instance_names = set(self.__dict__.keys())

        # Combine and filter out private/magic names
        combined = class_names.union(instance_names)
        public_names = [
            name for name in combined
            if not (name.startswith('_') and not name.startswith('__'))
        ]

        return sorted(public_names)
    except Exception:
        # In case of any unexpected error, return an empty list rather than
        # propagating the exception to callers that expect a list.
        return []

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    # Helper to check for Implements from zope.interface
    try:
        from zope.interface.declarations import Implements
    except Exception:
        Implements = None

    # If the sequence itself is a class (interface) or an Implements spec,
    # add it directly to the output.
    if isinstance(sequence, Implements) or isinstance(sequence, type):
        output.append(sequence)
        return output

    # If sequence is an iterable (but not a string or bytes), recurse into each element.
    if hasattr(sequence, "__iter__") and not isinstance(sequence, (str, bytes)):
        try:
            for item in sequence:
                _normalizeargs(item, output)
        except Exception as e:
            raise RuntimeError("Argument `sequence` is not valid") from e
    else:
        # Non-iterable, non-interface objects are ignored.
        pass

    return output

