    # Reinitialize bins
    try:
        if getattr(self, 'initial_value', None) is not None:
            n_bins = getattr(self, 'n_bins', 0)
            self.bins = [self.initial_value] * n_bins
        else:
            if hasattr(self, 'make_bins') and callable(self.make_bins):
                self.bins = self.make_bins()
            else:
                self.bins = []
    except Exception as e:
        self.bins = []
        import logging
        logging.exception("Failed to reinitialize bins in reset: %s", e)

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset contextual information to an empty dictionary
    self.context = {}

    # Reinitialize bins
    try:
        # If we have an explicit bin constructor, use it
        if hasattr(self, "make_bins") and callable(self.make_bins):
            # Use initial_value if provided, otherwise fall back to make_bins
            if hasattr(self, "initial_value"):
                # Try to preserve the original bin shape if possible
                if hasattr(self, "bins") and isinstance(self.bins, (list, tuple)):
                    self.bins = [self.initial_value for _ in self.bins]
                else:
                    # If no existing bins, create one with the initial value
                    self.bins = [self.initial_value]
            else:
                self.bins = self.make_bins()
        else:
            # No dedicated make_bins; zero out existing bins or create an empty list
            if hasattr(self, "bins"):
                self.bins = [0] * len(self.bins)
            else:
                self.bins = []
    except Exception:
        # In any failure, fall back to an empty bin list to avoid crash
        self.bins = []
    # Return nothing (in-place reset)
    return None

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset the context dictionary
    self.context = {}

    # Reinitialize bins
    use_initial = getattr(self, 'initial_value', None) is not None

    try:
        if use_initial:
            # Try to create a list of bins filled with the initial value
            if hasattr(self, 'number_of_bins') and isinstance(self.number_of_bins, int):
                self.bins = [self.initial_value for _ in range(self.number_of_bins)]
            elif hasattr(self, 'bins'):
                # If bins already exist, reset each element
                for i in range(len(self.bins)):
                    self.bins[i] = self.initial_value
        else:
            # If no initial_value, fall back to make_bins if available
            if hasattr(self, 'make_bins') and callable(self.make_bins):
                self.bins = self.make_bins()
    except Exception:
        # In case of any failure, attempt make_bins as last resort
        if hasattr(self, 'make_bins') and callable(self.make_bins):
            self.bins = self.make_bins()

    # Reset counts and total count if they exist
    if hasattr(self, 'counts') and isinstance(self.counts, (list, tuple)):
        self.counts = [0] * len(self.bins)
    if hasattr(self, 'total_count'):
        self.total_count = 0
    # If there are other state variables that should be cleared, do so here
    # For example, min_value, max_value, timestamps, etc.
    for attr in ['min_value', 'max_value', 'start_time_stamp_msec', 'end_time_stamp_msec']:
        if hasattr(self, attr):
            setattr(self, attr, None)

def to_csv(self, separator=",", header=None):
    """.. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
          Iterables are converted to tables.

    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.

    To convert :class:`Graph` to CSV inside a Lena sequence,
    use :class:`lena.output.ToCSV`.
    """
    # Build list of CSV rows
    rows = []
    for point in self:
        try:
            # Assume a point is either a tuple (coord, value) or a single coordinate
            if isinstance(point, tuple) and len(point) == 2:
                coord, value = point
            else:
                coord, value = point, None
        except Exception:
            # Skip points that cannot be unpacked
            continue

        # Convert coordinate to string
        if isinstance(coord, (list, tuple)):
            try:
                coord_str = separator.join(map(str, coord))
            except Exception:
                coord_str = str(coord)
        else:
            coord_str = str(coord)

        # Convert value to string (if any)
        if value is not None:
            if isinstance(value, (list, tuple)):
                try:
                    value_str = separator.join(map(str, value))
                except Exception:
                    value_str = str(value)
            else:
                value_str = str(value)
            row = f"{coord_str}{separator}{value_str}"
        else:
            row = coord_str

        rows.append(row)

    # Assemble final CSV string
    output_lines = []
    if header is not None:
        output_lines.append(str(header))
    output_lines.extend(rows)
    return "\n".join(output_lines) + ("\n" if output_lines else "")

def to_csv(self, separator=",", header=None):
    """.. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
