    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.

    To convert :class:`Graph` to CSV inside a Lena sequence,
    use :class:`lena.output.ToCSV`.
    """
    if separator is None:
        separator = ","
    try:
        # Try to get an iterator over points with .points() method, otherwise use __iter__
        iterator = getattr(self, "points", lambda: iter(self))()
    except Exception:
        iterator = iter(self)

    lines = []

    if header is not None:
        lines.append(str(header) + "\n")

    for point in iterator:
        try:
            # Retrieve coordinate and value from point
            if hasattr(point, "coord"):
                coord = point.coord
            else:
                # Assume point is a tuple/list where the last element is value
                # and all preceding elements are coordinates
                if isinstance(point, (list, tuple)):
                    coord = point[:-1]
                    value = point[-1]
                else:
                    continue
            if not hasattr(point, "value"):
                # If we used the tuple assumption, already have value
                if isinstance(coord, (list, tuple)):
                    pass
                else:
                    continue
            if hasattr(point, "value"):
                value = point.value
        except Exception:
            continue

        row_parts = []
        # Append coordinate components
        if isinstance(coord, (list, tuple)):
            for c in coord:
                row_parts.append(str(c))
        else:
            row_parts.append(str(coord))

        # Append value components
        if isinstance(value, (list, tuple)):
            for v in value:
                row_parts.append(str(v))
        else:
            row_parts.append(str(value))

        lines.append(separator.join(row_parts) + "\n")

