def to_csv(self, separator=",", header=None):
    """Convert graph's points to CSV.

    Returns a string containing the CSV representation of the graph's points.
    Each point is assumed to be either an object with ``coordinate`` and
    ``value`` attributes, an object with ``coords`` and ``payload`` attributes,
    or a two-element tuple ``(coordinate, value)``.  Missing attributes are
    tolerated and empty strings are used in their place.

    :param separator: The separator used in the resulting CSV.
    :param header: Optional string written as the first line of the output.
    :returns: A string containing the CSV representation.
    """
    # Prepare a list of output lines.
    lines = []

    # Include optional header if provided.
    if header is not None:
        lines.append(str(header))

    try:
        iterable = iter(self)
    except TypeError:
        # ``self`` is not iterable; nothing to export.
        return "\n".join(lines)

    for point in iterable:
        # Retrieve coordinate(s).
        try:
            coord = point.coordinate
        except AttributeError:
            try:
                coord = point.coords
            except AttributeError:
                try:
                    coord = point[0]
                except Exception:
                    coord = str(point)

        # Convert coordinate(s) to string.
        if isinstance(coord, str):
            coord_str = coord
        elif isinstance(coord, (list, tuple)):
            coord_str = separator.join(map(str, coord))
        else:
            # Fallback for any iterable but not a string.
            try:
                coord_str = separator.join(map(str, coord))
            except Exception:
                coord_str = str(coord)

        # Retrieve value(s).
        try:
            val = point.value
        except AttributeError:
            try:
                val = point.payload
            except AttributeError:
                try:
                    val = point[1]
                except Exception:
                    val = ""

        # Convert value(s) to string.
        if isinstance(val, str):
            val_str = val
        elif isinstance(val, (list, tuple)):
            val_str = separator.join(map(str, val))
        else:
            try:
                val_str = separator.join(map(str, val))
            except Exception:
                val_str = str(val)

        # Join coordinate and value parts with the separator.
        if val_str:
            line = f"{coord_str}{separator}{val_str}"
        else:
            line = coord_str

        lines.append(line)

    return "\n".join(lines)

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Ensure the coordinate name is a string
    if not isinstance(coord_name, str):
        raise TypeError("coord_name must be a string")

    # Retrieve the container that holds the variables
    try:
        variables = self._variables
    except AttributeError:
        raise AttributeError("The object has no '_variables' attribute")

    # If '_variables' is a dict, iterate over its keys; if a list/tuple, iterate directly
    err_indices = []
    if isinstance(variables, dict):
        iterable = variables.items()  # (key, value)
    elif isinstance(variables, (list, tuple)):
        iterable = enumerate(variables)  # (index, value)
    else:
        # Fall back to treating it as an iterable of variables with an implicit index
        iterable = enumerate(variables)

    for idx, var in iterable:
        # Extract the variable name
        name = None
        if isinstance(var, dict):
            name = var.get("name") or var.get("var") or None
        elif hasattr(var, "name"):
            name = getattr(var, "name")
        elif isinstance(var, str):
            name = var

        if not isinstance(name, str):
            continue

        # Check for common error suffixes
        if name.startswith(coord_name):
            suffix = name[len(coord_name) :]
            suffix_lc = suffix.lower()
            if suffix_lc.startswith("_err") or suffix_lc.startswith("_error"):
                # Using idx from enumeration
                if isinstance(iterable, dict.items()):
                    # For dict, use the key as index if it is numeric
                    if isinstance(idx, int):
                        err_indices.append(idx)
                    else:
                        err_indices.append(name)
                else:
                    err_indices.append(idx)

    return err_indices

def _get_err_indices(self, coord_name):
    """
    Get error indices corresponding to a coordinate.

    The method searches common error-related attributes on the instance
    to locate indices that are associated with *coord_name*. If no
    indices can be found, an empty list is returned. The attribute
    names searched for include:

    * ``err_coords``: a mapping from coordinate names to indices
      (or a list of indices).
    * ``errors``: can be a dict mapping coordinate names to indices.
    * ``err_index_map``: a dictionary mapping coordinate names to
      indices.
    * ``error_coords`` or ``error_coordinates``: a list of coordinate
      names; the method returns the positions at which *coord_name*
      occurs.

    Parameters
    ----------
    coord_name : str
        The name of the coordinate to find indices for.

    Returns
    -------
    list[int]
        List of indices corresponding to *coord_name*.
    """
    # First, try attributes that map coordinate names to indices.
    for attr in ("err_coords", "errors", "err_index_map"):
        if hasattr(self, attr):
            mapping = getattr(self, attr)
            try:
                if isinstance(mapping, dict):
                    if coord_name in mapping:
                        val = mapping[coord_name]
                        # If value is iterable turn into list.
                        if isinstance(val, (list, tuple, set)):
                            return list(val)
                        try:
                            return [int(val)]
                        except Exception:
                            return [val]
                # If mapping is a list/tuple of tuples each with a name.
                if hasattr(mapping, "items"):
                    continue
            except Exception:
                continue

    # Next, try a simple list of coordinate names.
    for attribute in ("error_coords", "error_coordinates"):
        if hasattr(self, attribute):
            coord_list = getattr(self, attribute)
            try:
                indices = [i for i, name in enumerate(coord_list) if name == coord_name]
                if indices:
                    return indices
            except Exception:
                continue

    # As a last resort, if self has an ``errors`` list with named items,
    # attempt to find a matching entry.
    if hasattr(self, "errors") and isinstance(self.errors, list):
        try:
            indices = [i for i, err in enumerate(self.errors)
                       if getattr(err, "coord", None) == coord_name]
            if indices:
                return indices
        except Exception:
            pass

    # No match found; return empty list.
    return []

