def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    import numpy as np

    # Convert bins to array, preserve scalar case
    bins_arr = np.asarray(bins)
    # Determine if edges is 1D or ND
    edges_arr = np.asarray(edges)

    # 1D histogram case
    if edges_arr.ndim == 1:
        if bins_arr.ndim != 1 and not np.isscalar(bins_arr):
            raise ValueError("For 1-D edges, bins must be 1-D array or scalar.")
        widths = np.diff(edges_arr)
        if np.isscalar(bins_arr):
            return float(bins_arr * widths.sum())
        return float(np.sum(bins_arr * widths))

    # ND histogram case: edges should be sequence of arrays
    if isinstance(edges, (list, tuple)):
        edges_list = edges
    else:
        # If edges is numpy array with ndim >1, interpret as list of 1-D arrays per axis
        if edges_arr.ndim > 1:
            edges_list = [edges_arr[i] for i in range(edges_arr.shape[0])]
        else:
            raise ValueError("Edges must be a 1-D array or a sequence of 1-D arrays for ND histograms.")

    # Compute widths for each dimension
    widths = [np.diff(e) for e in edges_list]

    # Broadcast widths to match bins shape
    vol = widths[0]
    for w in widths[1:]:
        vol = np.multiply.outer(vol, w).reshape(*vol.shape, *w.shape)

    # Ensure volume array matches bins array shape
    if vol.shape != bins_arr.shape:
        # Try reshaping with broadcasting
        try:
            vol = np.broadcast_to(vol, bins_arr.shape)
        except ValueError:
            raise ValueError("Edges and bins shapes do not align for integration.")
    return float(np.sum(bins_arr * vol))

