        ValidationError: if the given value is not conform to the regular expression.
    """
    if not isinstance(value, (str, bytes)):
        raise ValidationError(f'Value must be a string or bytes, got {type(value).__name__}')

    if isinstance(value, bytes):
        try:
            value = value.decode('utf-8')
        except UnicodeDecodeError as exc:
            raise ValidationError(f'Byte string could not be decoded: {exc}') from exc

    pattern = globals().get('_VALIDATION_REGEX')
    if pattern is None:
        return

    try:
        regex = re.compile(pattern)
    except re.error as exc:
        raise ValidationError(f'Invalid validation regex: {pattern}') from exc

    if not regex.match(value):
        raise ValidationError(f'Value {value!r} does not match regex {pattern!r}')

def validate_value(value):
    """
    Validate the given value against the corresponding regular expression.

    Args:
        value: the string to validate

    Raises:
        ValidationError: if the given value is not conform to the regular expression.
    """
    import re

    # Accept both str and bytes inputs
    if isinstance(value, bytes):
        try:
            value = value.decode("utf-8")
        except Exception as exc:
            raise ValidationError(f"bytes could not be decoded as utf-8: {exc}")

    if not isinstance(value, str):
        raise ValidationError(f"Expected a string or bytes, got {type(value).__name__}")

    # Define the regular expression to validate against.
    # (Replace this pattern with the specific requirement as needed.)
    pattern = r"^[a-zA-Z0-9_]+$"

    try:
        regex = re.compile(pattern)
    except re.error as exc:
        raise ValidationError(f"Invalid regex pattern '{pattern}': {exc}")

    if not regex.fullmatch(value):
        raise ValidationError(f"'{value}' does not match the required pattern '{pattern}'")

def validate_key(key):
    """Validate the given key against the corresponding regular expression.

    Args:
        key: the string to validate

    Raises:
        ValidationError: if the given key is not conform to the regular expression.
    """
    import re

    if not isinstance(key, str):
        raise ValidationError("Key must be a string.")

    # Use a predefined regular expression if available, otherwise fall back to a default.
    try:
        pattern = KEY_REGEX
    except NameError:
        # Default pattern: 32 hexadecimal characters
        pattern = r'^[0-9a-fA-F]{32}$'

    try:
        if not re.fullmatch(pattern, key):
            raise ValidationError(f"Key '{key}' does not match the required pattern.")
    except re.error as exc:
        # Catch potential regex compilation errors
        raise ValidationError(f"Invalid regular expression: {exc}")

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Create a new dictionary from ``manifest_dict`` replacing all leaf values by ``None``.

    If ``first_level`` is ``True`` the scalar values of top‑level identifying
    fields (``apiVersion`` and ``kind``) are preserved.  All other non‑container
    values are replaced by ``None``.  Child dictionaries are processed
    recursively with ``first_level`` set to ``False``.
    """
    if not isinstance(manifest_dict, dict):
        raise TypeError('manifest_dict must be a dict')

    result = {}
    for key, value in manifest_dict.items():
        # Recursively handle nested dictionaries
        if isinstance(value, dict):
            result[key] = generate_default_observer_schema_dict(value, first_level=False)
            continue

        # For lists, return an empty list; the list processor will handle contents
        if isinstance(value, list):
            result[key] = []
            continue

        # Scalar values
        if first_level and key in ('apiVersion', 'kind'):
            # Preserve identifying fields at the top level
            result[key] = value
        else:
            result[key] = None
    return result

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    if app is None:
        raise ValueError("app must not be None")

    # Safely retrieve the manifest and observer_schema from the app spec.
    # We support both attribute and dict access styles.
    def _get_attr_or_key(container, key):
        if isinstance(container, dict):
            return container.get(key)
        return getattr(container, key, None)

    try:
        spec = getattr(app, "spec", None)
    except Exception:
        spec = None

    if spec is None:
        # No spec configured; nothing to do.
        return {}

    manifest = _get_attr_or_key(spec, "manifest")
    if manifest is None:
        # No manifest provided; nothing to do.
        return {}

    # `observer_schema` may not exist; create an empty dict if so.
    observer_schema = _get_attr_or_key(spec, "observer_schema") or {}

    # Ensure manifest is iterable: dict mapping resource names to objects.
    if not isinstance(manifest, dict):
        raise TypeError("app.spec.manifest should be a dict of resource names to resource definitions")

    # Iterate over resources and create defaults where missing.
    for res_name, res_obj in manifest.items():
        if res_name not in observer_schema:
            # Build a very minimal JSON‑Schema that includes the metadata fields `name`
            # and `namespace`.  This is the default shape that most observers will
            # need to match against.
            default_schema = {
                "metadata": {
                    "type": "object",
                    "properties": {
                        "name": {"type": "string"},
                        "namespace": {"type": "string"}
                    },
                    "required": ["name"]
                }
            }
            observer_schema[res_name] = default_schema

    return observer_schema

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Validate that the app has a spec with a manifest
    try:
        spec = app.spec
    except AttributeError:
        raise AttributeError("The provided `app` object must have a `spec` attribute")

    manifest = getattr(spec, "manifest", None)
    if manifest is None or not isinstance(manifest, list):
        raise AttributeError("`app.spec.manifest` must be a list of Kubernetes resource definitions")

    # Ensure there's a dictionary to hold observer schemas
    observer_schema = getattr(spec, "observer_schema", None)
    if observer_schema is None:
        observer_schema = {}
        setattr(spec, "observer_schema", observer_schema)

    for resource in manifest:
        if not isinstance(resource, dict):
            continue  # skip malformed entries

        kind = resource.get("kind")
        metadata = resource.get("metadata", {})
        name = metadata.get("name")
        namespace = metadata.get("namespace")

        # Skip resources that lack essential identifiers
        if not kind or not name:
            continue

        # Use a tuple of (kind, namespace, name) as the key
        key = (kind, namespace, name)

        # Only generate a default schema if one hasn't been set
        if key not in observer_schema:
            # Construct a minimal default observer schema that simply references the basic fields
            observer_schema[key] = {
                "kind": kind,
                "metadata": {
                    "name": name,
                    "namespace": namespace
                }
            }

    return observer_schema

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    Returns:
        dict: Mapping of resource identifiers to the generated default observer schema.
    """
    default_schemas = {}
    # Retrieve the list of manifests from the application spec
    try:
        manifests = getattr(app, "spec", {}).get("manifest", [])
    except Exception:
        return default_schemas

    # Determine any existing custom observer schemas
    try:
        custom_schemas = getattr(app.spec, "observers", {})
    except Exception:
        custom_schemas = {}

    for resource in manifests:
        if not isinstance(resource, dict):
            continue

        kind = resource.get("kind")
        metadata = resource.get("metadata", {})
        name = metadata.get("name")

        # Build a unique key for the resource
        key = f"{kind}/{name}" if name else kind
        if not key:
            continue

        # Skip if a custom observer schema is already defined
        if key in custom_schemas:
            continue

        # Construct a very basic default observer schema.  This schema
        # captures the most common fields that an observer might want to
        # track: namespace, labels, and spec contents.  For the purpose
        # of this generic implementation, we simply include the fields
        # that exist in the resource specification.
        default_schema = {"metadata": {}, "spec": {}}

        # Include namespace if present
        namespace = metadata.get("namespace")
        if namespace:
            default_schema["metadata"]["namespace"] = namespace

        # Include labels and annotations if present
        labels = metadata.get("labels")
        if isinstance(labels, dict):
            default_schema["metadata"]["labels"] = labels

        annotations = metadata.get("annotations")
        if isinstance(annotations, dict):
            default_schema["metadata"]["annotations"] = annotations

        # Include all spec fields from the resource
        spec = resource.get("spec")
        if isinstance(spec, dict):
            default_schema["spec"] = spec

        default_schemas[key] = default_schema

    return default_schemas

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Helper to recursively collect resources that look like a k8s manifest.
    def _collect_resources(node):
        resources = []
        if isinstance(node, dict):
            # If dict has apiVersion and kind, treat it as a resource definition.
            if "apiVersion" in node and "kind" in node:
                resources.append(node)
            # Recurse into values.
            for val in node.values():
                resources.extend(_collect_resources(val))
        elif isinstance(node, list):
            for item in node:
                resources.extend(_collect_resources(item))
        return resources

    if app is None:
        raise ValueError("Application must not be None")

    manifest = getattr(app, "spec", None)
    if manifest is None:
        raise AttributeError("Application has no 'spec' attribute")

    # The manifest should contain a 'manifest' key holding the resource definitions.
    raw_manifest = getattr(manifest, "manifest", None)
    if raw_manifest is None:
        # Try to use the spec itself as the manifest if 'manifest' key is missing.
        raw_manifest = manifest

    resources = _collect_resources(raw_manifest)

    # Default observer schema: we include the entire resource if no custom schema exists.
    default_schema = {"include": ["metadata"]}

    result = {}
    for resource in resources:
        kind = resource.get("kind")
        if not kind:
            continue
        name = resource.get("metadata", {}).get("name") or f"{kind}-no-name"
        key = f"{kind}:{name}"
        # If the app already has a custom observer schema for this key, skip.
        observers = getattr(app, "spec", None)
        if observers is not None:
            existing_obs = getattr(observers, "observers", {})
            if isinstance(existing_obs, dict) and key in existing_obs:
                continue
        result[key] = default_schema

    return result

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    try:
        # Extract the manifest list from the application specification
        manifest = getattr(app, "spec", None)
        if manifest is None:
            raise AttributeError("Application has no 'spec' attribute")

        resources = getattr(manifest, "manifest", None)
        if resources is None:
            raise AttributeError("Application spec has no 'manifest' attribute")

        # Ensure resources is an iterable of dictionaries
        if not hasattr(resources, "__iter__"):
            raise TypeError("spec.manifest should be iterable (e.g., a list of resource dicts)")

        # Retrieve existing observer schema mapping; create a new dict if missing
        observer_schema = getattr(app, "observer_schema", None)
        if observer_schema is None:
            observer_schema = {}

        # Populate default observer schemas for resources that lack a custom definition
        for resource in resources:
            if not isinstance(resource, dict):
                # Skip malformed entries
                continue
            kind = resource.get("kind")
            if not kind:
                continue  # Skip resources without a kind
            if kind in observer_schema:
                continue  # custom schema already provided
            # Default: an empty dict representing an empty schema
            observer_schema[kind] = {}

        # Persist the potentially updated schema back to the application object
        setattr(app, "observer_schema", observer_schema)

    except Exception as exc:  # pragma: no cover
        # Log the error and re-raise for visibility; logging is optional
        try:
            import logging
            logging.getLogger("krake").exception(
                "Failed to generate default observer schema: %s", exc
            )
        except Exception:
            pass  # If logging is not configured, silently ignore
        raise

