def validate(self, inventory, extract_spec_version=False):
        """Validate a given inventory.

        If extract_spec_version is True then will look at the type value to determine
        the specification version. In the case that there is no type value or it isn't
        valid, then other tests will be based on the version given in self.spec_version.
        """
        import re
        if inventory is None:
            raise ValueError("inventory must not be None")
        if not isinstance(inventory, dict):
            raise ValueError("inventory must be a dictionary")
        if extract_spec_version:
            type_val = inventory.get('type')
            if type_val is not None:
                if isinstance(type_val, str):
                    # try to extract a simple numeric version from the type string
                    parts = re.split(r'[^0-9.]', type_val)
                    parts = [p for p in parts if p]
                    if parts:
                        potential = parts[-1]
                        if re.fullmatch(r'\d+(\.\d+)*', potential):
                            self.spec_version = potential
        # If the class provides a detailed validation routine, run it.
        validate_method = getattr(self, "_run_validation", None)
        if callable(validate_method):
            validate_method(inventory)
        return inventory

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    if not isinstance(manifest_files, (list, tuple, set)):
        raise TypeError("manifest_files must be a list/tuple/set of entries")
    if not isinstance(digests_used, (list, tuple, set)):
        raise TypeError("digests_used must be a list/tuple/set of digest strings")

    used_set = set(digests_used)
    seen_digests = set()
    missing = []
    duplicate = []

    for entry in manifest_files:
        # Try to extract digest from known formats
        if isinstance(entry, dict):
            digest = entry.get("digest")
            if digest is None:
                raise ValueError(f"Entry dict missing 'digest' key: {entry}")
        elif isinstance(entry, (tuple, list)) and len(entry) == 2:
            # Assume (filename, digest)
            digest = entry[1]
        elif isinstance(entry, str):
            # Possibly a digest string itself
            digest = entry
        else:
            raise ValueError(f"Unsupported entry type: {entry!r}")

        if not isinstance(digest, str):
            raise ValueError(f"Digest must be a string, got {type(digest).__name__}")

        if digest in seen_digests:
            duplicate.append(digest)
        seen_digests.add(digest)

        if digest not in used_set:
            missing.append(digest)

    if missing:
        raise ValueError(f"Missing used digests: {', '.join(sorted(missing))}")
    if duplicate:
        raise ValueError(f"Duplicate digests found in manifest: {', '.join(sorted(duplicate))}")
    # If everything is fine, return None (or could return True)
    return None

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    if not isinstance(manifest_files, (list, tuple, set)):
