        for line in lines:
            digest = line.strip()
            if not digest:
                continue
            if digest not in digests_used_set:
                missing_digests.add(digest)

    if missing_files:
        raise FileNotFoundError("Missing manifest files: " + ", ".join(missing_files))
    if missing_digests:
        raise ValueError("Digests referenced in manifests but not used: " + ", ".join(sorted(missing_digests)))

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    errors = []

    # Basic type check
    try:
        import sys
        InventoryValidator = sys.modules[__name__].InventoryValidator
    except Exception:
        InventoryValidator = None
    if InventoryValidator is None:
        errors.append("Could not locate InventoryValidator class in current module")
    elif not isinstance(prior, InventoryValidator):
        errors.append("prior must be an InventoryValidator instance")

    # Compare inventory versioning if the attributes exist
    self_version = getattr(self, "inventory_version", None)
    prior_version = getattr(prior, "inventory_version", None)
    if self_version is None:
        errors.append("Current inventory missing 'inventory_version' attribute")
    if prior_version is None:
        errors.append("Prior inventory missing 'inventory_version' attribute")
    if self_version is not None and prior_version is not None:
        try:
            if prior_version >= self_version:
                errors.append(
                    f"Prior version ({prior_version}) is not older than "
                    f"current version ({self_version})"
                )
        except Exception as exc:
            errors.append(f"Comparison of inventory_version failed: {exc}")

    # Ensure prior inventory items are a subset of current
    self_inventory = getattr(self, "inventory", {})
    prior_inventory = getattr(prior, "inventory", {})
    if not isinstance(self_inventory, dict):
        errors.append("Current inventory's 'inventory' attribute must be a dict")
    if not isinstance(prior_inventory, dict):
        errors.append("Prior inventory's 'inventory' attribute must be a dict")
    if isinstance(self_inventory, dict) and isinstance(prior_inventory, dict):
        for key, prim_val in prior_inventory.items():
            if key not in self_inventory:
                errors.append(f"Key {key!r} in prior inventory is missing from current inventory")
            else:
                curr_val = self_inventory[key]
                if curr_val != prim_val:
                    errors.append(
                        f"Value for key {key!r} differs between current ({curr_val!r}) "
                        f"and prior ({prim_val!r}) inventories"
                    )

    if errors:
        raise ValueError("Prior inventory validation failed: " + "; ".join(errors))
    return True

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Basic sanity checks
    if prior is None:
        raise ValueError("prior must not be None")

    # Verify that prior is an InventoryValidator instance
    if not isinstance(prior, InventoryValidator):
        raise TypeError(
            f"prior must be an InventoryValidator instance, "
            f"got {type(prior).__name__}"
        )

    # Ensure both objects have an inventory attribute
    if not hasattr(self, "inventory") or self.inventory is None:
        raise AttributeError("Current object has no valid 'inventory' attribute")
    if not hasattr(prior, "inventory") or prior.inventory is None:
        raise AttributeError("Prior object has no valid 'inventory' attribute")

    # Optional: model or name consistency
    if hasattr(self, "model_name") and hasattr(prior, "model_name"):
        if self.model_name != prior.model_name:
            raise ValueError(
                f"model_name mismatch: current={self.model_name!r}, "
                f"prior={prior.model_name!r}"
            )

    # Version check – if available, the prior should be older
    if hasattr(self, "version") and hasattr(prior, "version"):
        try:
            if self.version <= prior.version:
                raise ValueError(
                    f"Current inventory version {self.version!r}"
                    f" must be greater than prior version {prior.version!r}"
                )
        except TypeError:
            # If the versions can't be compared, skip this check
            pass

    # Inventory subset check – prior's items must exist in the current inventory
    for key, prior_value in prior.inventory.items():
        if key not in self.inventory:
            raise ValueError(
                f"Prior inventory contains key {key!r} not found in current inventory"
            )
        current_value = self.inventory[key]
        # A basic equality check; adjust as needed for deep comparison
        if prior_value != current_value:
            raise ValueError(
                f"Inventory entry for key {key!r} differs between current "
                f"and prior inventories"
            )

def validate_as_prior_version(self, prior):
        """
        Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        # Ensure that the argument is of the same type
        if not isinstance(prior, type(self)):
            raise TypeError("prior must be an InventoryValidator instance")

        errors = []

        # Attributes that should match between inventories
        attrs = ['parameters', 'species', 'constraints', 'priors']

        for attr in attrs:
            try:
                self_vals = getattr(self, attr)
                prior_vals = getattr(prior, attr)
            except AttributeError:
                # If the attribute is missing in either, skip checking
                continue

            # For sets of symbols
            if isinstance(self_vals, set) and isinstance(prior_vals, set):
                if not prior_vals <= self_vals:
                    missing = prior_vals - self_vals
                    errors.append(
                        f"Prior contains {attr} symbols not in current inventory: {sorted(missing)}"
                    )
            # For dictionaries (e.g., mappings of indices to constraints or priors)
            elif isinstance(self_vals, dict) and isinstance(prior_vals, dict):
                if not prior_vals.keys() <= self_vals.keys():
                    missing = set(prior_vals.keys()) - set(self_vals.keys())
                    errors.append(
                        f"Prior contains keys in {attr} not in current inventory: {sorted(missing)}"
                    )
            # Generic iterable comparison
            else:
                try:
                    if not set(prior_vals).issubset(set(self_vals)):
                        missing = set(prior_vals) - set(self_vals)
                        errors.append(
                            f"Prior contains {attr} items not in current inventory: {sorted(missing)}"
                        )
                except Exception:
                    # If conversion to set fails, skip this attribute
                    pass

        if errors:
            raise ValueError("Invalid prior version: " + "; ".join(errors))

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if inventory is None:
        raise ValueError("inventory must not be None")
    if version is None:
        raise ValueError("version must not be None")

    path_map = {}

    try:
        # inventory is expected to be an iterable of mappings
        for item in inventory:
            try:
                # Ensure the item is a mapping
                if not isinstance(item, (dict,)):
                    continue

                item_version = item.get("version")
                if item_version != version:
                    continue

                logical_path = item.get("logical_path")
                content_file = item.get("content_file")

                if logical_path is None or content_file is None:
                    continue

                path_set = path_map.setdefault(logical_path, set())
                path_set.add(content_file)

            except Exception:
                # Skip any malformed entries
                continue
    except TypeError:
        raise ValueError("inventory must be an iterable of mapping objects")

    return path_map

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for `version` in `inventory`.

    Parameters
    ----------
    inventory : mapping or iterable
        The collection that represents the inventory. It can be a dictionary
        that maps ``version`` to a mapping of ``logical_path`` → ``content_files``
        or a list/tuple of records that each contain ``version``,
        ``logical_path`` and ``content_file`` keys.

    version : str
        The version to retrieve the mapping for.

    Returns
    -------
    dict
        Mapping of ``logical_path_in_state`` to a set of ``content_files``.
    """
    if isinstance(inventory, dict):
        # If the dictionary keys are version numbers, use the value for the
        # requested version. The value can itself be a mapping or a list of
        # record objects.
        raw = inventory.get(version)
        if raw is None:
            # No record for this version – return an empty mapping.
            return {}
        if isinstance(raw, dict):
            mapping = {}
            for logical_path, files in raw.items():
                if isinstance(files, (list, set, tuple)):
                    mapping[logical_path] = set(files)
                else:
                    mapping[logical_path] = {files}
            return mapping
        if isinstance(raw, (list, tuple)):
            mapping = {}
            for rec in raw:
                if isinstance(rec, dict):
                    if rec.get('version') != version:
                        continue
                    if 'logical_path' in rec and 'content_file' in rec:
                        lp = rec['logical_path']
                        cf = rec['content_file']
                        mapping.setdefault(lp, set()).add(cf)
            return mapping
        # Unsupported value type for the given version
        raise ValueError("Inventory entry for version '%s' is of unsupported type." % version)

    # Treat a plain list/tuple as a collection of records.
    if isinstance(inventory, (list, tuple)):
        mapping = {}
        for rec in inventory:
            if isinstance(rec, dict):
                if rec.get('version') != version:
                    continue
                if 'logical_path' in rec and 'content_file' in rec:
                    lp = rec['logical_path']
                    cf = rec['content_file']
                    mapping.setdefault(lp, set()).add(cf)
        return mapping

    raise TypeError("Unsupported inventory type (%s)" % type(inventory).__name__)

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")
    if version is None:
        raise ValueError("version must be specified")

    # Retrieve mapping for the requested version; if missing, return empty dict
    mapping = inventory.get(version, {})
    if not isinstance(mapping, dict):
        raise TypeError(f"inventory[{version!r}] must be a dictionary")

    # Ensure all values are sets (converting any iterable to a set)
    logical_map = {}
    for logical_path, content_files in mapping.items():
        if isinstance(content_files, set):
            logical_map[logical_path] = content_files
        else:
            # Accept list, tuple, or other iterables
            try:
                logical_map[logical_path] = set(content_files)
            except TypeError:
                # If not iterable, wrap in a single-element set
                logical_map[logical_path] = {content_files}

    return logical_map

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Result dictionary
    path_map = {}

    # Defensive: handle None inventory
    if inventory is None:
        return path_map

    # Inventory could be:
    # 1. An iterable of records (dicts) each with 'logical_path', 'content_file', 'version'.
    # 2. A mapping of logical_path -> iterable of records or filenames.
    # We'll try to normalise to an iterable of record dicts.
    records = []

    # Case 2: dict with logical paths as keys
    if isinstance(inventory, dict):
        # If all values are iterable of dicts/strings, treat as such
        for key, val in inventory.items():
            # If val is a string or dict with 'content_file', wrap
            if isinstance(val, dict):
                # Might be a single record
                records.append(val)
            elif isinstance(val, (list, tuple)):
                # Might be a list of records or filenames
                for item in val:
                    if isinstance(item, dict):
                        records.append(item)
                    else:
                        # treat as a content_file with inferred logical_path
                        records.append({
                            'logical_path': key,
                            'content_file': item,
                        })
            else:
                # Treat val as content_file
                records.append({
                    'logical_path': key,
                    'content_file': val,
                })
    else:
        # Assume inventory is an iterable of dicts
        try:
            iter(inventory)
            for r in inventory:
                if isinstance(r, dict):
                    records.append(r)
                else:
                    # ignore non-dict entries
                    continue
        except TypeError:
            # Not iterable
            pass

    # Process each record
    for rec in records:
        # Extract logical_path
        logical_path = rec.get('logical_path')
        if not logical_path:
            # If the record itself is a string or list, skip
            continue

        # Check version match if specified
        rec_version = rec.get('version')
        if version is not None and rec_version != version:
            # Skip record that does not match the requested version
            continue

        # Get the content file
        content_file = rec.get('content_file')
        if content_file is None:
            # No content file to map
            continue

        # Add to map
        path_map.setdefault(logical_path, set()).add(content_file)

    return path_map

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if version is None:
        raise ValueError("version must be specified")

    # Normalize inventory to an iterable of mapping-like objects.
    try:
        iterator = iter(inventory)
    except TypeError:
        raise TypeError("inventory must be an iterable of mapping-like objects")

    path_map = {}
    for item in iterator:
        # Ensure the item is a mapping or has attribute access.
        try:
            record = dict(item)
        except Exception:
            # Skip items that cannot be converted to dict
            continue

        if 'logical_path' not in record or 'content_file' not in record or 'version' not in record:
            # Skip records that do not contain the expected keys
            continue

        # Compare versions safely by converting to string.
        try:
            if str(record['version']) != str(version):
                continue
        except Exception:
            continue

        logical = record['logical_path']
        content = record['content_file']

        if logical is None or content is None:
            continue

        if logical not in path_map:
            path_map[logical] = set()
        path_map[logical].add(content)

    return path_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not fixity:
        # Empty or None is acceptable; nothing to validate
        return

    if not isinstance(fixity, dict):
        raise ValueError(f"Fixity block must be a dict, got {type(fixity).__name__}")

    # Allow optional top‑level keys that are not file references
    known_keys = {"algorithm", "files"}
    # If the structure follows the pattern {"algorithm": "...", "files": {...}}
    if "files" in fixity:
        # Normalise to the dictionary of per‑file metadata
        files_meta = fixity["files"]
    else:
        files_meta = fixity

    if not isinstance(files_meta, dict):
        raise ValueError("The 'files' entry in the fixity block must be a dict")

    for fname, meta in files_meta.items():
        if fname not in manifest_files:
            raise ValueError(f"Fixity references unknown file '{fname}'")
        if not isinstance(meta, dict):
            raise ValueError(f"Metadata for file '{fname}' must be a dict, got {type(meta).__name__}")

        # Common expected keys; adjust as necessary
        required_keys = {"hash", "size"}
        missing = required_keys - meta.keys()
        if missing:
            raise ValueError(f"Metadata for file '{fname}' missing required key(s): {', '.join(sorted(missing))}")

        if not isinstance(meta["hash"], str):
            raise ValueError(f"Hash for file '{fname}' must be a string")
        if not isinstance(meta["size"], int):
            raise ValueError(f"Size for file '{fname}' must be an integer")

    # If the block contains keys besides known ones or file entries, ensure they're valid
    for key in fixity.keys() - known_keys:
        if key == "files":
            continue
        # Unexpected top‑level key
        raise ValueError(f"Unexpected key in fixity block: '{key}'")
    return

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Sanity checks for input types
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary mapping file paths to checksums")
    if manifest_files is None:
        manifest_set = set()
    else:
        try:
            manifest_set = set(manifest_files)
        except TypeError:
            raise ValueError("manifest_files must be an iterable of file paths")

    for path, checksum in fixity.items():
        # Validate key
        if not isinstance(path, str):
            raise ValueError(f"Fixity key must be a string file path, got {type(path).__name__}")
        if path not in manifest_set:
            raise ValueError(f"File '{path}' referenced in fixity block is not in the manifest")

        # Validate checksum
        if not isinstance(checksum, str):
            raise ValueError(f"Checksum for '{path}' must be a string, got {type(checksum).__name__}")
        # Basic hex validation
        if not all(c in "0123456789abcdefABCDEF" for c in checksum):
            raise ValueError(f"Checksum for '{path}' is not a valid hexadecimal string")
        if checksum == "":
            raise ValueError(f"Checksum for '{path}' cannot be empty")
    # If no exception raised, the fixity block is valid
    return True

def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        if not isinstance(fixity, dict):
            raise ValueError("Fixity block must be a dictionary, got %r" % type(fixity).__name__)

        if 'hashes' not in fixity:
            raise ValueError("Fixity block missing required 'hashes' key")

        hashes = fixity['hashes']
        if not isinstance(hashes, dict):
            raise ValueError("'hashes' entry must be a dictionary, got %r" % type(hashes).__name__)

        # Accept any iterable of manifest file names; normalise to a set for fast lookup
        try:
            manifest_set = set(manifest_files)
        except TypeError:
            raise ValueError("'manifest_files' must be an iterable of file names")

        # Ensure every file referenced in the fixity block exists in the manifest
        missing_files = [fname for fname in hashes if fname not in manifest_set]
        if missing_files:
            raise ValueError("Fixity references files not present in manifest: %s"
                             % ", ".join(missing_files))

        # Validate each checksum: must be a non‑empty string
        for fname, checksum in hashes.items():
            if not isinstance(checksum, str) or checksum.strip() == "":
                raise ValueError("Invalid checksum for file '%s': must be a non‑empty string" % fname)

def files_list(path):
    """
    Return the files in `path`
    """
    abs_path = os.path.abspath(path)
    if not os.path.exists(abs_path):
        raise FileNotFoundError(f"No such file or directory: '{path}'")
    if os.path.isfile(abs_path):
        return [abs_path]
    if os.path.isdir(abs_path):
        try:
            return [
                os.path.join(abs_path, entry)
                for entry in os.listdir(abs_path)
                if os.path.isfile(os.path.join(abs_path, entry))
            ]
        except OSError as e:
            raise e
    raise ValueError(f"Unsupported path type: '{path}'")

def files_list(path):
    """Return the files in `path`."""
    import os
    if path is None:
        raise TypeError("Path must not be None")
    if not os.path.exists(path):
        raise FileNotFoundError(f"No such file or directory: '{path}'")
    if os.path.isfile(path):
        return [os.path.abspath(path)]
    if os.path.isdir(path):
        files = []
        for root, dirs, filenames in os.walk(path):
            for fname in filenames:
                files.append(os.path.join(root, fname))
        return sorted([os.path.abspath(p) for p in files])
    raise OSError(f"Unsupported path type: '{path}'")

def files_list(path):
    """Return the files in `path`"""
    import os
    if not path:
