def files_list(path):
    """
    Return the files in `path`
    """
    import os
    # Validate that the input is a string-like path
    if not isinstance(path, (str, bytes)):
        raise TypeError(f"Expected a string path, got {type(path).__name__}")
    # Resolve to absolute path for consistency
    abs_path = os.path.abspath(path)
    # Check existence
    if not os.path.exists(abs_path):
        raise FileNotFoundError(f"Path does not exist: {abs_path}")
    # If it's a single file, return it
    if os.path.isfile(abs_path):
        return [abs_path]
    # If it's a directory, list all files inside (non-recursive)
    if os.path.isdir(abs_path):
        files = []
        try:
            for entry in os.listdir(abs_path):
                full = os.path.join(abs_path, entry)
                if os.path.isfile(full):
                    files.append(os.path.abspath(full))
        except OSError as exc:
            # Surface any OS-related errors
            raise RuntimeError(f"Error accessing directory {abs_path}: {exc}") from exc
        return files
    # Fallback: path is neither file nor directory (shouldn't happen)
    raise ValueError(f"Unsupported path type: {abs_path}")

