def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os

    if not isinstance(folder, str):
        raise TypeError("folder must be a string path")
    if not os.path.isdir(folder):
        raise ValueError(f"Provided folder does not exist or is not a directory: {folder}")

    packages = {}
    xml_bases = set()

    # First pass: discover all XML files and initialize groups
    for root, _, files in os.walk(folder):
        for filename in files:
            if filename.lower().endswith('.xml'):
                base = os.path.splitext(filename)[0]
                xml_bases.add(base)
                rel_path = os.path.relpath(os.path.join(root, filename), folder)
                packages.setdefault(base, []).append(rel_path)

    # Second pass: add non-XML files that share an XML basename
    for root, _, files in os.walk(folder):
        for filename in files:
            if filename.lower().endswith('.xml'):
                continue
            base = os.path.splitext(filename)[0]
            if base in xml_bases:
                rel_path = os.path.relpath(os.path.join(root, filename), folder)
                packages[base].append(rel_path)

    # Optional: sort files within each package for deterministic output
    for base in packages:
        packages[base] = sorted(packages[base])

    return packages

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os
    import collections

    # Validate input
    if not isinstance(folder, str):
        raise TypeError(f"'folder' must be a str, got {type(folder).__name__}")
    if not os.path.isdir(folder):
        raise FileNotFoundError(f"Directory not found: {folder}")

    # First pass: find all XML files and collect their base names
    xml_basenames = set()
    try:
        with os.scandir(folder) as it:
            for entry in it:
                if entry.is_file():
                    _, ext = os.path.splitext(entry.name)
                    if ext.lower() == ".xml":
                        base = os.path.splitext(entry.name)[0]
                        xml_basenames.add(base)
    except OSError as exc:
        raise RuntimeError(f"Failed to scan directory {folder}") from exc

    # Second pass: group all files by the XML basename
    grouped = collections.defaultdict(list)
    try:
        with os.scandir(folder) as it:
            for entry in it:
                if entry.is_file():
                    base = os.path.splitext(entry.name)[0]
                    if base in xml_basenames:
                        grouped[base].append(entry.path)
    except OSError as exc:
        raise RuntimeError(f"Failed to scan directory {folder}") from exc

    return dict(grouped)

def _eval_file(prefix, file_path):
    """
    Identifica o tipo de arquivo do pacote: `asset` ou `rendition`.

    Identifica o tipo de arquivo do pacote e atualiza `packages` com o tipo e
    o endereço do arquivo em análise.

    Parameters
    ----------
    prefix : str
        nome do arquivo XML sem extensão
    file_path : str
        caminho completo do arquivo

    Returns
    -------
    dict
        Dicionário com a chave 'prefix' contendo um subdicionário com as chaves
        'type' (asset ou rendition) e 'filepath' (caminho completo). Por
        exemplo:
        {
            'myfile': {
                'type': 'asset',
                'filepath': '/caminho/para/myfile.asset.xml'
            }
        }
    """
    if not prefix or not isinstance(prefix, str):
        raise ValueError("prefix deve ser uma string válida")
    if not file_path or not isinstance(file_path, str):
        raise ValueError("file_path deve ser uma string válida")

    # Extrai o nome do arquivo para analisar se contém 'asset' ou 'rendition'
    base_name = file_path.split("/")[-1].lower()

    if "asset" in base_name:
        file_type = "asset"
    elif "rendition" in base_name:
        file_type = "rendition"
    else:
        # Caso o arquivo não contenha nenhuma das palavras-chave esperadas,
        # tenta derivar a partir do prefixo
        if prefix.lower() in base_name:
            # Se o prefixo for 'asset' ou 'rendition' podemos assumir
            if "asset" in prefix.lower():
                file_type = "asset"
            elif "rendition" in prefix.lower():
                file_type = "rendition"
            else:
                raise ValueError(
                    f"Tipo de arquivo desconhecido para {file_path}"
                )
        else:
            raise ValueError(
                f"Tipo de arquivo desconhecido para {file_path}"
            )

    # Retorna o dicionário conforme especificado
    return {
        prefix: {
            "type": file_type,
            "filepath": file_path,
        }
    }

def _eval_file(prefix, file_path):
    """
    Identifica o tipo de arquivo do pacote: `asset` ou `rendition`.

    Identifica o tipo de arquivo do pacote e atualiza `packages` com o tipo e
    o endereço do arquivo em análise.

    Parameters
    ----------
    prefix : str
        nome do arquivo XML sem extensão
    file_path : str
        caminho completo do arquivo (ou do diretório contendo o arquivo)

    Returns
    -------
    dict
        dicionário contendo:
            * ``prefix``  – nome do arquivo XML sem extensão
            * ``file_path`` – caminho absoluto do arquivo encontrado
            * ``type`` – ``asset`` ou ``rendition`` (ou ``unknown``)
    """
    import os

    if not isinstance(prefix, str) or not isinstance(file_path, str):
        raise TypeError("prefix and file_path must be strings")

    # Normalizamos o caminho do arquivo
    abs_path = os.path.abspath(file_path)

    # Se o caminho passado não existir, tentamos encontrar o arquivo
    # dentro de diretórios usuais, levando em conta a nomenclatura do prefixo.
    if not os.path.exists(abs_path):
        # Possível diretório contendo os arquivos
        base_dir = os.path.dirname(abs_path)
        if not os.path.isdir(base_dir):
            # Tenta (1) prefixo + .asset, (2) prefixo + .rendition
            alternatives = [
                os.path.join(base_dir, f"{prefix}.asset"),
                os.path.join(base_dir, f"{prefix}.rendition"),
            ]
            for alt in alternatives:
                if os.path.isfile(alt):
                    abs_path = alt
                    break
        else:
            # Busca em subdiretórios
            for root, _, files in os.walk(base_dir):
                for f in files:
                    if f.startswith(prefix):
                        abs_path = os.path.join(root, f)
                        break
                if os.path.isfile(abs_path):
                    break

    # Se ainda não existir, ele continua como desconhecido
    if not os.path.isfile(abs_path):
        file_type = "unknown"
    else:
        # Determina o tipo a partir da extensão ou nome
        _, ext = os.path.splitext(abs_path)
        if ext.lower() in {".asset", ".zip"}:
            file_type = "asset"
        elif ext.lower() in {".rendition", ".zip"}:
            # Se o nome do arquivo contém "rendition"
            if "rendition" in os.path.basename(abs_path).lower():
                file_type = "rendition"
            else:
                # Pode ser que seja asset mas com extensão zip; tentamos inferir a partir do nome
                file_type = "asset"
        elif "asset" in os.path.basename(abs_path).lower():
            file_type = "asset"
        elif "rendition" in os.path.basename(abs_path).lower():
            file_type = "rendition"
        else:
            # Se o diretório pai contém asset ou rendition
            dir_name = os.path.basename(os.path.dirname(abs_path)).lower()
            if "asset" in dir_name:
                file_type = "asset"
            elif "rendition" in dir_name:
                file_type = "rendition"
            else:
                file_type = "unknown"

    result = {
        "prefix": prefix,
        "file_path": abs_path,
        "type": file_type,
    }

    return result

