def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    if not isinstance(zip_path, (str, bytes)):
        raise TypeError("zip_path must be a string representing a file path")
    result = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zin:
            for zinfo in zin.infolist():
                if zinfo.is_dir():
                    continue  # skip directories
                name = zinfo.filename
                # compute basename without extension (only use the last component)
                base = os.path.splitext(os.path.basename(name))[0]
                if base not in result:
                    result[base] = {}
                # read file content; keep as bytes
                try:
                    content = zin.read(name)
                except RuntimeError as e:
                    # Capture read errors and continue
                    content = None
                result[base][name] = content
    except FileNotFoundError:
        raise FileNotFoundError(f"Zip file not found: {zip_path}")
    except zipfile.BadZipFile as e:
        raise zipfile.BadZipFile(f"Bad zip file: {zip_path}") from e
    except Exception as e:
        # Generic exception fallback
        raise RuntimeError(f"Failed to explore zip file '{zip_path}': {e}") from e
    return result

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
        A dictionary where each key is the basename of an .xml file (without extension)
        and each value is a list of dictionaries describing the files that belong to that
        package.  Each dictionary contains:
            * 'path': the full path inside the zip archive
            * 'content': the raw bytes of the file
    """
    import os
    import zipfile

    package_data = {}

    try:
        with zipfile.ZipFile(zip_path, 'r') as zin:
            for zinfo in zin.infolist():
                if zinfo.is_dir():
                    continue

                file_path = zinfo.filename
                try:
                    file_content = zin.read(zinfo)
                except Exception as exc:
                    # If a file cannot be read, skip it but record the error for debugging.
                    file_content = None

                # Determine the package key: the basename of the first .xml file found
                # within the same path or, if none, a generic key based on file_path.
                base_name = None
                # Look for an .xml file in the same directory hierarchy
                dir_path = os.path.dirname(file_path)
                for candidate in zin.infolist():
                    if candidate.is_dir():
                        continue
                    if os.path.dirname(candidate.filename) != dir_path:
                        continue
                    if candidate.filename.lower().endswith('.xml'):
                        base_name = os.path.splitext(os.path.basename(candidate.filename))[0]
                        break

                # Fallback to using the file's own basename if no .xml was found
                if not base_name:
                    base_name = os.path.splitext(os.path.basename(file_path))[0]

                entry = {
                    'path': file_path,
                    'content': file_content
                }
                package_data.setdefault(base_name, []).append(entry)

    except FileNotFoundError:
        raise FileNotFoundError(f"Zip file '{zip_path}' not found.")
    except zipfile.BadZipFile:
        raise zipfile.BadZipFile(f"File '{zip_path}' is not a valid zip archive.")
    except Exception as exc:
        # Generic fallback for unexpected errors
        raise RuntimeError(f"Unexpected error while exploring '{zip_path}': {exc}") from exc

    return package_data

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
        Mapping from XML base name to a dictionary of file names and their binary contents.
    """
    if not zip_path:
        return {}

    result = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            # First pass: collect all XML entries and initialize groups
            for zinfo in zf.infolist():
                if zinfo.is_dir():
                    continue
                if zinfo.filename.lower().endswith('.xml'):
                    base = os.path.splitext(os.path.basename(zinfo.filename))[0]
                    if base not in result:
                        result[base] = {}
                    data = zf.read(zinfo.filename)
                    result[base][zinfo.filename] = data

            # Second pass: add non-XML entries to the appropriate group if base matches
            for zinfo in zf.infolist():
                if zinfo.is_dir():
                    continue
                if zinfo.filename.lower().endswith('.xml'):
                    continue
                name = zinfo.filename
                base = os.path.splitext(os.path.basename(name))[0]
                if base in result:
                    data = zf.read(name)
                    # Avoid overwriting existing entry if duplicate key
                    if name not in result[base]:
                        result[base][name] = data
        return result
    except (OSError, zipfile.BadZipFile):
        # Return empty dict on any failure to read the zip file
        return {}

def files_list_from_zipfile(zip_path):
    """Return the files in `zip_path`."""
    try:
        import zipfile
        with zipfile.ZipFile(zip_path, 'r') as zf:
            # Filter out directory entries (ending with '/') and optional .pyc files
            return [name for name in zf.namelist()
                    if not name.endswith('/') and not name.endswith('.pyc')]
    except FileNotFoundError:
        raise FileNotFoundError(f"Zip file not found: {zip_path}")
    except zipfile.BadZipFile:
        raise zipfile.BadZipFile(f"Cannot read zip file: {zip_path}")

