def _extract_number_and_supplment_from_issue_element(issue):
    """
    Extrai do conteúdo de <issue>xxxx</issue>, os valores number e suppl.
    Valores possíveis
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl. 1,
    25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
    s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, suppl,
    suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """
    try:
        # Get the textual content from the issue element or string
        text = getattr(issue, "text", None)
        if text is None:
            text = str(issue)
        if not text:
            return (None, None)

        # Normalise text
        text = text.strip()
        if not text:
            return (None, None)

        import re

        # Lowercase and remove periods to simplify tokenization
        lowered = text.lower()
        cleaned = re.sub(r"\.", "", lowered)
        tokens = re.split(r"\s+", cleaned)

        number = None
        suppl = None
        pending_suppl = False

        for token in tokens:
            if not token:
                continue

            # Handle tokens like 's2', 's12-14'
            m = re.match(r"^s(\d+(?:-\d+)?)$", token)
            if m:
                suppl = m.group(1)
                pending_suppl = False
                continue

            # Handle explicit supplement keywords
            if token in ("suppl", "supl", "supp", "suppl", "spe", "spepr"):
                pending_suppl = True
                continue

            # Handle numeric tokens
            if re.match(r"^\d+(?:-\d+)?$", token):
                if pending_suppl and suppl is None:
                    suppl = token
                    pending_suppl = False
                elif number is None:
                    number = token

        return (number, suppl)
    except Exception:
        # On any unexpected error, return None values
        return (None, None)

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.

    Args:
        indent (int, optional): The indentation level for output. Default is 0.
        debug (bool, optional): If True, return the raw repr of the object.
            Otherwise, attempt a human‑readable JSON or pprint representation.

    Returns:
        str: A string containing a pretty printed representation of ``self``.
    """
    if debug:
        return repr(self)

    # Try to serialize using json; this works well for dicts, lists, tuples, etc.
    try:
        import json

        def _default(o):
            try:
                return o.__dict__
            except Exception:
                # Fallback to str for complex objects
                return str(o)

        # Ensure indent is a non‑negative integer
        _indent = max(int(indent), 0) if indent is not None else None
        return json.dumps(self, default=_default, indent=_indent, sort_keys=True)
    except Exception:
        pass

    # Fall back to pprint if json fails.
    try:
        import pprint
        return pprint.pformat(self, indent=indent)
    except Exception:
        # As a last resort, return repr.
        return repr(self)

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.

    Parameters
    ----------
    indent : int, optional
        Number of spaces to indent each line (default 0). Must be a
        non‑negative integer.
    debug : bool, optional
        If True, include a more verbose representation that shows
        attribute names and their values.  Default is False.

    Returns
    -------
    str
        A human readable string representation of the object.
    """
    # Validate the `indent` argument
    try:
        indent = int(indent)
    except Exception:
        indent = 0
    if indent < 0:
        indent = 0
    ind_str = " " * indent

    # Helper to format a single attribute
    def _format_attr(name, value):
        try:
            val = repr(value)
        except Exception:
            val = "<unrepresentable object>"
        return f"{ind_str}{name} = {val}"

    # Main representation logic
    if debug:
        attrs = {}
        # Prefer direct __dict__ if present
        try:
            attrs = vars(self)
        except Exception:
            pass
        # If no __dict__, fall back to dir filtering
        if not attrs:
            for name in dir(self):
                if name.startswith("_"):
                    continue
                try:
                    attrs[name] = getattr(self, name)
                except Exception:
                    attrs[name] = "<unreadable>"
        lines = [_format_attr(k, v) for k, v in sorted(attrs.items())]
        if not lines:
            lines = [f"{ind_str}<object of type {type(self).__name__} has no public attributes>"]
        return "\n".join(lines)
    else:
        # Non‑debug: simple one‑liner representation
        try:
            content = repr(self)
        except Exception:
            content = "<unrepresentable object>"
        return content

def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    # Obtain a basic string representation
    raw_repr = pprint_plain(self)
    # Nicely indent multiline representations
    lines = raw_repr.splitlines()
    if len(lines) > 1 and indent > 0:
        ind = ' ' * indent
        formatted = lines[0] + '\n' + '\n'.join(ind + line for line in lines[1:])
    else:
        formatted = raw_repr
    if debug:
        print(formatted)
    return formatted

def pprint_plain(obj):
    """Return a plain string representation, handling common containers."""
    if isinstance(obj, (dict, list, tuple, set)):
        try:
            import json
            return json.dumps(obj, indent=4, default=lambda o: str(o))
        except Exception:
            pass
    try:
        return repr(obj)
    except Exception:
        return str(obj)

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    try:
        import sympy
    except ImportError:
        # Fallback: if sympy is not available, return the original list.
        return list(args)

    result = []
    for expr in args:
        # Prepare a sympy expression from the input, if it is a string.
        expr_sym = expr
        try:
            if isinstance(expr, str):
                expr_sym = sympy.sympify(expr)
        except Exception:
            # If parsing fails, keep original.
            expr_sym = expr

        try:
            simplified = sympy.simplify(expr_sym)
        except Exception:
            # If simplification fails, keep original.
            simplified = expr

        result.append(simplified)

    return result

