def base_config(user, etcd_host="localhost", etcd_port=2379):
    """Creates a configuration with some simple parameters, which have a default value
    that can be set.

    Args:
        user (str): the name of the user for the static authentication
        etcd_host (str): the host for the database.
        etcd_port (int): the port for the database.

    Returns:
        dict: the created configuration.

    """
    # Validate input types
    if not isinstance(user, str):
        raise TypeError(f"user must be a string, got {type(user).__name__}")
    if not isinstance(etcd_host, str):
        raise TypeError(f"etcd_host must be a string, got {type(etcd_host).__name__}")
    if not isinstance(etcd_port, int):
        raise TypeError(f"etcd_port must be an integer, got {type(etcd_port).__name__}")

    # Validate port range
    if not (1 <= etcd_port <= 65535):
        raise ValueError(f"etcd_port {etcd_port} is out of valid range 1-65535")

    config = {
        "user": user,
        "etcd": {
            "host": etcd_host,
            "port": etcd_port
        }
    }
    return config

def _fromutc(self, dt):
        """Given a timezone-aware datetime in a given timezone, calculates a
        timezone-aware datetime in this timezone.

        Since this is the one time that we *know* we have an unambiguous
        datetime object, we take this opportunity to determine whether the
        datetime is ambiguous and in a "fold" state (e.g. if it's the first
        occurrence, chronologically, of the ambiguous datetime).

        :param dt: A timezone-aware :class:`datetime.datetime` object.
        :return: A timezone-aware :class:`datetime.datetime` in this timezone.
        """
        if not isinstance(dt, datetime):
            raise TypeError("dt must be a datetime instance")
        if dt.tzinfo is None:
            raise ValueError("dt must be timezone-aware")

        # If the datetime is already in this timezone, just return it
        if dt.tzinfo is self:
            result = dt
        else:
            try:
                # Convert to this timezone
                result = dt.astimezone(self)
            except Exception as exc:
                # Fall back to manual offset calculation if astimezone fails
                offset = self.utcoffset(dt.replace(tzinfo=None))
                if offset is None:
                    raise
                naive = dt.replace(tzinfo=None)
                result = naive + offset
                result = result.replace(tzinfo=self)

        # Determine fold (ambiguous DST transition)
        if hasattr(self, "is_ambiguous") and callable(getattr(self, "is_ambiguous")):
            try:
                is_ambig = self.is_ambiguous(result.replace(tzinfo=None))
                if is_ambig:
                    # Preserve the original fold value if present
                    fold_val = getattr(dt, "fold", 0)
                    try:
                        result = result.replace(fold=fold_val)
                    except TypeError:
                        # Some datetime implementations may not support fold replacement
                        pass
            except Exception:
                # If is_ambiguous fails, ignore
                pass

        return result

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def wrapper(*args, **kwargs):
        result = namefunc(*args, **kwargs)
        import sys
        if sys.version_info[0] >= 3:
            return result
        else:
            # In Python 2, unicode type is called 'unicode'
            try:
                unicode_type = unicode
            except NameError:
                unicode_type = str  # fallback, unlikely
            if isinstance(result, unicode_type):
                return result.encode()
            return result
    return wrapper

