def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    import sys
    def inner_func(*args, **kwargs):
        # Python 3 already returns unicode strings from tzname, so pass through.
        if sys.version_info[0] == 3:
            return namefunc(*args, **kwargs)
        # In Python 2 tzname may return unicode; convert to bytes.
        result = namefunc(*args, **kwargs)
        # If the result is a unicode string, encode it to bytes.
        try:
            # In Python 2, 'unicode' is a built-in type.
            if isinstance(result, unicode):  # type: ignore
                return result.encode('utf-8')
        except NameError:
            # 'unicode' not defined in Python 3, but this branch won't be reached.
            pass
        return result
    return inner_func

