def get_versions():
    """Get version information or return default if unable to do so."""
    import os
    import re

    # Default value if any lookup fails
    default_version = "unknown"

    # Determine the directory of this file if possible
    try:
        current_dir = os.path.dirname(os.path.abspath(__file__))
    except NameError:
        current_dir = os.getcwd()

    # Candidate files that might contain version info
    candidate_files = ["__init__.py", "version.py", "VERSION", "setup.cfg", "pyproject.toml", "setup.py"]

    for filename in candidate_files:
        filepath = os.path.join(current_dir, filename)
        if not os.path.isfile(filepath):
            continue
        try:
            with open(filepath, "r", encoding="utf-8") as fh:
                content = fh.read()
        except (OSError, IOError):
            continue

        # Look for a __version__ or version variable assignment
        match = re.search(
            r"""(?m)^\s*(?:__version__|version)\s*=\s*['"]([^'"]+)['"]""",
            content,
        )
        if match:
            return match.group(1)

        # For setup.cfg or pyproject.toml or setup.py, look for a line like 'version = "1.2.3"'
        inline_match = re.search(
            r"""(?m)^\s*version\s*=\s*['"]([^'"]+)['"]""",
            content,
        )
        if inline_match:
            return inline_match.group(1)

    # Try to use importlib.metadata (Python 3.8+) for the current package
    try:
        if "__package__" in globals():
            pkg_name = __package__
        else:
            pkg_name = os.path.basename(current_dir)

        import importlib.metadata as metadata  # type: ignore
    except Exception:
        try:
            import importlib_metadata as metadata  # type: ignore
        except Exception:
            metadata = None

    if metadata and pkg_name:
        try:
            version = metadata.version(pkg_name)
            if version:
                return version
        except Exception:
            pass

    # If all attempts fail, return the default value
    return default_version

def get_versions():
    """Get version information or return default if unable to do so."""
    default = "unknown"
    try:
        # Prefer importlib.metadata (Python 3.8+)
        from importlib import metadata as importlib_metadata
    except Exception:
        # Fallback to pkg_resources if importlib.metadata is unavailable
        try:
            import pkg_resources
        except Exception:
            # If neither is available, return the default
            return default

    # Attempt to read version from installed package metadata
    try:
        package_name = __name__.partition('.')[0]  # Top‑level package
        if 'importlib_metadata' in globals():
            return importlib_metadata.version(package_name)
        else:
            return pkg_resources.get_distribution(package_name).version
    except Exception:
        pass

    # If metadata is not available, try reading a local version file
    try:
        import os
        # Commonly, the project root contains a version.py file
        root = os.path.abspath(os.path.join(os.path.dirname(__file__), os.pardir))
        version_path = os.path.join(root, "version.py")
        if not os.path.isfile(version_path):
            # Try a sibling file called 'VERSION' (no extension)
            version_path = os.path.join(root, "VERSION")
            if not os.path.isfile(version_path):
                return default
        with open(version_path, "r", encoding="utf-8") as f:
            for line in f:
                if line.strip().startswith("__version__"):
                    _, value = line.split("=", 1)
                    value = value.strip().strip('"\'')
                    return value
    except Exception:
        pass

    # Final fallback: attempt to import the package and read __version__ attribute
    try:
        pkg = __import__(package_name, fromlist=["__version__"])
        return getattr(pkg, "__version__", default)
    except Exception:
        return default

def get_versions():
    """Get version information or return default if unable to do so."""
    default = "0.0.0"
    # Try reading a VERSION file
    try:
        with open('VERSION', encoding='utf-8') as file:
            content = file.read().strip()
            if content:
                return content
    except Exception:
        pass

    # Fallback: read from version.py if it defines __version__
    try:
        with open('version.py', encoding='utf-8') as file:
            for line in file:
                if line.strip().startswith('__version__'):
                    _, val = line.split('=', 1)
                    return val.strip().strip('"\'')
    except Exception:
        pass

    return default

def get_versions():
    """Get version information or return default if unable to do so."""
    try:
        import pkg_resources
    except Exception:
        return {'default': 'unknown'}
    versions = {}
    try:
        for dist in pkg_resources.working_set:
            try:
                versions[dist.project_name] = dist.version
            except Exception:
                continue
    except Exception:
        return {'default': 'unknown'}
    return versions if versions else {'default': 'unknown'}

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    if pieces is None:
        pieces = {}
    style = style.lower() if isinstance(style, str) else ''

    try:
        if style in ('json',):
            try:
                import json
            except ImportError:
                raise RuntimeError('JSON support requires the json module')
            return json.dumps(pieces, indent=2, sort_keys=True)
        elif style in ('yaml', 'yml'):
            try:
                import yaml
            except ImportError:
                # Fallback to JSON if PyYAML is not available
                import json
                return json.dumps(pieces, indent=2, sort_keys=True)
            return yaml.safe_dump(pieces, default_flow_style=False)
        elif style in ('text', 'plain'):
            if isinstance(pieces, dict):
                lines = [f'{k}: {v}' for k, v in pieces.items()]
            elif isinstance(pieces, (list, tuple)):
                lines = [str(item) for item in pieces]
            else:
                lines = [str(pieces)]
            return '\n'.join(lines)
        elif style in ('html', 'htm'):
            if isinstance(pieces, dict):
                items = ''.join(f'<li><strong>{k}</strong>: {v}</li>'
                                for k, v in pieces.items())
            elif isinstance(pieces, (list, tuple)):
                items = ''.join(f'<li>{item}</li>' for item in pieces)
            else:
                items = f'<li>{pieces}</li>'
            return f'<ul>{items}</ul>'
        elif style in ('csv',):
            try:
                import csv
                from io import StringIO
            except ImportError:
                raise RuntimeError('CSV support requires the csv module')
            output = StringIO()
            if isinstance(pieces, dict):
                writer = csv.writer(output)
                writer.writerow(pieces.keys())
                writer.writerow(pieces.values())
            elif isinstance(pieces, (list, tuple)):
                writer = csv.writer(output)
                writer.writerows(pieces)
            else:
                writer = csv.writer(output)
                writer.writerow([pieces])
            return output.getvalue()
        else:
            raise ValueError(f'Unsupported style "{style}". '
                             'Supported styles are: json, yaml, text, html, csv.')
    except Exception as exc:
        raise RuntimeError(f'Error rendering pieces to style "{style}": {exc}') from exc

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Validate inputs
    if not isinstance(pieces, (list, tuple)):
        raise TypeError("pieces must be a list or tuple")
    if not pieces:
        raise ValueError("pieces must contain at least one element")
    allowed_styles = {'short', 'medium', 'full'}
    if style not in allowed_styles:
        raise ValueError(f"style must be one of {allowed_styles}")

    # Prepare parts: convert to string and ignore empty/None entries
    parts = [str(p) for p in pieces if p not in (None, '')]
    if not parts:
        return ''

    # Render according to style
    if style == 'short':
        if len(parts) >= 2:
            return f"{parts[0]}.{parts[1]}"
        return parts[0]
    if style == 'medium':
        if len(parts) >= 3:
            return f"{parts[0]}.{parts[1]}.{parts[2]}"
        return '.'.join(parts[:2])
    # full
    return '.'.join(parts)

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Validate and normalize the style argument
    if not isinstance(style, str):
        raise TypeError("style must be a string")
    style = style.lower()

    # Prepare the pieces list, ensuring each element is a string
    if pieces is None:
        items = []
    else:
        try:
            items = [str(p) for p in pieces]
        except TypeError:
            # pieces might not be an iterable; treat it as a single item
            items = [str(pieces)]

    # Dispatch to the appropriate rendering strategy
    if style == "string":
        return "".join(items)
    if style == "list":
        return items
    if style == "csv":
        return ",".join(items)
    if style == "html":
        # Wrap each piece in <li> tags inside an unordered list
        return "<ul>" + "".join(f"<li>{x}</li>" for x in items) + "</ul>"
    if style == "json":
        import json
        return json.dumps(items)
    # If the style is not recognized, raise a clear error
    raise ValueError(f"unsupported style: {style}")

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    if not style:
        raise ValueError('style must be provided')
    style = style.lower()

    # Normalise pieces to core components (major, minor, patch) and
    # optional prerelease/build metadata.
    if isinstance(pieces, dict):
        major = str(pieces.get('major', ''))
        minor = str(pieces.get('minor', ''))
        patch = str(pieces.get('patch', ''))
        prerelease = pieces.get('prerelease')
        build = pieces.get('build')
        core_parts = [major, minor, patch]
    elif isinstance(pieces, (list, tuple)):
        core_parts = [str(p) for p in pieces if p is not None]
        prerelease = None
        build = None
    else:
        raise TypeError('pieces must be a mapping or an iterable of parts')

    # Helper to join non‑empty parts
    def _join(parts):
        return '.'.join(p for p in parts if p)

    if style == 'semver':
        result = _join(core_parts)
        if prerelease:
            result += '-' + str(prerelease)
        if build:
            result += '+' + str(build)
        return result
    if style == 'git':
        result = _join(core_parts)
        if prerelease:
            result += '-' + str(prerelease)
        return result
    if style == 'pep440':
        result = _join(core_parts)
        if prerelease:
            # Simple rc handling – full PEP‑440 rules are more involved
            result += '.rc' + str(prerelease)
        if build:
            result += '+' + str(build)
        return result
    if style == 'full':
        full_parts = core_parts[:]
        if prerelease:
            full_parts.append(str(prerelease))
        if build:
            full_parts.append(str(build))
        return _join(full_parts)

    raise ValueError(f'Unsupported style: {style}')

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    # Handle simple string input
    if isinstance(pieces, str):
        return '.' if '+' in pieces else '+'

    # If pieces is None or not iterable, default to returning '+'
    try:
        iterator = iter(pieces)
    except TypeError:
        return '+'

    # Check if any element contains a '+'
    has_plus = False
    for elem in iterator:
        if elem is None:
            continue
        try:
            if '+' in str(elem):
                has_plus = True
                break
        except Exception:
            # If conversion fails, skip this element
            continue

    return '.' if has_plus else '+'

