    try:
        # Consider any iterable; handle None gracefully
        if pieces is None:
            return '+'
        # If pieces is a string, iterate over its characters
        # But we interpret "having a plus" meaning the literal '+' present
        has_plus = any(p == '+' for p in pieces)
