def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Validate and normalize the commands input
    if commands is None:
        raise ValueError("commands argument must not be None")
    if isinstance(commands, (list, tuple)):
        cmd_list = list(commands)
    else:
        cmd_list = [commands]

    # Validate and normalize the args input
    if args is None:
        args = []
    elif isinstance(args, str):
        args = [args]
    elif isinstance(args, (list, tuple)):
        args = list(args)
    else:
        raise ValueError("args must be a list, tuple or string")

    # Ensure all command and argument elements are strings
    for idx, cmd in enumerate(cmd_list):
        if not isinstance(cmd, str):
            raise TypeError(f"commands[{idx}] must be a string, got {type(cmd).__name__}")
    for idx, arg in enumerate(args):
        if not isinstance(arg, str):
            raise TypeError(f"args[{idx}] must be a string, got {type(arg).__name__}")

    # Attempt to run each command in turn, optionally printing verbose info
    for cmd in cmd_list:
        full_cmd = [cmd] + args
        try:
            if verbose:
                print(f"Running command: {' '.join(full_cmd)}")
            stdout = subprocess.check_output(
                full_cmd,
                cwd=cwd,
                env=env,
                stderr=subprocess.DEVNULL if hide_stderr else None,
                universal_newlines=True
            )
            return stdout
        except subprocess.CalledProcessError as exc:
            if verbose:
                print(f"Command {' '.join(full_cmd)} failed with return code {exc.returncode}")
            # Try the next command if available
            continue
        except Exception as exc:  # pylint: disable=broad-except
            if verbose:
                print(f"Error running {' '.join(full_cmd)}: {exc}")
            continue

    # All attempts failed
    raise ProgramError(f"Unable to run any of the commands: {cmd_list} with arguments {args}")

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not commands:
        raise ValueError("commands must be provided")

    # Normalise args
    if args is None:
        args = []
    elif isinstance(args, str):
        args = [args]
    else:
        args = list(args)

    # Normalise command list
    if isinstance(commands, (list, tuple)):
        cmd_list = list(commands)
    else:
        cmd_list = [commands]

    cmd_list.extend(args)

    if verbose:
        print("Running command:", " ".join(map(str, cmd_list)))

    stderr_option = subprocess.DEVNULL if hide_stderr else subprocess.STDOUT

    try:
        output = subprocess.check_output(
            cmd_list,
            cwd=cwd,
            env=env,
            stderr=stderr_option
        )
        return output
    except subprocess.CalledProcessError as e:
        raise RuntimeError(
            f"Command '{' '.join(map(str, cmd_list))}' returned non-zero exit status {e.returncode}"
        ) from e

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if commands is None:
        raise ValueError('commands cannot be None')
    # Normalize args
    if args is None:
        args = []
    if isinstance(args, str):
        args = [args]
    if not isinstance(args, (list, tuple)):
        raise TypeError('args must be a list or tuple')
    # Build command list
    if isinstance(commands, str):
        cmd_list = [commands]
    elif isinstance(commands, (list, tuple)):
        cmd_list = list(commands)
    else:
        raise TypeError('commands must be a string or list/tuple')
    cmd_list.extend(args)
    if verbose:
        print('Running command:', ' '.join(cmd_list))
    # Configure stderr
    stderr_target = subprocess.DEVNULL if hide_stderr else None
    try:
        result = subprocess.run(
            cmd_list,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=stderr_target,
            text=True,
            check=True
        )
        return result.stdout
    except subprocess.CalledProcessError as exc:
        if verbose:
            print(f'Command {cmd_list} failed with return code {exc.returncode}')
        raise

