def register_vcs_handler(vcs, method):  # decorator
    """Create decorator to mark a method as the handler of a VCS."""
    if not isinstance(vcs, str) or not isinstance(method, str):
        raise TypeError("Both `vcs` and `method` must be strings.")
    def decorator(handler):
        if not callable(handler):
            raise TypeError("Handler must be a callable.")
        # Ensure the global HANDLERS dictionary exists.
        global HANDLERS
        if 'HANDLERS' not in globals():
            HANDLERS = {}
        if vcs not in HANDLERS:
            HANDLERS[vcs] = {}
        HANDLERS[vcs][method] = handler
        return handler
    return decorator

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """Validate storage root hierarchy.

        Returns:
            num_objects - number of objects checked
            good_objects - number of objects checked that were found to be valid
        """
        num_objects = 0
        good_objects = 0

        # Attempt to gather objects from the storage root
        objects = []
        try:
            # Prefer a dedicated method if available
            objects = list(self.storage_root.list_objects())
        except AttributeError:
            # Fallback: assume storage_root is iterable
            try:
                objects = list(self.storage_root)
            except Exception:
                objects = []

        for obj in objects:
            num_objects += 1
            is_valid = True

            # Individual object validation
            if validate_objects:
                if hasattr(obj, "validate"):
                    try:
                        obj.validate()
                    except Exception as exc:
                        is_valid = False
                        if show_warnings:
                            print(f"Warning: object {obj} failed validation: {exc}")
                else:
                    if show_warnings:
                        print(f"Warning: object {obj} has no 'validate' method; skipping validation")

            # Digest checking
            if check_digests and hasattr(obj, "check_digest"):
                try:
                    if not obj.check_digest():
                        is_valid = False
                        if show_warnings:
                            print(f"Warning: object {obj} digest mismatch")
                except Exception as exc:
                    is_valid = False
                    if show_warnings:
                        print(f"Warning: object {obj} digest check raised exception: {exc}")

            if is_valid:
                good_objects += 1

        return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """
    Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Validate input types
    if not isinstance(validate_objects, bool):
        raise TypeError("validate_objects must be a bool")
    if not isinstance(check_digests, bool):
        raise TypeError("check_digests must be a bool")
    if not isinstance(show_warnings, bool):
        raise TypeError("show_warnings must be a bool")

    # Attempt to retrieve all objects in the hierarchy.  An implementation
    # may provide a private method `_get_all_objects` returning an iterable,
    # or expose an attribute like `self.objects`.  If neither exists, we
    # treat the hierarchy as empty.
    objects_iterable = None
    if hasattr(self, "_get_all_objects") and callable(self._get_all_objects):
        try:
            objects_iterable = self._get_all_objects()
        except Exception:
            objects_iterable = []
    elif hasattr(self, "objects"):
        objects_iterable = getattr(self, "objects", [])
    elif hasattr(self, "root"):
        # fallback: assume root has a method to iterate its children
        root = getattr(self, "root", None)
        if root is not None:
            # try common traversal methods
            if hasattr(root, "children"):
                objects_iterable = root.children
            elif hasattr(root, "all_objects"):
                objects_iterable = root.all_objects()
    if objects_iterable is None:
        objects_iterable = []

    num_objects = 0
    good_objects = 0

    for obj in objects_iterable:
        num_objects += 1
        is_valid = True
        try:
            if validate_objects and hasattr(obj, "validate"):
                is_valid = bool(obj.validate())
            if is_valid and check_digests and hasattr(obj, "check_digest"):
                is_valid = bool(obj.check_digest())
        except Exception as exc:  # pragma: no cover - robustness handling
            is_valid = False
            if show_warnings:
                obj_id = getattr(obj, "id", None) or getattr(obj, "name", repr(obj))
                print(f"Warning: validation failed for object {obj_id}: {exc!s}")

        if is_valid:
            good_objects += 1
        elif show_warnings:
            obj_id = getattr(obj, "id", None) or getattr(obj, "name", repr(obj))
            print(f"Warning: object {obj_id} failed validation.")

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Parameters
    ----------
    validate_objects : bool, optional
        If True, each object will be subjected to its intrinsic validation
        (via a ``validate`` method or an ``is_valid`` boolean property).
    check_digests : bool, optional
        If True, objects are expected to have a ``digest`` attribute and a
        ``compute_digest`` method; the two must match.
    show_warnings : bool, optional
        If True, any validation failures will be reported using either a
        ``logger`` attribute or, if unavailable, via ``print``.

    Returns
    -------
    tuple[int, int]
        ``(num_objects, good_objects)`` – the number of objects examined and
        the number that passed validation.
    """
    num_objects = 0
    good_objects = 0

    # Try to obtain an iterable collection of hierarchy objects
    try:
        if hasattr(self, 'get_objects') and callable(self.get_objects):
            objects_iter = self.get_objects()
        elif hasattr(self, 'objects'):
            objects_iter = self.objects
        else:
            raise AttributeError("No method or attribute to retrieve hierarchy objects.")
        objects = list(objects_iter)
    except Exception as exc:
        if show_warnings:
            msg = f"Warning: could not retrieve hierarchy objects: {exc}"
            if hasattr(self, 'logger') and hasattr(self.logger, 'warning'):
                self.logger.warning(msg)
            else:
                print(msg)
        return 0, 0

    for obj in objects:
        num_objects += 1
        valid = True

        # Skip None or non‑object entries gracefully
        if obj is None:
            valid = False
            reason = "object is None"
        else:
            # Basic object validation
            if validate_objects:
                try:
                    if hasattr(obj, 'validate') and callable(obj.validate):
                        result = obj.validate()
                        if isinstance(result, bool):
                            valid = result
                    elif hasattr(obj, 'is_valid'):
                        # Assume boolean property
                        valid = bool(obj.is_valid)
                except Exception as exc:
                    valid = False
                    reason = f"validation raised {exc}"

            # Digest consistency
            if valid and check_digests:
                try:
                    if hasattr(obj, 'compute_digest') and callable(obj.compute_digest) and hasattr(obj, 'digest'):
                        expected = obj.compute_digest()
                        if expected != obj.digest:
                            valid = False
                            reason = "digest mismatch"
                except Exception as exc:
                    valid = False
                    reason = f"digest check raised {exc}"

        if valid:
            good_objects += 1
        elif show_warnings:
            # Determine a useful identifier for the object
            obj_id = getattr(obj, 'id', getattr(obj, 'name', str(obj)))
            msg = f"Validation failed for object {obj_id}: {reason if 'reason' in locals() else 'unknown'}"
            if hasattr(self, 'logger') and hasattr(self.logger, 'warning'):
                self.logger.warning(msg)
            else:
                print(msg)

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Parameters
    ----------
    validate_objects : bool, optional
        If True, attempt to call ``validate`` on each object.
    check_digests : bool, optional
        If True, compare the computed digest of each object with its
        stored digest attribute (if present).
    show_warnings : bool, optional
        If True, print warnings when an object fails validation or
        digest check.

    Returns
    -------
    tuple
        A ``(num_objects, good_objects)`` pair indicating the total
        number of objects processed and the number that passed
        validation/digest checks.
    """
    num_objects = 0
    good_objects = 0

    # Try to obtain an iterable of objects.  Many hierarchies expose an
    # ``iterate_objects`` method, otherwise an attribute ``children``
    # or even direct iteration is expected.
    def _iter_objects(root):
        # Recursive depth‑first traversal
        stack = [root]
        while stack:
            node = stack.pop()
            yield node
            # If node has an explicit list/tuple of children, iterate over them
            # otherwise try to treat whatever is returned by iter(node) as
            # children of this node.
            if hasattr(node, 'children') and isinstance(node.children, (list, tuple)):
                stack.extend(reversed(node.children))
            else:
                try:
                    for child in iter(node):
                        stack.append(child)
                except Exception:
                    # Not iterable, so nothing to descend into
                    continue

    # Locate the root of the hierarchy
    root = getattr(self, 'root', None)
    if root is None:
        raise RuntimeError("Hierarchy has no 'root' attribute to validate.")

    # If the root itself is an iterable we treat it as a collection of
    # objects, otherwise we treat it as a single root node.
    try:
        if isinstance(root, (list, tuple)):
            objects_iter = root
        else:
            objects_iter = _iter_objects(root)
    except Exception as e:
        raise RuntimeError(f"Could not iterate over hierarchy root: {e}")

    for obj in objects_iter:
        num_objects += 1
        ok = True

        # Validate the object
        if validate_objects:
            try:
                if hasattr(obj, 'validate') and callable(obj.validate):
                    ok = bool(obj.validate())
            except Exception as exc:
                ok = False
                if show_warnings:
                    print(f"Warning: validation failed for {obj!r}: {exc}")

        # Digest check
        if ok and check_digests:
            try:
                if hasattr(obj, 'compute_digest') and callable(obj.compute_digest):
                    computed = obj.compute_digest()
                    # Many objects store the digest in an attribute called
                    # ``stored_digest`` or ``digest``; we try both.
                    stored = getattr(obj, 'stored_digest', None) or getattr(obj, 'digest', None)
                    if stored is not None and computed != stored:
                        ok = False
                        if show_warnings:
                            print(f"Warning: digest mismatch for {obj!r}")
            except Exception as exc:
                ok = False
                if show_warnings:
                    print(f"Warning: digest check failed for {obj!r}: {exc}")

        if ok:
            good_objects += 1

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    import os
    import hashlib
    import logging

    logger = logging.getLogger(__name__)
    num_objects = 0
    good_objects = 0

    # Gather objects: try a dedicated method first, fallback to file walk
    try:
        objects = self._collect_objects()
    except (AttributeError, TypeError):
        if hasattr(self, "root_dir") and isinstance(self.root_dir, str):
            objects = []
            for dirpath, _, filenames in os.walk(self.root_dir):
                for fname in filenames:
                    objects.append(os.path.join(dirpath, fname))
        else:
            objects = []

    for obj in objects:
        num_objects += 1
        is_valid = True

        # Validate object if requested
        if validate_objects:
            try:
                is_valid = self._validate_object(obj)
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    logger.warning(f"Object validation failed for {obj!r}: {exc}")

        # Check digests if requested
        if is_valid and check_digests:
            try:
                # If a custom validation is available use it; otherwise compute SHA-256
                if hasattr(self, "_verify_digest") and callable(self._verify_digest):
                    digest_ok = self._verify_digest(obj)
                else:
                    with open(obj, "rb") as f:
                        data = f.read()
                        computed_hash = hashlib.sha256(data).hexdigest()
                    # Assume an external source that provides the expected hash
                    expected_hash = getattr(self, "_expected_hash", lambda path: None)(obj)
                    digest_ok = expected_hash == computed_hash if expected_hash is not None else True
                if not digest_ok:
                    is_valid = False
                    if show_warnings:
                        logger.warning(f"Digest mismatch for {obj!r}")
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    logger.warning(f"Digest check failed for {obj!r}: {exc}")

        if is_valid:
            good_objects += 1

    return num_objects, good_objects

def initialize(self):
        """Create and initialize a new OCFL storage root."""
        import os
        import json
        import traceback
        # Determine the root path; it must be set on the instance.
        root = getattr(self, "root", None)
        if not isinstance(root, str) or not root:
            raise AttributeError("Storage root path ('root' attribute) is not set on the instance.")
        try:
            # If the root already exists, ensure it is empty; otherwise raise.
            if os.path.exists(root):
                if os.listdir(root):
                    raise RuntimeError(f"OCFL root '{root}' already exists and is not empty.")
            else:
                os.makedirs(root, exist_ok=True)
            # Create required subdirectories.
            for sub in ("objects", "metadata"):
                sub_path = os.path.join(root, sub)
                os.makedirs(sub_path, exist_ok=True)
            # Create an initial manifest file if it does not exist.
            manifest_path = os.path.join(root, "manifest.json")
            if not os.path.exists(manifest_path):
                manifest_data = {
                    "ocfl_version": "2.0",
                    "created_at": os.path.getmtime(root)
                }
                with open(manifest_path, "w", encoding="utf-8") as f:
                    json.dump(manifest_data, f, indent=2)
            # Store the root back on the instance for future reference.
            self.root = root
            return root
        except Exception as exc:
            # Provide a clear message and preserve the traceback.
            raise RuntimeError(f"Failed to initialize OCFL storage root at '{root}'.") from exc

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    # Determine the root path attribute used by the instance.
    root_path = getattr(self, "root", None) or getattr(self, "path", None)
    if not root_path:
        raise ValueError("OCFL root path is not set on this instance.")

    # Do not overwrite an existing OCFL root.
    ocfl_marker = os.path.join(root_path, ".ocfl_root")
    if os.path.isdir(root_path):
        if os.path.exists(ocfl_marker):
            raise FileExistsError(f"OCFL root already initialized at {root_path}")
        # a non-OCFL-like directory exists – treat as an error
        raise FileExistsError(f"Directory {root_path} already exists and is not an OCFL root.")
    try:
        os.makedirs(root_path, exist_ok=False)
    except OSError as exc:
        raise OSError(f"Failed to create OCFL root directory {root_path}: {exc}") from exc

    # Required subdirectories for OCFL v1.0
    objects_dir = os.path.join(root_path, "objects")
    commits_dir = os.path.join(root_path, "commits")
    for d in (objects_dir, commits_dir):
        try:
            os.makedirs(d, exist_ok=False)
        except OSError as exc:
            raise OSError(f"Failed to create OCFL subdirectory {d}: {exc}") from exc

    # Create the .ocfl_root marker file indicating the OCFL version.
    try:
        with open(ocfl_marker, "w", encoding="utf-8") as f:
            f.write("ocfl/root\n")  # minimal marker for OCFL v1.0
    except OSError as exc:
        raise OSError(f"Failed to write OCFL marker file at {ocfl_marker}: {exc}") from exc

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    try:
        root = self.root_path
    except AttributeError:
        raise ValueError("Storage root path must be set as 'root_path' before initializing.")
    from pathlib import Path
    root_path = Path(root).expanduser().resolve()
    if root_path.exists():
        raise ValueError(f"Root path {root_path} already exists.")
    try:
        root_path.mkdir(parents=True, exist_ok=False)
        # Create .ocfl_version file
        (root_path / ".ocfl_version").write_text("1.0", encoding="utf-8")
        # Create .ocfl_root.json with minimal default metadata
        import json
        root_metadata = {"layout": "v2", "manifestDigest": "sha256"}
        (root_path / ".ocfl_root.json").write_text(json.dumps(root_metadata, indent=2), encoding="utf-8")
        # Create default objects directory
        (root_path / "objects").mkdir()
    except Exception as e:
        raise RuntimeError(f"Failed to initialize OCFL root at {root_path}: {e}") from e
    return self

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    import os

    # Determine and normalise the root path
    try:
        root_path = getattr(self, "root_path", None)
    except Exception as exc:
        raise ValueError(f"Unable to access storage root path: {exc}")

    if not isinstance(root_path, str):
        raise ValueError("root_path must be a string path")

    root_path = os.path.expanduser(root_path)
    root_path = os.path.abspath(root_path)

    # Verify the root doesn't already contain files
    try:
        if os.path.exists(root_path):
            if os.listdir(root_path):
                raise ValueError(f"Root path {root_path} already exists and is not empty.")
        else:
            os.makedirs(root_path, exist_ok=True)
    except OSError as exc:
        raise ValueError(f"Failed to create root directory {root_path}: {exc}")

    # Create OCFL internal directories
    ocfl_dir = os.path.join(root_path, ".ocfl")
    rev_dir = os.path.join(ocfl_dir, "rev")
    manifest_dir = os.path.join(ocfl_dir, "manifest")

    for dir_path in (ocfl_dir, rev_dir, manifest_dir):
        try:
            if not os.path.exists(dir_path):
                os.mkdir(dir_path)
        except OSError as exc:
            raise ValueError(f"Failed to create OCFL directory {dir_path}: {exc}")

    # Write a minimal .ocfl.info file
    info_file = os.path.join(ocfl_dir, ".ocfl.info")
    info_content = (
        '{\n'
        '  "ocfl_version": "2.0",\n'
        '  "obj_fmt_version": "1.0",\n'
        '  "rev_num": 0\n'
        '}'
    )
    try:
        with open(info_file, "w", encoding="utf-8") as fh:
            fh.write(info_content)
    except OSError as exc:
        raise ValueError(f"Failed to create OCFL info file {info_file}: {exc}")

    return None

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str) or not version:
        return ""
    if not version.isdigit():
        return ""
    width = len(version)
    try:
        next_num = int(version, 10) + 1
    except ValueError:
        return ""
    next_str = str(next_num)
    if len(next_str) < width:
        next_str = next_str.rjust(width, '0')
    return next_str

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        return ""
    ver = version.strip()
    if not ver:
        return ""
    # Ensure all characters are digits
    if not ver.isdigit():
        return ""
    try:
        num = int(ver) + 1
    except Exception:
        return ""
    new_str = str(num)
    # Pad with leading zeros to maintain original length if needed
    new_str = new_str.rjust(len(ver), "0")
    return new_str

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not version:
        return ""
    parts = version.split('.')
    if not parts:
        return version
    try:
        # Increment the last numeric part
        last_num = int(parts[-1])
        last_num += 1
        parts[-1] = str(last_num)
        return ".".join(parts)
    except ValueError:
        # If any part is not an integer, return the original version
        return version

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    try:
        ver_str = str(version).strip()
    except Exception:
        return ""

    if not ver_str:
        return ""

    parts = ver_str.split('.')
    last_part = parts[-1]

    # Proceed only if the last part is a sequence of digits
    if not last_part.isdigit():
        return ver_str

    try:
        new_num = int(last_part) + 1
    except Exception:
        return ver_str

    # Preserve leading zeros if the width stays the same
    width = len(last_part)
    new_part = str(new_num).zfill(width) if len(str(new_num)) <= width else str(new_num)
    parts[-1] = new_part
    return ".".join(parts)

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Basic input validation
    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple of directory paths")
    if not version_dirs:
        raise ValueError("No version directories provided")

    # Load the root inventory (first directory) as the baselines
    root_dir = version_dirs[0]
    root_inv_path = os.path.join(root_dir, "inventory.json")
    if not os.path.isfile(root_inv_path):
        raise FileNotFoundError(f"Root inventory file not found: {root_inv_path}")
    try:
        with open(root_inv_path, "r") as f:
            root_inventory = json.load(f)
    except Exception as exc:
        raise ValueError(f"Failed to parse root inventory at {root_inv_path}") from exc

    if not isinstance(root_inventory, dict):
        raise ValueError(f"Root inventory must contain a JSON object mapping file paths to digests")

    # Prepare structures for validation
    self.different_digests = {}  # {file_path: {version_dir: digest, ...}}
    previous_keys = set(root_inventory.keys())
    previous_inventory = root_inventory

    # Iterate through each version directory, ensuring inventories are cumulative
    for idx, vdir in enumerate(version_dirs):
        inv_path = os.path.join(vdir, "inventory.json")
        if not os.path.isfile(inv_path):
            raise FileNotFoundError(f"Inventory file missing in version directory: {vdir}")

        try:
            with open(inv_path, "r") as f:
                inv = json.load(f)
        except Exception as exc:
            raise ValueError(f"Failed to load inventory in {vdir}") from exc

        if not isinstance(inv, dict):
            raise ValueError(f"Inventory in {vdir} must be a JSON object")

        # Ensure the inventory includes all files from the previous version (cumulative)
        if idx > 0:
            missing_in_prev = previous_keys - inv.keys()
            if missing_in_prev:
                missing_str = ", ".join(sorted(missing_in_prev))
                raise ValueError(f"Inventory in {vdir} missing files from previous version: {missing_str}")

        # Record any digests that differ from the root inventory
        for file_path, digest in inv.items():
            if file_path in root_inventory and digest != root_inventory[file_path]:
                self.different_digests.setdefault(file_path, {})[vdir] = digest

        # Update previous state for the next iteration
        previous_keys = set(inv.keys())
        previous_inventory = inv

    return self

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("`version_dirs` must be a list or tuple of directory names.")

    if not hasattr(self, "root_inventory") or not isinstance(self.root_inventory, dict):
        raise ValueError("`self.root_inventory` must be defined as a mapping of path to digest.")

    # Initialize container for differing digests if it doesn't exist
    if not hasattr(self, "different_content_digests") or not isinstance(self.different_content_digests, dict):
        self.different_content_digests = {}

    # Inventory file name expected inside each version directory
    inv_name = getattr(self, "inventory_file", "inventory.json")

    for idx, vdir in enumerate(version_dirs, start=1):
        # Construct full path to inventory file
        inv_path = os.path.join(self.root_dir if hasattr(self, "root_dir") else "", vdir, inv_name)

        if not os.path.isfile(inv_path):
            raise ValueError(f"Inventory file missing for version {vdir} at expected path: {inv_path}")

        try:
            with open(inv_path, "r", encoding="utf-8") as fh:
                try:
                    inv_data = json.load(fh)
                except ValueError as e:
                    raise ValueError(f"Invalid JSON format in inventory for version {vdir}: {e}")
        except OSError as e:
            raise OSError(f"Could not read inventory file for version {vdir}: {e}")

        if not isinstance(inv_data, dict):
            raise ValueError(f"Inventory for version {vdir} must be a mapping of path to digest.")

        # Compare each entry against root inventory, recording any differences.
        diff = {}
        for path, digest in inv_data.items():
            root_digest = self.root_inventory.get(path)
            if root_digest is not None and digest != root_digest:
                diff[path] = digest

        if diff:
            self.different_content_digests[vdir] = diff

    return self

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # The root inventory is assumed to be in self.root_dir/inventory.json
    root_inventory_path = os.path.join(self.root_dir, 'inventory.json')
    if not os.path.exists(root_inventory_path):
        raise ValueError(f"Root inventory not found at {root_inventory_path}")

    try:
        with open(root_inventory_path, 'r', encoding='utf-8') as f:
            root_inventory = json.load(f)
    except Exception as exc:
        raise ValueError(f"Failed to load root inventory '{root_inventory_path}': {exc}") from exc

    mismatches = {}

    for ver_dir in version_dirs:
        inv_path = os.path.join(ver_dir, 'inventory.json')
        if not os.path.exists(inv_path):
            raise ValueError(f"Missing inventory in version directory '{ver_dir}'")

        try:
            with open(inv_path, 'r', encoding='utf-8') as f:
                inv = json.load(f)
        except Exception as exc:
            raise ValueError(f"Failed to load inventory '{inv_path}': {exc}") from exc

        # Ensure that the inventory contains entries for all previous versions.
        for item_path, digest in inv.items():
            root_digest = root_inventory.get(item_path)
            if root_digest is None:
                # Item not in root inventory; skip or record for clarity.
                continue
            if digest != root_digest:
                mismatches.setdefault(item_path, []).append({
                    'version': ver_dir,
                    'current_digest': digest,
                    'root_digest': root_digest
                })

    # Record mismatches for later validation
    self.content_digests_mismatches = mismatches

    return mismatches

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).

    Returns:
        self
    """
    import os
    import json

    # Basic validation of the input
    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple of directory names")
    if not version_dirs:
        raise ValueError("version_dirs list cannot be empty")

    # Determine the repository root.  Prefer an attribute if present, otherwise
    # fall back to the current working directory.
    root = getattr(self, "repo_path", os.getcwd())

    # Path to the root inventory file.  It is assumed to be a JSON file named
    # 'inventory.json' in the root of the repository.
    root_inv_path = os.path.join(root, "inventory.json")
    if not os.path.isfile(root_inv_path):
        raise FileNotFoundError(f"Root inventory not found at {root_inv_path!r}")

    # Load the root inventory
    try:
        with open(root_inv_path, "r", encoding="utf-8") as f:
            root_inventory = json.load(f)
    except ValueError as exc:
        raise ValueError(f"Failed to parse root inventory {root_inv_path!r}: {exc}") from exc
    except OSError as exc:
        raise FileNotFoundError(f"Error reading root inventory {root_inv_path!r}: {exc}") from exc

    if not isinstance(root_inventory, dict):
        raise ValueError("Root inventory must be a JSON object mapping content to digest")

    # Record any digest differences between the root inventory and each version's inventory.
    # The structure is:
    #   {content_path: [(version_dir, root_digest, version_digest), ...], ...}
    self._inventory_digest_differences = {}

    for ver_dir in version_dirs:
        ver_path = os.path.join(root, ver_dir)
        if not os.path.isdir(ver_path):
            raise FileNotFoundError(f"Version directory not found: {ver_path!r}")

        inventory_path = os.path.join(ver_path, "inventory.json")
        if not os.path.isfile(inventory_path):
            raise FileNotFoundError(f"Missing inventory at {inventory_path!r} for version {ver_dir!r}")

        # Load the version inventory
        try:
            with open(inventory_path, "r", encoding="utf-8") as f:
                ver_inventory = json.load(f)
        except ValueError as exc:
            raise ValueError(f"Failed to parse inventory {inventory_path!r}: {exc}") from exc
        except OSError as exc:
            raise FileNotFoundError(f"Error reading inventory {inventory_path!r}: {exc}") from exc

        if not isinstance(ver_inventory, dict):
            raise ValueError(f"Inventory at {inventory_path!r} must be a JSON object")

        # Compare digests
        for content, ver_digest in ver_inventory.items():
            root_digest = root_inventory.get(content)
            if root_digest is None:
                # New content not present in the root; treat as a difference
                self._inventory_digest_differences.setdefault(content, []).append((ver_dir, None, ver_digest))
            elif root_digest != ver_digest:
                self._inventory_digest_differences.setdefault(content, []).append((ver_dir, root_digest, ver_digest))

    # Return the instance for chaining
    return self

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the
    root inventory so that we can also check them when validating the content.

    `version_dirs` is an array of version directory names and is assumed to be
    in version sequence (1, 2, 3...).
    """
    # Locate the root inventory file (assumed to be set on the instance)
    root_inv_path = getattr(self, "root_inventory_path", None)
    if root_inv_path is None:
        raise AttributeError(
            "root_inventory_path attribute is required but not set on the instance"
        )
    # Load the root inventory
    try:
        with open(root_inv_path, "r", encoding="utf-8") as fh:
            root_inv = json.load(fh)
    except (OSError, json.JSONDecodeError) as exc:
        raise ValueError(
            f"Unable to read root inventory from {root_inv_path!r}: {exc}"
        ) from exc
    root_items = root_inv.get("items")
    if not isinstance(root_items, dict):
        raise ValueError("Root inventory must contain an 'items' dictionary")
    # Prepare a structure to record differences
    self.different_digests = {}
    # Validate each version's inventory
    for ver in version_dirs:
        inv_path = os.path.join(ver, "inventory.json")
        try:
            with open(inv_path, "r", encoding="utf-8") as fh:
                inv = json.load(fh)
        except FileNotFoundError:
            raise ValueError(f"Missing inventory file for version directory {ver!r}")
        except json.JSONDecodeError as exc:
            raise ValueError(
                f"Malformed inventory JSON in {inv_path!r}: {exc}"
            ) from exc
        items = inv.get("items")
        if not isinstance(items, dict):
            raise ValueError(f"Inventory in {inv_path!r} must contain an 'items' dictionary")
        # Ensure that the inventory contains all items from the root
        missing = set(root_items) - set(items)
        if missing:
            raise ValueError(
                f"Inventory {inv_path!r} is missing root items: {sorted(missing)}"
            )
        # Record any differing digests
        for key, root_digest in root_items.items():
            ver_digest = items.get(key)
            if ver_digest is None:
                continue  # already flagged as missing
            if ver_digest != root_digest:
                self.different_digests.setdefault(key, []).append(
                    {"version": ver, "root_digest": root_digest, "ver_digest": ver_digest}
                )
    return self

def find_path_type(path):
    """
    Return a string indicating the type of thing at the given path.

    Return values:
        'root'    - looks like an OCFL Storage Root
        'object'  - looks like an OCFL Object
        'file'    - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os

    # Basic sanity checks
    if not path:
        return "error: path is empty or None"

    # Resolve to absolute path to avoid issues with relative symlinks
    try:
        abs_path = os.path.abspath(path)
    except (TypeError, OSError) as exc:
        return f"error: could not resolve absolute path: {exc}"

    if not os.path.exists(abs_path):
        return f"error: path does not exist: {abs_path}"

    # If the path is a regular file (or a symlink to a file)
    try:
        if os.path.isfile(abs_path):
            return "file"
    except OSError as exc:
        return f"error: could not determine if path is a file: {exc}"

    # If the path is a directory (or a symlink to a directory)
    try:
        if os.path.isdir(abs_path):
            # List directory contents; handle permission issues gracefully
            try:
                items = os.listdir(abs_path)
            except PermissionError as exc:
                return f"error: permission denied when reading directory: {exc}"
            except OSError as exc:
                return f"error: could not list directory contents: {exc}"

            # Check for any "0=" Namaste files
            namaste_files = [name for name in items if name.startswith("0=")]
            if namaste_files:
                return "object"
            else:
                # No Namaste files so consider it a storage root
                return "root"
    except OSError as exc:
        return f"error: could not determine if path is a directory: {exc}"

    # If we reach here the path is neither file nor directory
    return f"error: unknown path type: {abs_path}"

def find_path_type(path):
    """
    Return a string indicating the type of thing at the given path.

    Return values:
        'root'   - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file'   - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os, re
    try:
        if not os.path.exists(path):
            return f'error: path does not exist'

        if os.path.isfile(path) or os.path.islink(path):
            return 'file'

        if os.path.isdir(path):
            try:
                entries = os.listdir(path)
            except OSError as exc:
                return f'error: cannot list directory: {exc}'

            # Check for storage root namaste file
            for entry in entries:
                if re.match(r'^0=.*\.namaste$', entry):
                    return 'root'

            # Check for OCFL object layout (content directory presence)
            for entry in entries:
                full_path = os.path.join(path, entry)
                if os.path.isdir(full_path) and entry == 'content':
                    return 'object'
                # Additional quick checks for common object markers
                if entry in ('inventory.tufte', 'manifest'):
                    return 'object'

            return 'other'
        else:
            return 'other'
    except Exception as exc:
        return f'error: {exc}'

def find_path_type(path):
    """
    Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os

    # Validate the incoming path
    if not path:
        return "empty path"

    if not os.path.exists(path):
        return f"does not exist: {path}"

    # If it's a file, return 'file' right away
    if os.path.isfile(path):
        return "file"

    # If it's a directory, look for "0=" namaste files
    if os.path.isdir(path):
        try:
            # List directory contents (non-recursive)
            for entry in os.listdir(path):
                if not entry.startswith("0="):
                    continue
                full_path = os.path.join(path, entry)
                if os.path.isfile(full_path):
                    try:
                        with open(full_path, "r", encoding="utf-8") as f:
                            content = f.read().strip()
                    except Exception as exc:
                        return f"cannot read Namaste file {full_path}: {exc}"

                    # Determine the type based on content
                    if content.startswith("OCFL.Root"):
                        return "root"
                    elif content.startswith("OCFL.Object"):
                        return "object"
                    else:
                        return f"unknown Namaste content: {content}"
            # No Namaste file found
            return "no Namaste file found"
        except PermissionError:
            return "permission denied"
        except Exception as exc:
            return f"error reading directory {path}: {exc}"

    # If we get here, it's neither a file nor a directory
    return f"unrecognized path type: {path}"

def find_path_type(path):
    """
    Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os, re
    try:
        if not os.path.exists(path):
            return f"missing: {path}"
        if os.path.isfile(path):
            return "file"
        if os.path.isdir(path):
            # Check for Namaste file pattern "0=*"
            for name in os.listdir(path):
                if re.match(r"^0=.*$", name):
                    return "object"
            # If no Namaste file, assume storage root
            # but ensure it's not an empty directory
            if any(
                os.path.isdir(os.path.join(path, entry)) for entry in os.listdir(path)
            ):
                return "root"
            return "empty directory"
        return f"unknown path type: {path}"
    except Exception as exc:
        return f"error: {exc}"

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        import os

        if not isinstance(path, str):
            return f'Invalid path type: {type(path)}'
        if not os.path.exists(path):
            return f'Path does not exist: {path}'

        if os.path.isfile(path):
            return 'file'

        if os.path.isdir(path):
            # Directory: check for presence of "0=" subdirectories that contain a "namaste" file.
            try:
                entries = os.listdir(path)
            except Exception as e:  # Permission errors, etc.
                return f'Cannot list directory "{path}": {e}'

            has_version_dir = False
            has_namaste = False

            for entry in entries:
                full_entry = os.path.join(path, entry)
                if os.path.isdir(full_entry) and entry.startswith('0='):
                    has_version_dir = True
                    # Search for a namaste file inside this version directory
                    try:
                        sub_entries = os.listdir(full_entry)
                    except Exception:
                        continue
                    for sub_entry in sub_entries:
                        # Many implementations may name the namaste file "namaste", "namaste.json", etc.
                        if sub_entry.lower().startswith('namaste'):
                            sub_full = os.path.join(full_entry, sub_entry)
                            if os.path.isfile(sub_full):
                                has_namaste = True
                                break
                    if has_namaste:
                        break

            if has_version_dir and has_namaste:
                return 'object'

            # If no "0=" directories found, we consider this a potential storage root.
            # A storage root is typically a directory that contains subdirectories (object IDs),
            # and may also contain repo.yaml or other config files.
            is_empty = not entries
            if is_empty:
                # An empty directory cannot be determined; return error description
                return f'Empty directory, cannot determine type: {path}'
            else:
                return 'root'

        return f'Unknown type for path: {path}'

    except Exception as exc:
        return f'Error processing path "{path}": {exc}'

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not isinstance(params, dict):
        raise ValueError("The first argument 'params' must be a dictionary")
    # Normalise bug_ids into a list
    if isinstance(bug_ids, (int, str)):
        bug_id_list = [bug_ids]
    elif isinstance(bug_ids, (list, tuple)):
        bug_id_list = list(bug_ids)
    else:
        raise ValueError("bug_ids must be an int, str, list, or tuple")
    # Convert all items to strings (Bugzilla expects integer IDs as strings)
    bug_id_strs = [str(b) for b in bug_id_list]
    if not bug_id_strs:
        # nothing to add
        return
    # If 'id' already exists, append the new ids separated by commas
    existing = params.get("id")
    if existing:
        # ensure existing is a string
        if isinstance(existing, list):
            existing = ",".join(map(str, existing))
        elif not isinstance(existing, str):
            existing = str(existing)
        params["id"] = ",".join([existing] + bug_id_strs)
    else:
        # single id or comma‑separated string
        params["id"] = ",".join(bug_id_strs) if len(bug_id_strs) > 1 else bug_id_strs[0]
    # The method mutates the dictionary in place and returns None
    return None

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if params is None:
        params = {}
    if bug_ids is None:
        return params
    try:
        # If a single integer or string, use it as a single id
        if isinstance(bug_ids, (int, str)):
            params['id'] = str(bug_ids).strip()
        elif isinstance(bug_ids, (list, tuple, set)):
            # Convert each element to string, ignore empty values, dedupe
            cleaned = {str(bid).strip() for bid in bug_ids if str(bid).strip()}
            if cleaned:
                params['ids'] = ','.join(sorted(cleaned))
        elif isinstance(bug_ids, str) and ',' in bug_ids:
            # Comma separated string given instead of list
            cleaned = {x.strip() for x in bug_ids.split(',') if x.strip()}
            if cleaned:
                params['ids'] = ','.join(sorted(cleaned))
        else:
            # Unsupported type; just ignore or raise
            raise ValueError("bug_ids must be int, str, list, tuple, or set")
    except Exception:
        # In case of any error we simply return the params unchanged
        pass
    return params

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    # Validate params is a dict
    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")

    # No bug_ids to amend, simply return the params unchanged
    if not bug_ids:
        return params

    # Normalise bug_ids to a list of values
    if isinstance(bug_ids, (int, str)):
        bug_ids = [bug_ids]
    else:
        try:
            bug_ids = list(bug_ids)
        except Exception as e:
            raise TypeError("bug_ids must be an iterable of ids") from e

    # Ensure all ids are stringified (Bugzilla expects string ids)
    bug_ids = [str(i).strip() for i in bug_ids if i is not None and str(i).strip() != '']

    if not bug_ids:
        return params

    # Merge into existing 'ids' key if present
    if 'ids' in params:
        existing = params['ids']
        if isinstance(existing, (list, tuple)):
            existing_ids = [str(e).strip() for e in existing]
        else:
            # assume comma‑separated string
            existing_ids = [e.strip() for e in str(existing).split(',') if e.strip()]
        # Combine and deduplicate while preserving order
        combined = existing_ids + [bid for bid in bug_ids if bid not in existing_ids]
        params['ids'] = combined
    else:
        params['ids'] = bug_ids

    return params

def amend_bzparams(self, params, bug_ids):
        """Amend the Bugzilla params"""
        if not isinstance(params, dict):
            raise TypeError("params must be a dictionary")
        if bug_ids is None:
            return params
        if isinstance(bug_ids, (list, tuple, set)):
            cleaned = []
            for bid in bug_ids:
                if isinstance(bid, (int, str)):
                    cleaned.append(str(bid))
                else:
                    raise TypeError(
                        "Each element in bug_ids must be an int or str"
                    )
            # Bugzilla expects a comma‑separated string for multiple ids
            params["ids"] = ",".join(cleaned)
        else:
            if isinstance(bug_ids, (int, str)):
                params["id"] = str(bug_ids)
            else:
                raise TypeError(
                    "bug_ids must be an int, str, or iterable of ints/strs"
                )
        return params

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    if not isinstance(nodes, list):
        raise TypeError('Expected a list of node tuples')
    # Helper to determine if a node is a MappingNode by checking its tag
    def _is_mapping(node):
        return getattr(node, 'tag', None) in (None, 'tag:yaml.org,2002:map')
    # Recursive merge of mapping node values
    def _merge_mapping(node1, node2):
        # Both nodes should be mapping nodes
        if not (_is_mapping(node1) and _is_mapping(node2)):
            return node2
        merged_pairs = _merge_pairs(node1.value + node2.value)
        # Preserve original node type
        return type(node1)(node1.tag, merged_pairs)
    # Merge a list of (key_node, val_node) pairs
    def _merge_pairs(pairs):
        seen = {}
        order = []
        for key_node, val_node in pairs:
            key_val = getattr(key_node, 'value', None)
            if key_val not in seen:
                seen[key_val] = (key_node, val_node)
                order.append(key_val)
            else:
                old_key_node, old_val_node = seen[key_val]
                if _is_mapping(old_val_node) and _is_mapping(val_node):
                    merged_val = _merge_mapping(old_val_node, val_node)
                    seen[key_val] = (old_key_node, merged_val)
                else:
                    seen[key_val] = (old_key_node, val_node)  # last wins
        return [(seen[k][0], seen[k][1]) for k in order]
    return _merge_pairs(nodes)

