    def _is_mapping_node(node):
        """Return True if node is a MappingNode (ruamel.yaml), identified by its tag."""
        return getattr(node, 'tag', None) == 'tag:yaml.org,2002:map'

    def _merge_mapping_lists(a_list, b_list):
        """Merge two lists of (ScalarNode key, Node value) tuples."""
        merged = {}
        # Insert first list
        for k_node, v_node in a_list:
            key_val = getattr(k_node, 'value', None)
            merged[key_val] = (k_node, v_node)
        # Merge second list, overriding or deep‑merging as needed
        for k_node, v_node in b_list:
            key_val = getattr(k_node, 'value', None)
            if key_val in merged:
                _, existing_v = merged[key_val]
                if _is_mapping_node(existing_v) and _is_mapping_node(v_node):
                    # Deep merge nested mappings
                    merged_v = _merge_mapping_lists(existing_v.value, v_node.value)
                    merged[key_val] = (k_node, merged_v)
                else:
                    # Last value wins for non‑mapping values
                    merged[key_val] = (k_node, v_node)
            else:
                merged[key_val] = (k_node, v_node)
        return list(merged.values())

    merged_map = {}
    order = []
    for key_node, val_node in nodes:
        key_val = getattr(key_node, 'value', None)
        if key_val is None:
            # Skip malformed entries
            continue
        if key_val not in merged_map:
            merged_map[key_val] = (key_node, val_node)
            order.append(key_val)
        else:
            existing_key_node, existing_val_node = merged_map[key_val]
            if _is_mapping_node(existing_val_node) and _is_mapping_node(val_node):
                # Merge mapping nodes in place, updating the value list of the existing node
                merged_list = _merge_mapping_lists(existing_val_node.value, val_node.value)
                existing_val_node.value = merged_list
                merged_map[key_val] = (existing_key_node, existing_val_node)
            else:
                # For non‑mapping values, the last one wins
                merged_map[key_val] = (existing_key_node, val_node)

    result = [(merged_map[key][0], merged_map[key][1]) for key in order]
    return result

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    def is_mapping_node(node):
        return hasattr(node, 'tag') and node.tag == 'tag:yaml.org,2002:map'

    def merge_mapping_nodes(m1, m2):
        """Deep merge two mapping nodes."""
        # Create a copy of the first mapping's items
        merged_items = list(m1.value)
        # Map key value to its index in merged_items for quick lookup
        key_index = {key.value: idx for idx, (key, _) in enumerate(merged_items)}
        # Iterate over second mapping's items
        for key, val in m2.value:
            idx = key_index.get(key.value)
            if idx is not None:
                # Merge the values
                merged_items[idx] = (merged_items[idx][0], merge_values(merged_items[idx][1], val))
            else:
                # Append new key-value pair
                merged_items.append((key, val))
                key_index[key.value] = len(merged_items) - 1
        # Instantiate a new mapping node of the same class
        return type(m1)(tag=m1.tag, value=merged_items)

    def merge_values(v1, v2):
        """Merge two node values."""
        if is_mapping_node(v1) and is_mapping_node(v2):
            return merge_mapping_nodes(v1, v2)
        # For non-mapping values, the last one wins
        return v2

    # Main merging loop
    result = {}
    for item in nodes:
        try:
            key, value = item
        except Exception:
            # Skip malformed items
            continue
        key_id = getattr(key, 'value', None)
        if key_id in result:
            # Merge with existing value
            existing_key, existing_value = result[key_id]
            merged_value = merge_values(existing_value, value)
            result[key_id] = (existing_key, merged_value)
        else:
            result[key_id] = (key, value)
    # Return list preserving the order of first occurrence
    return [tuple_pair for tuple_pair in result.values()]

