def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    # Validate input
    if dicts is None:
        return {}
    try:
        iterator = iter(dicts)
    except TypeError:
        raise TypeError("Argument must be an iterable of dictionaries")
    result = {}
    for d in iterator:
        if not isinstance(d, dict):
            raise TypeError("All elements of the iterable must be dictionaries")
        for key, val in d.items():
            if key in result:
                try:
                    result[key] += val
                except Exception:
                    # If addition fails (different types), override with the latest value
                    result[key] = val
            else:
                result[key] = val
    return result

