def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    if not url:
        return ''

    if not url_args:
        return url

    import re
    import urllib.parse

    # Pattern matches {var} or :var
    pattern = r'\{(?P<var1>[^}]+)\}|\:(?P<var2>[^/]+)'

    def _repl(match):
        var = match.group('var1') or match.group('var2')
        if var not in url_args:
            raise KeyError(f"URL argument '{var}' not provided.")
        value = str(url_args[var])
        # Encode the value for use in a URL path/query
        return urllib.parse.quote(value, safe='')

    try:
        return re.sub(pattern, _repl, url)
    except Exception as exc:
        # In case of any unexpected error, return the original URL
        # and optionally log the error if a logger is available.
        return url

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    if not isinstance(url, str):
        return ''
    if not url_args:
        return url

    def _substitute(match):
        key = match.group(1)
        if key in url_args:
            value = url_args[key]
            value = '' if value is None else str(value)
            try:
                encoded = urllib.parse.quote(value, safe='')
            except Exception:
                encoded = value
            return encoded
        return match.group(0)

    import re  # local import to avoid global dependency
    return re.sub(r'\{([A-Za-z0-9_]+)\}', _substitute, url)

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if not url:
        return ''
    if not url_args:
        return url
    # Find placeholders like {parameter}
    pattern = re.compile(r'\{([^}]+)\}')
    def _replace(match):
        key = match.group(1)
        if key in url_args:
            value = url_args[key]
            # Convert to string and URL-encode
            try:
                encoded = urllib.parse.quote_plus(str(value))
            except Exception:
                encoded = str(value)
            return encoded
        return match.group(0)
    return pattern.sub(_replace, url)

