    if number < 0:
        raise ValueError("number must be non-negative")
    if not alphabet:
        raise ValueError("alphabet must not be empty")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("alphabet must contain unique symbols")
    base = len(alphabet)
    if base < 2:
        raise ValueError("alphabet must contain at least two symbols")
    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError("padding must be an int or None")
        if padding < 0:
            raise ValueError("padding must be non-negative")
    # Convert number to digits in reverse order
    digits = []
    n = number
    if n == 0:
        digits.append(alphabet[0])
    else:
        while n:
            digits.append(alphabet[n % base])
            n //= base
    digits.reverse()
    # Apply padding if requested
    if padding is not None and len(digits) < padding:
        digits = [alphabet[0]] * (padding - len(digits)) + digits
    return "".join(digits)

