    return result

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    """
    if not isinstance(flow_params, dict):
        raise TypeError(f"flow_params must be a dict, got {type(flow_params).__name__}")
    if not isinstance(register_number, int):
        raise TypeError(f"register_number must be an int, got {type(register_number).__name__}")
    if not isinstance(register_value, str):
        raise TypeError(f"register_value must be a str, got {type(register_value).__name__}")

    def _traverse(obj):
        if isinstance(obj, dict):
            for key, value in obj.items():
                if key == register_value:
                    obj[key] = register_number
                else:
                    _traverse(value)
        elif isinstance(obj, list) or isinstance(obj, tuple):
            for item in obj:
                _traverse(item)

    _traverse(flow_params)
    return flow_params

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    """
    # Validate inputs
    if not isinstance(flow_params, dict):
        raise TypeError("flow_params must be a dictionary")
    if not isinstance(register_number, (int, str)):
        raise TypeError("register_number must be an int or str")
    if not isinstance(register_value, (int, str, float)):
        raise TypeError("register_value must be a primitive value")

    def _replace_in_obj(obj, reg_num, reg_val):
        if isinstance(obj, dict):
            new_dict = {}
            for k, v in obj.items():
                if isinstance(v, (dict, list)):
                    new_dict[k] = _replace_in_obj(v, reg_num, reg_val)
                else:
                    new_dict[k] = reg_num if v == reg_val else v
            return new_dict
        if isinstance(obj, list):
            return [_replace_in_obj(item, reg_num, reg_val) for item in obj]
        # Primitive value: replace if it matches
        return reg_num if obj == reg_val else obj

    try:
        return _replace_in_obj(flow_params, register_number, register_value)
    except Exception as exc:
        raise RuntimeError(f"Failed to replace register values: {exc}") from exc

def _replace_register(flow_params, register_number, register_value):
