            raise ValueError('platform must be "this", 0, or 1') from e

    try:
        if platform_flag == 1:          # POSIX
            return shlex.split(s)
        elif platform_flag == 0:        # Windows / CMD
            return shlex.split(s, posix=False)
        else:
            raise ValueError('unsupported platform flag %r' % platform)
    except Exception as exc:
        # Wrap any shlex-related errors with a clear message
        raise ValueError('shlex.split failed: %s' % exc) from exc

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import os
    from pathlib import Path
    from subprocess import run, CalledProcessError

    # Resolve paths
    archive_path = Path(archive_path).expanduser().resolve()
    tmp_dir = Path(tmp_path).expanduser().resolve()

    # Determine extraction directory name
    if filename:
        out_name = filename
    else:
        out_name = archive_path.stem
        # Remove compression extensions
        for ext in (".tar.gz", ".tgz", ".tar.bz2", ".zip"):
            if out_name.endswith(ext):
                out_name = out_name[: -len(ext)]
    extract_dir = tmp_dir / out_name

    # Ensure the extraction directory exists
    try:
        extract_dir.mkdir(parents=True, exist_ok=True)
    except OSError as exc:
        raise RuntimeError(f"Could not create extraction directory {extract_dir}") from exc

    # Determine extraction command based on archive type
    ext = archive_path.suffix.lower()
    cmd = None
    if archive_path.name.endswith(".tar.gz") or archive_path.name.endswith(".tgz"):
        cmd = ["tar", "-xzf", str(archive_path), "-C", str(extract_dir)]
    elif archive_path.name.endswith(".tar.bz2"):
        cmd = ["tar", "-xjf", str(archive_path), "-C", str(extract_dir)]
    elif ext == ".tar":
        cmd = ["tar", "-xf", str(archive_path), "-C", str(extract_dir)]
    elif ext == ".zip":
        cmd = ["unzip", "-q", str(archive_path), "-d", str(extract_dir)]
    else:
        raise ValueError(f"Unsupported archive type for {archive_path}")

    # Execute extraction
    try:
        run(cmd, check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    except CalledProcessError as exc:
        raise RuntimeError(f"Extraction failed for {archive_path}: {exc.stderr.decode().strip()}") from exc

    # Return a file URL to the extracted directory
    return f"file://{extract_dir}"

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.
    This does not deal with the case where the archive passed along does not exist.
    """
    import os
    import subprocess
    from pathlib import Path

    # Ensure the base tmp path is a string
    tmp_path = str(tmp_path)

    if not os.path.isfile(archive_path):
        raise FileNotFoundError(f"Archive '{archive_path}' does not exist")

    # Resolve the target extraction directory name
    if filename:
        target_name = filename
    else:
        base = os.path.basename(archive_path)
        # Strip common compressed extensions
        for ext in (".tar.gz", ".tgz", ".tar.bz2", ".tbz2", ".zip"):
            if base.lower().endswith(ext):
                target_name = base[: -len(ext)]
                break
        else:
            target_name = os.path.splitext(base)[0]

    dest_dir = os.path.join(tmp_path, target_name)

    if os.path.exists(dest_dir):
        raise FileExistsError(f"Destination directory '{dest_dir}' already exists")

    os.makedirs(dest_dir, exist_ok=False)

    # Build the extraction command based on the archive type
    lower_path = archive_path.lower()
    if lower_path.endswith((".tar.gz", ".tgz")):
        cmd = ["tar", "-xzf", archive_path, "-C", dest_dir]
    elif lower_path.endswith((".tar.bz2", ".tbz2")):
        cmd = ["tar", "-xjf", archive_path, "-C", dest_dir]
    elif lower_path.endswith(".zip"):
        cmd = ["unzip", "-q", archive_path, "-d", dest_dir]
    else:
        raise ValueError(f"Unsupported archive type: '{archive_path}'")

    try:
        subprocess.check_call(cmd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    except subprocess.CalledProcessError as exc:
        raise RuntimeError(f"Failed to extract archive '{archive_path}': {exc}") from exc

    # Return a standard file URL that can be used as a Git remote
    return f"file://{os.path.abspath(dest_dir)}"

def prepare_repository_from_archive(
