    except subprocess.CalledProcessError:
        raise FileNotFoundError(f"Archive {archive_path!r} does not exist")

    # Determine the base filename to use for extraction directory
    if filename is None:
        # Strip path to get basename
        if "/" in archive_path:
            base = archive_path.rsplit("/", 1)[1]
        else:
            base = archive_path
        # Remove all extensions
        name = base
        while "." in name:
            name, _ = name.rsplit(".", 1)
        filename_local = name
    else:
        filename_local = filename

    # Build extraction directory path
    if str(tmp_path).endswith("/"):
        extraction_dir = f"{tmp_path}{filename_local}"
    else:
        extraction_dir = f"{tmp_path}/{filename_local}"

    # If the extraction directory already exists, raise an error
    try:
        if subprocess.run(["test", "-d", extraction_dir], check=False).returncode == 0:
            raise FileExistsError(f"Extraction directory {extraction_dir!r} already exists")
    except Exception as exc:
        # Any unexpected error from test should be surfaced
        raise

    # Create the extraction directory
    subprocess.run(["mkdir", "-p", extraction_dir], check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)

    # Determine the extraction command based on archive type
    if archive_path.endswith((".tar.gz", ".tgz")):
        cmd = ["tar", "-xzf", archive_path, "-C", extraction_dir]
    elif archive_path.endswith((".tar.bz2", ".tbz2")):
        cmd = ["tar", "-xjf", archive_path, "-C", extraction_dir]
    elif archive_path.endswith(".zip"):
        cmd = ["unzip", "-q", archive_path, "-d", extraction_dir]
    else:
        # Fallback to tar with no compression flag
        cmd = ["tar", "-xf", archive_path, "-C", extraction_dir]

    # Execute extraction
    try:
        subprocess.check_call(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    except subprocess.CalledProcessError as exc:
        # Clean up partially extracted files
        subprocess.run(["rm", "-rf", extraction_dir], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
