def addignored(ignored):
    """Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma."""
    try:
        # git ls-files --others --exclude-standard lists untracked files that are ignored
        output = subprocess.check_output(
            ["git", "ls-files", "--others", "--exclude-standard"],
            stderr=subprocess.STDOUT,
            text=True,
        )
    except subprocess.CalledProcessError as exc:
        # In case of a failure, return an empty string or propagate the error
        return ""

    # Split the output into lines, filter out empty entries, sort
    ignored_files = sorted([line.strip() for line in output.splitlines() if line.strip()])

    # Return as a comma separated string
    return ",".join(ignored_files)

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or (isinstance(frequency, str) and frequency.strip().lower() == "always"):
        return None

    if not isinstance(frequency, str):
        raise ValueError("Frequency must be a string or None")

    import re
    pattern = r'^\s*(\d+(?:\.\d+)?)\s*([a-zA-Z]+)\s*$'
    match = re.match(pattern, frequency)
    if not match:
        raise ValueError(f"Cannot parse frequency: {frequency!r}")

    amount_str, unit = match.groups()
    try:
        amount = float(amount_str)
    except ValueError:
        raise ValueError(f"Invalid numeric part in frequency: {amount_str!r}")

    unit = unit.lower()
    # Normalize unit names
    unit_map = {
        'day': 'days', 'days': 'days',
        'week': 'weeks', 'weeks': 'weeks',
        'hour': 'hours', 'hours': 'hours',
        'minute': 'minutes', 'minutes': 'minutes',
        'second': 'seconds', 'seconds': 'seconds',
        'month': 'days', 'months': 'days',
        'year': 'days', 'years': 'days',
    }

    if unit not in unit_map:
        raise ValueError(f"Unrecognized time unit in frequency: {unit!r}")

    if unit in ('month', 'months'):
        # approximate month as 30 days
        return datetime.timedelta(days=amount * 30)
    if unit in ('year', 'years'):
        # approximate year as 365 days
        return datetime.timedelta(days=amount * 365)

    kwargs = {unit_map[unit]: amount}
    return datetime.timedelta(**kwargs)

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    # Return None for null or sentinel value
    if frequency is None:
        return None
    if isinstance(frequency, str) and frequency.strip().lower() == 'always':
        return None

    freq_str = str(frequency).strip()
    if not freq_str:
        raise ValueError(f"Cannot parse empty frequency: {frequency!r}")

    try:
        import re
    except ImportError:
        raise ImportError("The 're' module is required for parsing frequency")

    m = re.match(r'^\s*(?P<num>\d+)\s*(?P<unit>\w+)\s*$', freq_str, re.I)
    if not m:
        raise ValueError(f"Cannot parse frequency string: {frequency!r}")

    num = int(m.group('num'))
    unit = m.group('unit').lower()

    unit_map = {
        'day': 'days',
        'days': 'days',
        'week': 'weeks',
        'weeks': 'weeks',
        'hour': 'hours',
        'hours': 'hours',
        'minute': 'minutes',
        'minutes': 'minutes',
        'second': 'seconds',
        'seconds': 'seconds',
    }

    if unit not in unit_map:
        raise ValueError(f"Unknown time unit in frequency: {frequency!r}")

    kwargs = {unit_map[unit]: num}
    return datetime.timedelta(**kwargs)

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False

    # Quick string checks for common representations
    if host.lower() in {"localhost", "127.0.0.1", "::1"}:
        return True

    try:
        # Resolve the host to all possible addresses
        info = socket.getaddrinfo(host, None)
    except socket.gaierror:
        # Could not resolve; cannot be local
        return False

    # Loop over resolved addresses and check if any is in the loopback range
    try:
        import ipaddress
    except ImportError:
        # Fallback for environments without ipaddress module
        def is_loopback(ip):
            # Basic checks for IPv4 127.0.0.0/8 and IPv6 ::1
            if ip.startswith("127.") or ip == "::1":
                return True
            return False
    else:
        def is_loopback(ip):
            try:
                return ipaddress.ip_address(ip).is_loopback
            except ValueError:
                return False

    for entry in info:
        # entry[4] is the sockaddr; for IPv4 it is (ip, port), for IPv6 (ip, port, flow, scope)
        sockaddr = entry[4]
        addr = sockaddr[0]
        if is_loopback(addr):
            return True

    return False

