def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    '''
    Given a target config filename and rendered config YAML, write it out to file. Create any
    containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything.
    '''
    config_filename = os.path.expanduser(config_filename)
    if not overwrite and os.path.isfile(config_filename):
        return
    config_dir = os.path.dirname(config_filename)
    if config_dir:
        try:
            os.makedirs(config_dir, exist_ok=True)
        except OSError:
            if not os.path.isdir(config_dir):
                raise
    with open(config_filename, 'w') as f:
        f.write(rendered_config)
    try:
        os.chmod(config_filename, mode)
    except OSError:
        pass

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    # Determine the variable name
    try:
        name = matcher.name
    except AttributeError:
        if hasattr(matcher, "groupdict"):
            g = matcher.groupdict()
            if "name" in g:
                name = g["name"]
            else:
                raise ValueError("Matcher must contain a 'name' group.")
        elif isinstance(matcher, (list, tuple)) and len(matcher) >= 1:
            name = matcher[0]
        else:
            raise ValueError("Unsupported matcher type; cannot extract variable name.")

    # Determine the default value (if any)
    default = None
    try:
        default = matcher.default
    except AttributeError:
        if hasattr(matcher, "groupdict"):
            g = matcher.groupdict()
            default = g.get("default")
        elif isinstance(matcher, (list, tuple)) and len(matcher) >= 2:
            default = matcher[1]
        # If not found, default remains None

    # Return the environment value or default, or raise an error
    try:
        return os.environ[name]
    except KeyError:
        if default is not None:
            return default
        raise KeyError(f"Environment variable '{name}' not found and no default value provided.")

def _resolve_string(matcher):
    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    # Determine name and default from matcher which may be a tuple/list or an object with attributes.
    if isinstance(matcher, (list, tuple)):
        if not matcher:
            raise ValueError("Matcher must contain at least the variable name.")
        name = matcher[0]
        default = matcher[1] if len(matcher) > 1 else None
    else:
        try:
            name = getattr(matcher, 'name')
        except AttributeError:
            raise TypeError("Matcher must have a 'name' attribute or be a tuple/list.")
        default = getattr(matcher, 'default', None)

    # Fetch from environment
    if name in os.environ:
        return os.environ[name]
    if default is not None:
        return default
    raise KeyError(f"Environment variable '{name}' not found and no default provided.")

