        print("Executing:", " ".join(base))

    # Configure stderr handling
    stderr_option = subprocess.DEVNULL if hide_stderr else None

    try:
        result = subprocess.run(
            base,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=stderr_option,
            text=True,
            check=False
        )
    except Exception as exc:
        raise RuntimeError(f"Command {base!r} failed to start: {exc}") from exc

    if verbose:
        if result.stdout:
            print(result.stdout)
        if not hide_stderr and result.stderr:
            print(result.stderr)

    return result

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    # Basic input validation
    if commands is None:
        raise ValueError("commands must not be None")
    if isinstance(commands, str):
        # a single command string becomes the first element of the list
        cmd_list = [commands]
    elif isinstance(commands, (list, tuple)):
        cmd_list = list(commands)
    else:
        raise TypeError(f"commands must be a string or list/tuple of strings, got {type(commands).__name__}")

    if args is None:
        args = []
    if not isinstance(args, (list, tuple)):
        raise TypeError(f"args must be a list or tuple of strings, got {type(args).__name__}")

    # Ensure every element is a string
    for elem in cmd_list + list(args):
        if not isinstance(elem, str):
            raise TypeError(f"All command parts must be strings, got element of type {type(elem).__name__}")

    # Construct full command
    full_cmd = cmd_list + list(args)

    if verbose:
        print(f"[run_command] Starting: {full_cmd} (cwd={cwd})")

    # Configure stderr handling
    stderr_setting = subprocess.DEVNULL if hide_stderr else subprocess.PIPE

    try:
        result = subprocess.run(
            full_cmd,
            cwd=cwd,
            stdout=subprocess.PIPE,
            stderr=stderr_setting,
            env=env,
            check=True,
            text=True
        )
        if verbose:
            print(f"[run_command] Completed: returncode={result.returncode}")
        return result
    except subprocess.CalledProcessError as e:
        # Include stdout and stderr in the error message for debugging
        out = e.stdout or ""
        err = e.stderr or ""
        msg = (f"Command '{full_cmd}' failed with return code {e.returncode}\n"
               f"stdout:\n{out}\n"
               f"stderr:\n{err}")
        raise RuntimeError(msg) from e
    except OSError as e:
        raise RuntimeError(f"OS error running command '{full_cmd}': {e}") from e

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
