def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple
        shape of the array to create
    dtype : `numpy.dtype`
        data-type of the array to create
    """
    if not isinstance(shape, tuple):
        raise TypeError(f"shape must be a tuple, got {type(shape)}")
    for dim in shape:
        if not isinstance(dim, int):
            raise TypeError(f"Shape dimensions must be integers, got {type(dim)}")
        if dim < 0:
            raise ValueError("Shape dimensions must be non-negative")
    try:
        dtype_np = np.dtype(dtype)
    except Exception as exc:
        raise TypeError(f"Invalid dtype: {dtype}") from exc
    try:
        return np.empty(shape, dtype=dtype_np)
    except Exception as exc:
        raise ValueError(f"Could not create array with shape {shape} and dtype {dtype_np}") from exc

