def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    import json
    import yaml
    import toml
    import configparser
    import logging

    # Ensure config_filenames is iterable
    if isinstance(config_filenames, str):
        config_filenames = [config_filenames]
    configs = {}
    error_records = []

    def _create_error_record(path, message, exc=None):
        record = logging.makeLogRecord({
            'name': 'config_loader',
            'level': logging.ERROR,
            'pathname': path,
            'lineno': 0,
            'msg': message,
            'args': (),
            'exc_info': exc
        })
        return record

    for cfg_path in config_filenames:
        try:
            with open(cfg_path, 'r', encoding='utf-8') as fp:
                content = fp.read()
        except FileNotFoundError as e:
            error_records.append(_create_error_record(cfg_path,
                                                       f'Configuration file not found: {cfg_path}'))
            continue
        except Exception as e:
            error_records.append(_create_error_record(cfg_path,
                                                       f'Error reading configuration file {cfg_path}: {e}',
                                                       exc_info=True))
            continue

        ext = os.path.splitext(cfg_path)[1].lower()
        try:
            if ext == '.json':
                data = json.loads(content)
            elif ext in ('.yaml', '.yml'):
                data = yaml.safe_load(content)
            elif ext == '.toml':
                data = toml.loads(content)
            elif ext == '.ini':
                parser = configparser.ConfigParser()
                parser.read_string(content)
                data = {s: dict(parser[s]) for s in parser.sections()}
            else:
                # Default to JSON
                data = json.loads(content)
        except Exception as e:
            error_records.append(_create_error_record(cfg_path,
                                                       f'Error parsing configuration file {cfg_path}: {e}',
                                                       exc_info=True))
            continue

        # Simple validation: configuration must be a dict
        if not isinstance(data, dict):
            error_records.append(_create_error_record(cfg_path,
                                                       f'Parsed configuration is not a dictionary: {type(data)}'))
            continue

        # Resolve environment variables if requested
        if resolve_env:
            def _resolve(value):
                if isinstance(value, str):
                    return os.path.expandvars(value)
                if isinstance(value, dict):
                    return {k: _resolve(v) for k, v in value.items()}
                if isinstance(value, list):
                    return [_resolve(v) for v in value]
                return value
            data = _resolve(data)

        # Apply overrides if any
        if overrides and isinstance(overrides, dict):
            data.update(overrides)

        configs[cfg_path] = data

    return configs, error_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    import json
    import os
    import yaml
    import logging

    def _expand_env(value):
        if isinstance(value, dict):
            return {k: _expand_env(v) for k, v in value.items()}
        if isinstance(value, list):
            return [_expand_env(v) for v in value]
        if isinstance(value, str):
            return os.path.expandvars(value)
        return value

    config_dict = {}
    error_records = []
    logger = logging.getLogger(__name__)

    for filename in config_filenames:
        try:
            with open(filename, "r") as f:
                raw_data = f.read()
        except Exception as exc:
            record = logger.makeRecord(
                logger.name, logging.ERROR, filename, 0,
                f"Unable to read configuration file '{filename}': {exc}",
                None, None,
            )
            error_records.append(record)
            continue

        parsed = None
        loaders = [
            (json.loads, ValueError),
            (yaml.safe_load, yaml.YAMLError)
        ]
        for loader, exc_cls in loaders:
            try:
                parsed = loader(raw_data)
                break
            except exc_cls:
                parsed = None

        if parsed is None:
            record = logger.makeRecord(
                logger.name, logging.ERROR, filename, 0,
                f"Unable to parse configuration file '{filename}'.",
                None, None,
            )
            error_records.append(record)
            continue

        if resolve_env:
            parsed = _expand_env(parsed)

        if overrides:
            if isinstance(parsed, dict):
                parsed.update(overrides)

        config_dict[filename] = parsed

    return config_dict, error_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import json, os
    try:
        import yaml
    except ImportError:
        yaml = None
    try:
        import toml
    except ImportError:
        toml = None

    configs = {}
    errors = []

    def expand_env(value):
        if isinstance(value, str):
            return os.path.expandvars(value)
        if isinstance(value, dict):
            return {k: expand_env(v) for k, v in value.items()}
        if isinstance(value, list):
            return [expand_env(v) for v in value]
        return value

    for filename in config_filenames:
        try:
            if not os.path.isfile(filename):
                raise FileNotFoundError(filename)
            with open(filename, 'r', encoding='utf-8') as f:
                content = f.read()
            ext = os.path.splitext(filename)[1].lower()
            if ext == '.json':
                cfg = json.loads(content)
            elif ext in {'.yaml', '.yml'} and yaml is not None:
                cfg = yaml.safe_load(content)
            elif ext == '.toml' and toml is not None:
                cfg = toml.loads(content)
            else:
                raise ValueError(f'Unsupported configuration file format: {ext}')
            if not isinstance(cfg, dict):
                raise ValueError('Top-level configuration must be a dictionary')
            if resolve_env:
                cfg = expand_env(cfg)
            if overrides:
                cfg.update(overrides)
            configs[filename] = cfg
        except Exception as exc:
            record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=str(exc),
                args=None,
                exc_info=None
            )
            errors.append(record)
    return configs, errors

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    import json
    import yaml
    import toml
    import re
    import logging

    configs = {}
    parse_errors = []

    env_var_pattern = re.compile(r'\$\{([^}]+)\}')

    def _replace_env(value):
        if isinstance(value, str):
            def repl(match):
                return os.getenv(match.group(1), '')
            return env_var_pattern.sub(repl, value)
        return value

    def _walk_and_replace(obj):
        if isinstance(obj, dict):
            return {k: _walk_and_replace(_replace_env(v)) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [_walk_and_replace(_replace_env(item)) for item in obj]
        else:
            return _replace_env(obj)

    for filename in config_filenames:
        try:
            if not os.path.exists(filename):
                raise FileNotFoundError(f'Configuration file not found: {filename}')

            with open(filename, 'r', encoding='utf-8') as f:
                raw = f.read()

            if not raw.strip():
                config_dict = {}
            else:
                ext = os.path.splitext(filename)[1].lower()
                if ext in {'.yaml', '.yml'}:
                    config_dict = yaml.safe_load(raw)
                elif ext == '.json':
                    config_dict = json.loads(raw)
                elif ext == '.toml':
                    config_dict = toml.loads(raw)
                else:
                    raise ValueError(f'Unsupported configuration extension: {ext}')

            if config_dict is None:
                config_dict = {}

            if overrides is not None:
                if isinstance(overrides, dict):
                    config_dict.update(overrides)
                else:
                    raise TypeError('Overrides must be a dictionary')

            if resolve_env:
                config_dict = _walk_and_replace(config_dict)

            configs[filename] = config_dict

        except Exception as exc:
            msg = f'Error loading configuration "{filename}": {exc}'
            record = logging.LogRecord(
                name=os.path.basename(filename),
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=msg,
                args=(),
                exc_info=exc.__class__,)
            parse_errors.append(record)

    return configs, parse_errors

def protocol_handlers(cls, protocol_version=None):
        """
        Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        if protocol_version is not None:
            if not isinstance(protocol_version, tuple) or len(protocol_version) != 2:
                raise TypeError(
                    "protocol_version must be a tuple of two integers (major, minor)"
                )
            protocols = {}
            if hasattr(cls, "HANDLERS") and isinstance(cls.HANDLERS, dict):
                handler = cls.HANDLERS.get(protocol_version)
                if handler is not None:
                    protocols[protocol_version] = handler
            else:
                for subcls in cls.__subclasses__():
                    ver = getattr(subcls, "VERSION", None)
                    if ver == protocol_version:
                        protocols[protocol_version] = subcls
            return protocols

        # No specific version requested: return all supported handlers
        protocols = {}
        if hasattr(cls, "HANDLERS") and isinstance(cls.HANDLERS, dict):
            protocols.update(cls.HANDLERS)
        else:
            for subcls in cls.__subclasses__():
                ver = getattr(subcls, "VERSION", None)
                if isinstance(ver, tuple) and len(ver) == 2:
                    protocols[ver] = subcls
        return protocols

def protocol_handlers(cls, protocol_version=None):
    """
    Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple.  If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported.  If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    :raise AttributeError: if the class does not provide a
        PROTOCOL_HANDLERS mapping
    """
    # Validate the type of protocol_version
    if protocol_version is not None and not isinstance(protocol_version, tuple):
        raise TypeError("protocol_version must be a tuple (major, minor)")

    # Retrieve the mapping of available protocol handlers
    try:
        available = cls.PROTOCOL_HANDLERS
    except AttributeError as exc:
        raise AttributeError(
            "Class %s does not provide a 'PROTOCOL_HANDLERS' attribute" % cls.__name__
        ) from exc

    # Ensure the attribute is a dictionary
    if not isinstance(available, dict):
        raise TypeError(
            "PROTOCOL_HANDLERS must be a dictionary mapping "
            "version tuples to handler classes"
        )

    # Return the appropriate slice of the mapping
    if protocol_version is None:
        # Return a shallow copy to prevent accidental mutation
        return available.copy()

    # Return a dictionary containing the requested version if present
    return (
        {protocol_version: available[protocol_version]}
        if protocol_version in available
        else {}
    )

def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    handlers = getattr(cls, "_bolt_protocol_handlers", {})
    if not isinstance(handlers, dict):
        # If the attribute exists but is not a dict, treat as no handlers.
        handlers = {}

    if protocol_version is not None:
        if not isinstance(protocol_version, tuple):
            raise TypeError(
                f"protocol_version must be a tuple, got {type(protocol_version).__name__}"
            )
        # Return single-item dict if supported, else empty dict
        if protocol_version in handlers:
            return {protocol_version: handlers[protocol_version]}
        return {}

    # Return a copy of all handlers
    return dict(handlers)

def from_raw_values(cls, values):
