        unique_values = []
        seen = set()
        for v in values:
            if not isinstance(v, str):
                raise TypeError(f"Bookmark value must be a string, got {type(v)}")
            if v not in seen:
                seen.add(v)
                unique_values.append(v)
    except TypeError as exc:
        raise ValueError("values must be an iterable of strings") from exc

    # Attempt to construct the Bookmarks object with the parsed values.
    # If the constructor accepts an iterable of bookmarks, pass it directly;
    # otherwise assign the internal storage attribute after instantiation.
    try:
        # Prefer constructor that accepts initial bookmarks list
        return cls(unique_values)
    except TypeError:
        # Fallback: create an empty instance and set attribute manually
        instance = cls()
        setattr(instance, "bookmarks", unique_values)
        return instance

