        except TypeError:
            raise TypeError("values must be an iterable of strings")

        # Clean and validate each bookmark value
        cleaned = []
        for item in iterator:
            if not isinstance(item, str):
                raise TypeError(
                    f"Each bookmark value must be a string, got {type(item).__name__}"
                )
            stripped = item.strip()
            if stripped:          # ignore empty strings
                cleaned.append(stripped)

        # Preserve original order while removing duplicates
        seen = set()
        unique = []
        for item in cleaned:
            if item not in seen:
                seen.add(item)
                unique.append(item)

        # Construct the Bookmarks instance (assuming constructor accepts an iterable)
        return cls(unique)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # If seq is a string or bytes, keep it as is
    if isinstance(seq, (str, bytes)):
        return (seq, type(seq))

    # If seq looks like a sequence (has __len__ and __getitem__)
    if hasattr(seq, "__len__") and hasattr(seq, "__getitem__"):
        return (seq, type(seq))

    # Try to consume seq into a list (handles iterators/generators)
    try:
        seq_list = list(seq)
    except TypeError:
        raise TypeError(f"Input {seq!r} is not iterable")

    return (seq_list, type(seq_list))

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if seq is None:
        raise TypeError("Input sequence cannot be None")

    # If seq is already a sequence type (including strings and bytes), return it directly
    if isinstance(seq, (list, tuple, str, bytes)):
        return (seq, type(seq).__name__)

    # If seq is not a sequence, try to iterate over it
    try:
        iterator = iter(seq)
    except TypeError:
        raise TypeError(
            f"Input of type {type(seq).__name__} is not iterable and cannot be used as a sequence"
        )

    # Build a list from the iterator, possibly using a buffer size if provided
    seq_list = []
    if bufsize is None:
        for item in iterator:
            seq_list.append(item)
    else:
        chunk = []
        count = 0
        for item in iterator:
            chunk.append(item)
            count += 1
            if count >= bufsize:
                seq_list.extend(chunk)
                chunk = []
                count = 0
        if chunk:
            seq_list.extend(chunk)

    # Return the constructed list and the original type name of seq
    return (seq_list, type(seq).__name__)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # If seq is already a sequence type (list, tuple, str, bytes, set, etc.)
    if isinstance(seq, (list, tuple, str, bytes, set)):
        return seq, type(seq)
    # If seq is an iterable but not a concrete sequence object
    if hasattr(seq, "__iter__"):
        # Support optional bufsize to avoid exhausting large iterators
        if bufsize is not None:
            collected = []
            for idx, item in enumerate(seq):
                if idx >= bufsize:
                    break
                collected.append(item)
            return collected, list
        # Convert to a list when no size constraint is specified
        return list(seq), list
    # If seq is neither a sequence nor iterable, raise an informative error
    raise TypeError(f"Provided seq of type {type(seq).__name__} is not a sequence or iterable")

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # Check if seq is already a sequence (list, tuple, etc.) but not a string/bytes
    try:
        import collections.abc as _abc
    except Exception:
        _abc = None
    if _abc and isinstance(seq, _abc.Sequence) and not isinstance(seq, (str, bytes)):
        return seq, type(seq)

    # If seq is an iterable but not a string/bytes, convert to a sequence
    if hasattr(seq, "__iter__") and not isinstance(seq, (str, bytes)):
        try:
            if bufsize is None:
                sequence = list(seq)
            else:
                import itertools as _itertools
                sequence = list(_itertools.islice(seq, bufsize))
            return sequence, type(sequence)
        except Exception as exc:
            raise ValueError(f"Unable to convert input to a sequence: {exc}") from exc

    # For non-iterables (including strings/bytes), wrap in a list
    return [seq], list

def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # Getter
    if other is None:
        # Prefer private attribute if exists
        if hasattr(self, "_scale"):
            return getattr(self, "_scale")
        if hasattr(self, "scale"):
            return getattr(self, "scale")
        # No scale set
        return None

    # Setter – validate *other*
    if not isinstance(other, (int, float, np.number)):
        raise TypeError("Scale must be a numeric value.")
    # Current scale
    cur = None
    if hasattr(self, "_scale"):
        cur = getattr(self, "_scale")
    elif hasattr(self, "scale"):
        cur = getattr(self, "scale")

    if cur is None or not isinstance(cur, (int, float, np.number)) or cur == 0:
        raise LenaValueError("Unable to rescale graph with unknown or zero scale.")

    factor = other / cur

    # Identify last coordinate (assume ordering z > y > x)
    axis_names = ["x", "y", "z"]
    last_coord = None
    for name in reversed(axis_names):
        if hasattr(self, name):
            val = getattr(self, name)
            if val is not None:
                if isinstance(val, (np.ndarray, list, tuple)):
                    last_coord = name
                    break
    if last_coord is None:
        raise AttributeError("No coordinate found to rescale.")

    # Rescale coordinate data
    try:
        coord = getattr(self, last_coord)
        if isinstance(coord, np.ndarray):
            np.multiply(coord, factor, out=coord)
        else:
            setattr(self, last_coord, [v * factor for v in coord])
    except Exception as exc:
        raise RuntimeError(f"Failed to rescale coordinate '{last_coord}': {exc}") from exc

    # Rescale associated error if present
    err_attr = f"{last_coord}_err"
    if hasattr(self, err_attr):
        err = getattr(self, err_attr)
        try:
            if isinstance(err, np.ndarray):
                np.multiply(err, factor, out=err)
            else:
                setattr(self, err_attr, [v * factor for v in err])
        except Exception as exc:
            raise RuntimeError(f"Failed to rescale error '{err_attr}': {exc}") from exc

    # Update stored scale
    if hasattr(self, "_scale"):
        setattr(self, "_scale", other)
    else:
        setattr(self, "scale", other)

    return None

def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    import numpy as np

    # Determine the list of coordinate attributes in the order x, y, z
    coord_attrs = [a for a in ('x', 'y', 'z') if hasattr(self, a)]
    if not coord_attrs:
        try:
            raise LenaValueError("No coordinate attributes found")
        except NameError:
            raise ValueError("No coordinate attributes found")

    # The last coordinate is the one to be rescaled
    last_coord_name = coord_attrs[-1]
    last_coord = getattr(self, last_coord_name)

    # Ensure last_coord is array-like and has a numeric scale
    if last_coord is None:
        try:
            raise LenaValueError("Scale is unknown for the last coordinate")
        except NameError:
            raise ValueError("Scale is unknown for the last coordinate")

    # Compute the current scale (maximum absolute value)
    try:
        # If numpy array
        current_scale = np.max(np.abs(last_coord))
    except Exception:
        # Fallback for plain Python sequences
        try:
            current_scale = max(abs(v) for v in last_coord)
        except Exception:
            try:
                current_scale = abs(last_coord)
            except Exception:
                try:
                    raise LenaValueError("Unable to determine scale")
                except NameError:
                    raise ValueError("Unable to determine scale")

    if np.isnan(current_scale) or current_scale == 0:
        try:
            raise LenaValueError("Current scale is zero or undefined")
        except NameError:
            raise ValueError("Current scale is zero or undefined")

    if other is None:
        return current_scale

    # Validate other is numeric
    if not isinstance(other, (int, float)):
        try:
            raise TypeError("Scale factor must be numeric")
        except NameError:
            raise TypeError("Scale factor must be numeric")

    # Calculate scaling factor
    factor = other / current_scale

    # Rescale the last coordinate
    try:
        getattr(self, last_coord_name)[:] = last_coord * factor
    except Exception:
        # For immutable sequences, create new list/array
        new_coord = type(last_coord)(v * factor for v in last_coord)
        setattr(self, last_coord_name, new_coord)

    # Rescale associated error fields, if any
    for attr_name in list(vars(self).keys()):
        if attr_name.startswith(last_coord_name):
            if attr_name.endswith(('err', 'error', '_err', '_error')):
                err_field = getattr(self, attr_name)
                try:
                    err_field[:] = err_field * factor
                except Exception:
                    new_err = type(err_field)(v * factor for v in err_field)
                    setattr(self, attr_name, new_err)

    return None

def scale(self, other=None):
    """
    Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # Identify coordinate fields – try common attribute names
    coord_names = (
        getattr(self, "_coordinate_names", None) or
        getattr(self, "_fields", None) or
        getattr(self, "fields", None)
    )
    if not coord_names:
        raise LenaValueError("Graph has no coordinate fields defined.")

    # Use the last coordinate specified
    last_coord = coord_names[-1]
    if not hasattr(self, last_coord):
        raise LenaValueError(f"Coordinate '{last_coord}' not found in the graph.")
    coord_data = getattr(self, last_coord)

    # Helper to compute scale (max absolute value)
    def _current_scale(data):
        try:
            return float(max(abs(v) for v in data)) if hasattr(data, "__iter__") else abs(data)
        except Exception:
            return None

    cur_scale = _current_scale(coord_data)

    # Getter: return current scale
    if other is None:
        if cur_scale is None:
            raise LenaValueError("Graph has unknown scale; cannot retrieve.")
        return cur_scale

    # Setter: validate and apply new scale
    if cur_scale is None or cur_scale == 0:
        raise LenaValueError("Graph has unknown or zero scale; cannot rescale.")
    if not isinstance(other, (int, float)):
        raise TypeError("Scale value must be numeric.")

    factor = other / cur_scale

    # Rescale the last coordinate
    try:
        if hasattr(coord_data, "__iter__") and not isinstance(coord_data, (str, bytes)):
            new_coord = [v * factor for v in coord_data]
        else:
            new_coord = coord_data * factor
        setattr(self, last_coord, new_coord)
    except Exception as exc:
        raise RuntimeError("Failed to rescale the coordinate.") from exc

    # Rescale any associated error attributes
    suffixes = ("_err", "_error", "_errx", "_erry", "_errz")
    for suf in suffixes:
        err_name = last_coord + suf
        if hasattr(self, err_name):
            err_data = getattr(self, err_name)
            try:
                if hasattr(err_data, "__iter__") and not isinstance(err_data, (str, bytes)):
                    new_err = [e * factor for e in err_data]
                else:
                    new_err = err_data * factor
                setattr(self, err_name, new_err)
            except Exception:
                # If error scaling fails, ignore or log as needed
                pass
    return self

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    # Helper to extract numeric value from a bin or bin content.
    def _extract_val(item):
        if isinstance(item, (int, float)):
            return item
        # Try common attribute names
        for name in ("value", "content", "frequency", "count", "y"):
            if hasattr(item, name):
                return getattr(item, name)
        # If it's a sequence, take first element if numeric
        try:
            if isinstance(item, (list, tuple)) and len(item) > 0:
                v = item[0]
                if isinstance(v, (int, float)):
                    return v
        except Exception:
            pass
        raise TypeError(f"Cannot extract numeric value from {item!r}")

    # Helper to get coordinate
    def _get_coord(bin_obj):
        if get_coordinate == "left":
            if hasattr(bin_obj, "left"):
                return bin_obj.left
            raise AttributeError("Histogram bin has no 'left' attribute")
        if get_coordinate == "right":
            if hasattr(bin_obj, "right"):
                return bin_obj.right
            raise AttributeError("Histogram bin has no 'right' attribute")
        if get_coordinate == "middle":
            if hasattr(bin_obj, "left") and hasattr(bin_obj, "right"):
                return (bin_obj.left + bin_obj.right) / 2
            raise AttributeError("Histogram bin has no 'left'/'right' attributes")
        raise ValueError(f"Invalid get_coordinate: {get_coordinate!r}")

    # Resolve scale
    if scale is None:
        graph_scale = None
    elif scale is True:
        graph_scale = getattr(hist, "scale", None)
    else:
        graph_scale = scale

    # Build points list
    points = []
    for bin_obj in hist:
        try:
            coord = _get_coord(bin_obj)
        except Exception as e:
            raise ValueError(f"Coordinate extraction failed: {e}") from e

        try:
            val = _extract_val(bin_obj)
        except Exception as e:
            raise ValueError(f"Value extraction failed: {e}") from e

        if make_value is not None:
            try:
                val_res = make_value(val)
            except Exception as e:
                raise ValueError(f"make_value function raised an error: {e}") from e
        else:
            val_res = val

        # Ensure val_res is iterable (but not a string)
        if isinstance(val_res, (list, tuple, set)):
            point = [coord] + list(val_res)
        else:
            point = [coord, val_res]
        points.append(point)

    # Simple graph representation
    graph = {
        "points": points,
        "field_names": field_names,
        "scale": graph_scale,
    }
    return graph

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if iface is None:
        raise TypeError("iface cannot be None")
    if candidate is None:
        raise TypeError("candidate cannot be None")
    if not isinstance(iface, type):
        raise TypeError("iface must be a class or type")
    # choose a shortcut if candidate is a subclass of iface
    try:
        if isinstance(candidate, type) and issubclass(candidate, iface):
            return True
    except TypeError:
        # candidate might be an instance; fall through
        pass

    missing = []
    for name in dir(iface):
        if name.startswith('_'):
            continue
        attr = getattr(iface, name, None)
        if callable(attr):
            if not hasattr(candidate, name):
                missing.append(name)
            else:
                cand_attr = getattr(candidate, name, None)
                if not callable(cand_attr):
                    missing.append(name)
    if missing:
        msg = f"{candidate!r} does not implement {iface.__name__} methods: {missing}"
        if tentative:
            return False
        raise TypeError(msg)
    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    import inspect
    # If tentative is True, do a light-weight check and accept any candidate
    if tentative:
        return True
    if not inspect.isclass(iface):
        raise TypeError(f"iface must be a class; got {type(iface).__name__}")
    # If candidate is a class, check subclass relationship
    if inspect.isclass(candidate):
        if not issubclass(candidate, iface):
            raise TypeError(f"{candidate.__name__} does not subclass {iface.__name__}")
    else:
        # Candidate is an instance; ensure it is an instance of iface
        if not isinstance(candidate, iface):
            raise TypeError(f"Instance of type {type(candidate).__name__} does not implement interface {iface.__name__}")
    # Ensure all callable members of iface are present in candidate
    for name, member in inspect.getmembers(iface):
        if inspect.isfunction(member) or inspect.ismethod(member):
            if not hasattr(candidate, name):
                raise TypeError(f"Candidate is missing required method '{name}' from interface {iface.__name__}")
    return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    # Ensure bases is a list-like iterable
    bases_list = list(bases)

    # If an explicit metaclass is provided, use it after validation
    if explicit_mc is not None:
