            if tz_match:
                tz_str = tz_match.group(1)
                time_core = tp[:tz_match.start()]

        # Parse hour, minute, second, fraction
        m = re.match(r'^(?P<hour>\d{2})(?::?(?P<minute>\d{2}))?(?::?(?P<second>\d{2}))?(?:[.,](?P<frac>\d{1,6}))?$', time_core)
        if not m:
            raise ValueError(f"Unrecognized time format: {tp}")

        hour = int(m.group('hour'))
        minute = int(m.group('minute') or 0)
        second = int(m.group('second') or 0)
        frac = m.group('frac')
        microsecond = int((frac or '0').ljust(6, '0'))

        # Handle 24:00 case
        offset_day = False
        if hour == 24:
            if minute != 0 or second != 0 or microsecond != 0:
                raise ValueError("Hour 24 must have zero minute, second and fraction")
            hour = 0
            offset_day = True

        # Resolve timezone
        tzinfo = None
        if tz_str:
            if tz_str == 'Z':
                tzinfo = tzutc()
            else:
                # Parse offset
                sign = 1 if tz_str[0] == '+' else -1
                hrs = int(tz_str[1:3])
                mins = 0
                if len(tz_str) > 3:
                    tz_min_part = tz_str[3:]
                    if tz_min_part.startswith(':'):
                        mins = int(tz_min_part[1:3])
                    else:
                        mins = int(tz_min_part[0:2])
                total_offset = sign * (hrs * 3600 + mins * 60)
                tzinfo = tzoffset(None, total_offset)
        return hour, minute, second, microsecond, tzinfo, offset_day

    h, m, s, u, tz, offset_day = parse_time(time_part)

    dt = datetime(date_obj.year, date_obj.month, date_obj.day, h, m, s, u, tz)
    if offset_day:
        dt += timedelta(days=1)
    return dt

def fromutc(self, dt):
    """
    Given a timezone-aware datetime in a given timezone, calculates a
    timezone-aware datetime in a new timezone.

    Since this is the one time that we *know* we have an unambiguous
    datetime object, we take this opportunity to determine whether the
    datetime is ambiguous and in a "fold" state (e.g. if it's the first
    occurrence, chronologically, of the ambiguous datetime).

    :param dt:
        A timezone-aware :class:`datetime.datetime` object.
    """
    if dt is None:
        raise TypeError("dt argument cannot be None")
    if not isinstance(dt, datetime.datetime):
        raise TypeError("dt must be a datetime.datetime instance")
    if dt.tzinfo is None:
        raise TypeError("dt must be timezone-aware")

    # If the target timezone is the same as the source, just return a copy
    if self == dt.tzinfo:
        return dt

    try:
        converted = dt.astimezone(self)
    except Exception as exc:
        raise ValueError("Unable to convert datetime to target timezone") from exc

    # Preserve fold information if available (Python 3.6+)
    if hasattr(dt, "fold"):
        # Some datetime implementations may prevent setting fold directly;
        # use object.__setattr__ to avoid attribute errors.
        try:
            object.__setattr__(converted, "fold", dt.fold)
        except Exception:
            pass  # If we cannot set fold, silently ignore – conversion remains valid

    return converted

