    """
    Format a datetime in the way that D* nodes expect.
    The function accepts a `datetime.datetime` instance and returns a
    string representation suitable for the D* node interface:
    * If the datetime is naive (no tzinfo) it is formatted as
      ``YYYY-MM-DD HH:MM:SS``.
    * If the datetime carries timezone information it is converted to an ISO
      8601 string including the offset.
    Raises a ``TypeError`` if the input is not a ``datetime`` instance.
    """
    if not hasattr(dt, "timetuple") or not isinstance(dt, datetime):
        raise TypeError("dt must be a datetime.datetime instance")

    try:
        if dt.tzinfo is None:
            # Naive datetime – use a simple space-separated format
            return dt.strftime("%Y-%m-%d %H:%M:%S")
        else:
            # Aware datetime – return full ISO 8601 string
            return dt.isoformat()
    except Exception as exc:  # pragma: no cover
        raise RuntimeError(f"Failed to format datetime: {exc}") from exc

def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    The D* node format is an ISO‑8601 UTC timestamp without microseconds,
    e.g. "2023-01-31T15:45:00Z".
    """
    if not isinstance(dt, datetime.datetime):
        raise TypeError("format_dt expects a datetime instance")
    # Ensure the datetime is in UTC
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=datetime.timezone.utc)
    else:
        dt = dt.astimezone(datetime.timezone.utc)
    # Strip microseconds for the required format
    dt = dt.replace(microsecond=0)
    return dt.strftime("%Y-%m-%dT%H:%M:%SZ")

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    import re

    if not isinstance(text, str):
        raise TypeError("process_text_links expects a string input")

    # Matches http:// or https:// URLs (excluding trailing punctuation and quotes)
    url_re = re.compile(r'(?P<url>https?://[^\s<>"\']+)', re.IGNORECASE)

    def _replace(match):
        url = match.group('url')
        return f'<a href="{url}" target="_blank" rel="noopener">{url}</a>'

    return url_re.sub(_replace, text)

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    if not isinstance(text, str):
        return text
    import re
    url_pattern = re.compile(r'(https?://[^\s\'"<>]+)')
    def replace_url(match):
        url = match.group(1)
        try:
            # ensure quotes inside URL are escaped
            href = url.replace('"', '&quot;')
            return f'<a href="{href}" target="_blank" rel="noopener noreferrer">{url}</a>'
        except Exception:
            return url
    return url_pattern.sub(replace_url, text)

