    try:
        scheme, netloc, path, query, fragment = urllib.parse.urlsplit(url)
    except Exception:
        # Invalid URL format
        return None

    if scheme not in ('http', 'https', 'ftp', 'ftps'):
        # Unsupported scheme
        return None

    try:
        # Use a HEAD request to avoid downloading the body
        req = urllib.request.Request(url, method='HEAD')
        with urllib.request.urlopen(req, timeout=10) as resp:
            # For HTTP/HTTPS, ensure the response code is 200
            if hasattr(resp, 'status') and resp.status != 200 and scheme not in ('ftp', 'ftps'):
                return None
            # Retrieve the Content-Type header if present
            return resp.headers.get('Content-Type')
    except Exception:
        # Any exception (network issue, SSL error, etc.) results in None
        return None

def fetch_content_type(url: str) -> Optional[str]:
