    Fetch the HEAD of the remote url to determine the content type.
    """
    # allow empty string or None to be handled gracefully
    if not url:
        return None
    try:
        # parse URL to verify scheme
        scheme, netloc, _, _, _ = urlparse(url)
        if scheme not in ('http', 'https'):
            return None

        # build HEAD request
        req = Request(url, method='HEAD')
        with urlopen(req, timeout=10) as resp:
            # raise for HTTP errors (status code 4xx/5xx)
            if hasattr(resp, 'status'):
                if resp.status >= 400:
                    return None
            elif hasattr(resp, 'getcode'):
                if resp.getcode() >= 400:
                    return None
            # extract content type header
            content_type = resp.info().get('Content-Type')
            return content_type
    except Exception:
        # any exception (network, URL error, timeout, etc.) -> no content type
        return None

