    try:
        if not urlparse(url).scheme in ("http", "https"):
            return None
        req = Request(url, method="HEAD")
        with urlopen(req, timeout=10) as resp:
            return resp.headers.get("Content-Type")
    except (HTTPError, URLError, ValueError):
        return None

