    base = url.rstrip("/")
    # Determine the href for the nodeinfo document
    if document_path:
        # If a full URL is provided, use it directly
        if isinstance(document_path, str) and (document_path.lower().startswith("http://") or document_path.lower().startswith("https://")):
            href = document_path
        else:
            # Ensure the path begins with a slash
            path = document_path if document_path.startswith("/") else "/" + document_path
            href = f"{base}{path}"
    else:
        # Default nodeinfo document location
        href = f"{base}/.well-known/nodeinfo/1.0"
    # Construct and return the .well-known document
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/1.0",
                "href": href
            }
        ]
    }

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not document:
        return None
    # Try JSON first
    try:
        data = json.loads(document)
        if isinstance(data, dict):
            result: Dict = {}
            if "subject" in data:
                result["subject"] = data["subject"]
            links = {}
            for link in data.get("links", []):
                rel = link.get("rel")
                href = link.get("href")
                if rel and href:
                    links[rel] = href
            result["links"] = links
            # Convenience aliases
            result["hcard_url"] = links.get("hcard")
            result["lrdd_url"] = links.get("lrdd")
            return result
    except Exception:
        # Not JSON; fall back to XRD
        pass

    # Try XRD (XML) parsing
    try:
        def _strip_ns(tag):
            return tag.split("}")[-1] if "}" in tag else tag

        root = ET.fromstring(document)
        result: Dict = {}
        # Find subject
        subject_el = None
        for el in root.iter():
            if _strip_ns(el.tag).lower() == "subject":
                subject_el = el
                break
        if subject_el is not None:
            result["subject"] = subject_el.text
        # Find links
        links = {}
        for el in root.iter():
            if _strip_ns(el.tag).lower() == "link":
                rel = el.attrib.get("rel")
                href = el.attrib.get("href")
                if rel and href:
                    links[rel] = href
        result["links"] = links
        result["hcard_url"] = links.get("hcard")
        result["lrdd_url"] = links.get("lrdd")
        return result
    except Exception:
        # Unable to parse
        return None

def parse_diaspora_webfinger(document: str) -> Dict:
