            return None

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not document:
        return None

    # Attempt to parse as JSON first
    try:
        import json
        data = json.loads(document)
        # Collect subject if present
        result: Dict[str, str] = {}
        if "subject" in data:
            result["subject"] = data["subject"]

        # Link information may be stored under "_links" or "links"
        links = data.get("_links") or data.get("links") or {}
        for rel, link_obj in links.items():
            if isinstance(link_obj, dict):
                # Prefer href, fallback to template
                href = link_obj.get("href") or link_obj.get("template") or link_obj.get("templ")
                if href:
                    result[f"{rel}_url"] = href
        return result
    except Exception:
        pass  # JSON parsing failed, try XML

    # Attempt to parse as XRD (XML)
    try:
        import xml.etree.ElementTree as ET

        # Namespace used by XRD is often the default; handle both cases
        ns = {"xrd": "http://docs.oasis-open.org/ns/xri/xrd-1.0"}
        # Try to parse with namespace prefix; if fails, parse without
        try:
            root = ET.fromstring(document)
        except ET.ParseError:
            # Strip namespace prefixes if any
            document_str = document
            if "xmlns=" in document_str:
                document_str = document_str.split("xmlns=", 1)[1]
                document_str = document_str.split(">", 1)[1]
                document_str = ">" + document_str
                root = ET.fromstring(document_str)
            else:
                return None

        result: Dict[str, str] = {}

        # Extract subject
        subject_el = root.find(".//xrd:Subject", ns)
        if subject_el is None:
            subject_el = root.find(".//Subject")
        if subject_el is not None and subject_el.text:
            result["subject"] = subject_el.text

        # Extract all links
        for link_el in root.findall(".//xrd:Link", ns):
            if link_el is None:
                continue
            rel = link_el.attrib.get("rel")
            href = link_el.attrib.get("href") or link_el.attrib.get("template")
            if rel and href:
                result[f"{rel}_url"] = href

        # Fallback: no rel attribute but href present (unlikely)
        for link_el in root.findall(".//xrd:Link", ns):
            if link_el is None:
                continue
            href = link_el.attrib.get("href") or link_el.attrib.get("template")
            if href and not link_el.attrib.get("rel") and "href" not in result:
                result["href"] = href

        return result
    except Exception:
        return None

def parse_diaspora_webfinger(document: str) -> Dict:
