def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """Try to retrieve an RFC7033 webfinger document. Does not raise if it fails."""
    try:
        # Form the resource identifier, ensuring it starts with "acct:"
        resource = handle if handle.startswith("acct:") else f"acct:{handle}"
        # Extract the host part after the '@' in the resource
        try:
            host = resource.split("@", 1)[1]
        except IndexError:
            # Cannot find host part; invalid handle
            return None
        # Construct the well‑known webfinger URL
        url = f"https://{host}/.well-known/webfinger?resource={urllib.parse.quote(resource, safe='')}"
        # Attempt to fetch the document
        with urllib.request.urlopen(url) as response:
            if response.status != 200:
                return None
            return response.read().decode("utf-8")
    except Exception:
        # Suppress all exceptions: return None on failure
        return None

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """Try to retrieve an RFC7033 webfinger document. Does not raise if it fails."""
    if not handle:
        return None
    try:
        host = handle.split("@", 1)[1]
    except (IndexError, AttributeError):
        return None

    resource = urllib.parse.quote(handle)
    # Try HTTPS first, then HTTP if that fails
    urls = [
        f"https://{host}/.well-known/webfinger?resource={resource}",
        f"http://{host}/.well-known/webfinger?resource={resource}",
    ]

    for url in urls:
        try:
            with urllib.request.urlopen(url, timeout=5) as resp:
                if 200 <= resp.status < 300:
                    # Attempt to decode using utf-8, fall back to ignore errors
                    return resp.read().decode("utf-8", errors="replace")
        except Exception:
            # Ignore any error and try the next URL
            continue

    return None

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
