    urls = [
        f"https://{host}/.well-known/webfinger?resource={encoded_resource}",
        f"http://{host}/.well-known/webfinger?resource={encoded_resource}",
    ]

    for url in urls:
        try:
            with urlopen(url, timeout=5) as resp:
                # Check for successful status code
                if 200 <= resp.getcode() < 300:
                    # Read and decode the response body
                    return resp.read().decode("utf-8", errors="replace")
        except Exception:
            # Ignore any errors (e.g., network, timeout, HTTP error) and try next URL
