def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """
    if not isinstance(dic, dict):
        raise TypeError(f"'dic' must be a dict, got {type(dic).__name__}")

    full_keys = [key] + list(keys)
    if not full_keys:
        raise ValueError("At least one key must be provided")

    current = dic
    for i, k in enumerate(full_keys):
        if i == len(full_keys) - 1:
            # insert the value at the last key
            current[k] = val
        else:
            # ensure intermediate key points to a dict
            if k not in current or not isinstance(current[k], dict):
                current[k] = {}
            current = current[k]"""

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    import os
    import fnmatch
    from pathlib import Path

    if spec_option is None:
        spec_option = '*'
    # Normalize the settings_dirs to a list
    if isinstance(settings_dirs, (str, Path)):
        dirs = [settings_dirs]
    else:
        try:
            dirs = list(settings_dirs)
        except TypeError:
            dirs = [settings_dirs]
    file_list = []

    for d in dirs:
        try:
            for root, _, names in os.walk(str(d)):
                for name in names:
                    if fnmatch.fnmatch(name, spec_option):
                        file_list.append(os.path.join(root, name))
        except (OSError, TypeError):
            # Ignore directories that cannot be accessed
            continue

    return sorted(file_list)

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    import os
    import fnmatch
    # Normalize settings_dirs to a list
    if isinstance(settings_dirs, (str, bytes)):
        dirs = [settings_dirs]
    elif isinstance(settings_dirs, (list, tuple, set)):
        dirs = list(settings_dirs)
    else:
        raise TypeError("settings_dirs must be a string or an iterable of directory paths")
    # Validate spec_option
    if spec_option is None or spec_option == '':
        pattern = '*'
    elif isinstance(spec_option, str):
        pattern = spec_option
    else:
        raise TypeError("spec_option must be a string pattern or None")
    file_list = []
    for dir_path in dirs:
        try:
            if not os.path.isdir(dir_path):
                continue
            for entry in os.listdir(dir_path):
                if fnmatch.fnmatch(entry, pattern):
                    full_path = os.path.join(dir_path, entry)
                    if os.path.isfile(full_path):
                        file_list.append(full_path)
        except (OSError, IOError):
            # Skip directories that raise errors
            continue
    return sorted(file_list)

def list_of_file_names(settings_dirs, spec_option):
