    import os
    import fnmatch
    result = []
    # Ensure settings_dirs is iterable
    if isinstance(settings_dirs, (str, bytes)):
        dirs = [settings_dirs]
    else:
        dirs = list(settings_dirs)
    # Normalise spec_option to list of patterns
    if spec_option is None:
        patterns = ['*']
    elif isinstance(spec_option, (str, bytes)):
        patterns = [spec_option]
    else:
        patterns = list(spec_option)
    for d in dirs:
        try:
            for fname in os.listdir(d):
                full_path = os.path.join(d, fname)
                if not os.path.isfile(full_path):
                    continue
                for pat in patterns:
