        except OSError:
            # Skip directories that cannot be accessed
            continue
    return sorted(result)

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type

    Returns a sorted list of fully qualified file names from the given
    directories that optionally match ``spec_option``.  ``spec_option`` may be
    a string containing a file pattern (e.g. ``'.ini'``) or a regular 
    expression.  If it is ``None`` or empty, all files are returned.
    """
    import os
    import re
    result = []

    # Normalise settings_dirs to an iterable of paths
    if isinstance(settings_dirs, (str, bytes)):
        dirs = [settings_dirs]
    else:
        try:
            dirs = list(settings_dirs)
        except TypeError:
            dirs = [settings_dirs]

    # Compile a regex if spec_option looks like a pattern
    regex = None
    if spec_option:
        # If spec_option contains regex meta characters, treat it as regex
        if any(ch in spec_option for ch in r"^$.*+?[]\|()"):
            try:
                regex = re.compile(spec_option)
            except re.error:
                # Fallback: treat as plain substring
                regex = None
        else:
            # simple substring or extension match
            regex = None

    for d in dirs:
        try:
            if not os.path.isdir(d):
                continue
            for fname in os.listdir(d):
                if regex:
                    if not regex.search(fname):
                        continue
                else:
                    if spec_option and not (fname.endswith(spec_option) or spec_option in fname):
                        continue
                full_path = os.path.join(d, fname)
                if os.path.isfile(full_path):
                    result.append(full_path)
        except OSError:
            # Skip directories that cannot be accessed
            continue

    return sorted(result)

