def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    if not isinstance(parser_dict, dict):
        raise TypeError("parser_dict must be a dictionary of groups")
    # Helper to recursively resolve includes while detecting cycles
    def _resolve_section(name, stack):
        if name in stack:
            raise ValueError(f"Circular include detected: {' -> '.join(stack + [name])}")
        section = parser_dict.get(name)
        if section is None:
            raise KeyError(f"Group '{name}' not found in parser_dict")
        if not isinstance(section, dict):
            return
        if 'include' in section or 'includes' in section:
            includes = section.pop('include', None) or section.pop('includes', None)
            if includes is None:
                return
            if not isinstance(includes, (list, tuple)):
                includes = [includes]
            for inc_name in includes:
                _resolve_section(inc_name, stack + [name])
                inc_section = parser_dict.get(inc_name)
                if inc_section is None:
                    raise KeyError(f"Included group '{inc_name}' not found for group '{name}'")
                if not isinstance(inc_section, dict):
                    continue
                for k, v in inc_section.items():
                    if k not in section:
                        section[k] = v
    # Resolve all top-level groups
    for group_name in list(parser_dict.keys()):
        _resolve_section(group_name, [])

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    if parser_dict is None:
        raise ValueError("parser_dict cannot be None")
    if not isinstance(parser_dict, dict):
        raise TypeError("parser_dict must be a dict")
    # Pop the include directive so it is no longer in the dict
    include = parser_dict.pop('include', None)
    if include is None:
        return
    # Normalise the include value into a list of dicts
    if isinstance(include, list):
        source_dicts = include
    elif isinstance(include, dict):
        source_dicts = [include]
    else:
        raise TypeError("include directive must be a dict or a list of dicts")
    # Helper to merge two dicts recursively
    def _merge(target, source):
        for key, value in source.items():
            if (
                key in target
                and isinstance(target[key], dict)
                and isinstance(value, dict)
            ):
                _merge(target[key], value)
            else:
                target[key] = value
    # Merge each source dict into parser_dict
    for src in source_dicts:
        if not isinstance(src, dict):
            raise TypeError("Each include source must be a dict")
        _merge(parser_dict, src)

def _include_groups(self, parser_dict):
        """Resolves the include dict directive in the spec files."""
        if not isinstance(parser_dict, dict):
            return
        for key, value in list(parser_dict.items()):
            # If the value is a dict, look for an include directive
            if isinstance(value, dict):
                # Handle either "__include__" or "include" as the directive key
                include_key = None
                if "__include__" in value:
                    include_key = "__include__"
                elif "include" in value:
                    include_key = "include"
                # If an include directive is present and the value is a dict,
                # merge it into the current dict entry
                if include_key and isinstance(value[include_key], dict):
                    included = value[include_key]
                    # Build a new dict that merges the included dict
                    # with the remaining keys (excluding the directive key)
                    remaining = {k: v for k, v in value.items() if k != include_key}
                    merged = {**included, **remaining}
                    parser_dict[key] = merged
                    # recurse on the merged dict in case nested includes exist
                    self._include_groups(parser_dict[key])
                else:
                    # No include directive or included value is not a dict;
                    # just recurse into this dict to catch nested includes
                    self._include_groups(value)
            elif isinstance(value, list):
                # If the value is a list, recurse into any dicts inside it
                for idx, item in enumerate(value):
                    if isinstance(item, dict):
                        self._include_groups(item)

