def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    resolved = {}
    spec = getattr(self, "spec", None)
    if spec is None:
        return resolved

    for arg in self.args:
        if not isinstance(arg, _BaseOpt):
            raise ValueError(f"Expected an Option instance, got {type(arg).__name__}")

        name = arg.name
        # Attempt to get value from spec, fall back to default
        value = None
        try:
            # spec may expose a get method or support item access
            if hasattr(spec, "get"):
                value = spec.get(name)
            else:
                value = spec[name]
        except (AttributeError, KeyError, TypeError):
            # spec did not provide this option
            value = None

