        """
        if not isinstance(cli_args, dict) or not isinstance(answer_file_args, dict):
            raise TypeError("Both cli_args and answer_file_args must be dictionaries")

        deprecated_keys = []
        for key in answer_file_args:
            if key not in cli_args:
                deprecated_keys.append(key)

        if deprecated_keys:
            for key in deprecated_keys:
                # Emit a warning for each deprecated argument found only in the answer file
                print(f"Warning: argument '{key}' is deprecated and present only in the answer file. "
                      "Consider specifying it via the command line or updating the configuration.")
        return None

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Ensure the inputs are dictionaries
    if not isinstance(cli_args, dict):
        raise TypeError(f"cli_args must be a dict, got {type(cli_args).__name__}")
    if not isinstance(answer_file_args, dict):
        raise TypeError(f"answer_file_args must be a dict, got {type(answer_file_args).__name__}")

    # Fetch the deprecation mapping if it exists
    deprecated = getattr(self, "deprecated_args", None)
    if not isinstance(deprecated, dict):
        # nothing to validate if mapping is missing or invalid
        return

    import warnings

    for source_name, args in (("CLI", cli_args), ("Answer file", answer_file_args)):
        for old_arg, new_arg in deprecated.items():
            if old_arg in args:
                warnings.warn(
                    f"{source_name} argument '{old_arg}' is deprecated in favour "
                    f"of '{new_arg}'. '{old_arg}' will be removed in a future "
                    "version.",
                    category=DeprecationWarning,
                    stacklevel=2,
                )

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # Prefer a dedicated attribute holding the options
    try:
        if hasattr(self, f"{command_name}_options"):
            return getattr(self, f"{command_name}_options")

        # Look for a dictionary that maps command names to option lists
        if hasattr(self, "command_options") and isinstance(self.command_options, dict):
            return self.command_options.get(command_name, [])

        # Try a method that returns the options
        method_name = f"get_{command_name}_options"
        if hasattr(self, method_name):
            method = getattr(self, method_name)
            if callable(method):
                return method()

        # If there is a parser registry, pull options from the parser
        if hasattr(self, "parsers") and isinstance(self.parsers, dict):
            parser = self.parsers.get(command_name)
            if parser:
                # argparse parsers expose _actions, optparse has option_list
                if hasattr(parser, "_actions"):
                    return parser._actions
                if hasattr(parser, "option_list"):
                    return parser.option_list
    except Exception:
        # Any unexpected error should result in an empty list rather than
        # breaking the caller.
        return []

    # Fallback empty list if nothing found
    return []

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # Validate input type
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string, got %r" % type(command_name).__name__)

    # Ensure the underlying option storage exists
    if not hasattr(self, "command_options"):
        raise AttributeError("Parser instance lacks 'command_options' attribute")

    # Attempt to fetch specs for the requested command
    try:
        specs = self.command_options[command_name]
    except KeyError:
        raise KeyError("Unknown command name: %r" % command_name)

    # Validate the returned structure
    if not isinstance(specs, list):
        raise TypeError("Command options for %r must be a list, got %r" %
                        (command_name, type(specs).__name__))

    # Return a shallow copy to prevent accidental mutation
    return list(specs)

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # Validate input type
    if not isinstance(command_name, str):
        raise TypeError(
            f"command_name must be a string, got {type(command_name).__name__}"
        )

    # Common attribute names that may store the command options mapping
    candidate_attrs = ("_option_specs", "command_options", "options", "cmd_options")

    specs = None
    for attr in candidate_attrs:
        if hasattr(self, attr):
            mapping = getattr(self, attr)
            if isinstance(mapping, dict):
                # Direct dictionary look‑up
                specs = mapping.get(command_name)
                if specs is not None:
                    return specs
            elif isinstance(mapping, list):
                # Sometimes options are stored as a list of tuples
                # e.g. (command_name, options_list, …)
                for entry in mapping:
                    if (
                        isinstance(entry, (tuple, list))
                        and len(entry) >= 2
                        and entry[0] == command_name
                    ):
                        specs = entry[1]
                        return specs

    # If no mapping or entry found, raise an informative error
    raise KeyError(f"Command '{command_name}' not found in parser options")

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # Ensure the command name is a string
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")

    # 1. Try an internal mapping if the instance exposes one
    mapping = getattr(self, "_command_option_specs", None)
    if isinstance(mapping, dict):
        options = mapping.get(command_name)
        if options is not None:
            if isinstance(options, list):
                return options
            # In case a callable or other type is stored
            if callable(options):
                try:
                    return options()
                except Exception:
                    pass

    # 2. Try an attribute that follows a naming convention
    attr_name = f"{command_name}_options"
    options = getattr(self, attr_name, None)
    if isinstance(options, list):
        return options
    if callable(options):
        try:
            return options()
        except Exception:
            pass

    # 3. Try a helper method that could provide the options
    method_name = f"get_{command_name}_options"
    method = getattr(self, method_name, None)
    if callable(method):
        try:
            ret = method()
            if isinstance(ret, list):
                return ret
        except Exception:
            pass

    # 4. If nothing was found, return an empty list rather than raising
    return []

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    # Retrieve the command object from the stored commands.
    try:
        command = self.commands[command_name]
    except (AttributeError, KeyError):
        # If the command does not exist, issue a gentle warning and return None.
        if hasattr(self, "log"):
            self.log.warning("Command %r not found", command_name)
        else:
            try:
                import logging
                logging.getLogger(__name__).warning("Command %r not found", command_name)
            except Exception:
                pass
        return None

    # Attempt to fetch the option specification from the command.
    try:
        # Most CLI frameworks expose a mapping of arguments/options.
        options_attr = getattr(command, "options", None)
        if options_attr is None:
            options_attr = getattr(command, "args", None)
        return options_attr[argument_name]
    except (AttributeError, KeyError):
        # The specified option is missing; warn and return None.
        if hasattr(self, "log"):
            self.log.warning("Option %r not found in command %r", argument_name, command_name)
        else:
            try:
                import logging
                logging.getLogger(__name__).warning("Option %r not found in command %r",
                                                    argument_name, command_name)
            except Exception:
                pass
        return None

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    # Basic input validation
    if command_name is None or argument_name is None:
        raise ValueError("command_name and argument_name must not be None")
    if not isinstance(command_name, str) or not isinstance(argument_name, str):
        raise TypeError("command_name and argument_name must be strings")

    # Strip any leading dashes from the option name
    opt_key = argument_name.lstrip('-')

    try:
        # Command specifications are expected to be stored in an attribute named
        # `_commands` or `commands`.  It should be a mapping from command name to
        # the command's option specification.
        cmd_dict = getattr(self, "_commands", getattr(self, "commands", None))
        if cmd_dict is None:
            raise AttributeError("No command specification mapping found")

        # Retrieve the specification for the requested command
        cmd_spec = cmd_dict[command_name]
    except KeyError as exc:
        raise ValueError(f"Command '{command_name}' not found") from exc
    except Exception as exc:
        raise ValueError(f"Error accessing command specifications: {exc}") from exc

    # The command specification can be a dictionary mapping option names to
    # spec objects, or a list of spec objects.  Handle both cases.
    opt_spec = None

    if isinstance(cmd_spec, dict):
        opt_spec = cmd_spec.get(opt_key)
    elif isinstance(cmd_spec, list):
        for spec_item in cmd_spec:
            # Try a few common attribute names that might hold the option key
            try:
                name = getattr(spec_item, "name", None) or getattr(spec_item, "dest", None)
            except AttributeError:
                continue
            if name is None:
                continue
            if name.lstrip('-') == opt_key:
                opt_spec = spec_item
                break

    if opt_spec is None:
        raise ValueError(f"Option '{argument_name}' not found in command '{command_name}'")

    return opt_spec

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    if not command_name or not argument_name:
        raise ValueError("Both command_name and argument_name must be non-empty")
    specs = getattr(self, 'command_specs', None)
    if specs is None:
        raise AttributeError("Object has no 'command_specs' attribute")
    if not isinstance(specs, dict):
        raise TypeError("'command_specs' must be a dictionary")
    try:
        return specs[command_name][argument_name]
    except KeyError as exc:
        raise KeyError(f"Specification for command '{command_name}' and option '{argument_name}' not found") from exc

def get_silent_args(self, args):
    """
    list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    # If args is a list or tuple of strings, return those that look like options
    if isinstance(args, (list, tuple)):
        return [arg for arg in args
                if isinstance(arg, str) and arg.startswith('-') and arg != '-']
    # If args is a dict, return keys that look like options
    if isinstance(args, dict):
        return [k for k in args.keys()
                if isinstance(k, str) and k.startswith('-') and k != '-']
    # If args is a Namespace or has a __dict__, inspect its attributes
    if hasattr(args, '__dict__'):
        attr_dict = vars(args)
        return [k for k, v in attr_dict.items()
                if isinstance(k, str) and k.startswith('-') and k != '-']
    # Fallback: if args is iterable of key-value pairs
    try:
        return [k for k, v in args
                if isinstance(k, str) and k.startswith('-') and k != '-']
    except Exception:
        # Unable to interpret args; return empty list
        return []

def get_silent_args(self, args):
        """list of silenced argument

        :param args: The received arguments.
        :return: list, silenced argument names
        """
        silent = []
        try:
            if args is None:
                return silent
            # If args is a dict (e.g., parsed args from argparse)
            if isinstance(args, dict):
                for key, value in args.items():
                    if value is False or value is None:
                        silent.append(key)
                return silent
            # If args has a __dict__ (e.g., argparse.Namespace)
            if hasattr(args, "__dict__"):
                for key, value in args.__dict__.items():
                    if value is False or value is None:
                        silent.append(key)
                return silent
            # If args is an iterable of argument names, just return them as-is
            if isinstance(args, (list, tuple, set)):
                return list(args)
            # Fallback: return empty list for unknown types
            return silent
        except Exception:
            return silent

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, silenced argument names
    """
    silent = []
    if args is None:
        return silent

    # Handle mapping of argument names to values
    if isinstance(args, dict):
        for key, val in args.items():
            if val is None or val == '' or val is False:
                silent.append(key)
        return silent

    # Handle list of raw command-line arguments
    if isinstance(args, list):
        i = 0
        while i < len(args):
            arg = args[i]
            if isinstance(arg, str) and arg.startswith('-'):
                # Determine if this flag has an associated value
                if i + 1 < len(args) and isinstance(args[i + 1], str) and not args[i + 1].startswith('-'):
                    # Skip the value
                    i += 2
                    continue
                # Flag without following value; treat as silent
                silent.append(arg)
            i += 1
        return silent

    # Attempt to handle argparse.Namespace or similar objects
    try:
        for name in dir(args):
            if name.startswith('_'):
                continue
            val = getattr(args, name, None)
            if val is None or val == '' or val is False:
                silent.append(name)
    except Exception:
        pass

    return silent

def get_silent_args(self, args):
        """list of silenced argument

        :param args: The received arguments.
        :return: list, slienced argument names
        """
        # If there are no arguments, return an empty list
        if args is None:
            return []

        # Ensure we have an iterable collection
        try:
            iterable = list(args)
        except TypeError:
            # Non‑iterable input – nothing to process
            return []

        silent_names = []
        for arg in iterable:
            if isinstance(arg, str):
                # We consider an argument "silent" if it starts with an underscore
                # or contains the word "silent" (case‑insensitive).
                if arg.startswith('_') or 'silent' in arg.lower():
                    silent_names.append(arg)
        return silent_names

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # Determine the iterable of required argument names. If the object
    # does not provide a `required` attribute we consider nothing required.
    required = getattr(self, "required", None)
    if not required:
        return

    missing = []

    # If `args` is a mapping, look up keys directly.  If it is not
    # a mapping (e.g., a list or tuple), try to resolve arguments
    # by index using an optional `arg_names` attribute that
    # maps positions to names.
    if isinstance(args, dict):
        for name in required:
            if name not in args or args[name] is None:
                missing.append(name)
    else:
        # Optionally support positional args with a known order
        names = getattr(self, "arg_names", [])
        for name in required:
            try:
                index = names.index(name)
                if args[index] is None:
                    missing.append(name)
            except (ValueError, IndexError):
                missing.append(name)

    if missing:
        raise ValueError(f"Missing required argument(s): {', '.join(missing)}")

def validate_requires_args(self, args):
    """
    Check if all the required arguments have been provided.
    """
    if not isinstance(args, dict):
        raise TypeError(f"args must be a dict, got {type(args).__name__}")

    missing = []

    # Determine the list of required arguments. Prefer an explicit attribute
    # on the instance; fall back to any keys that start with 'req_'.
    required = getattr(self, "required", None)
    if required is None:
        required = [k for k in args if k.startswith("req_")]

    for name in required:
        if name not in args or args[name] is None:
            missing.append(name)

    if missing:
        raise ValueError(f"Missing required arguments: {', '.join(missing)}")

    return True

def validate_requires_args(self, args):
    """
    Check if all the required arguments have been provided.
    """
    # Determine the required arguments.  Subclasses may define
    # a `required_args` attribute containing an iterable of argument names.
    required = getattr(self, 'required_args', None)
    if not required:
        return  # nothing to validate

    # Normalise the `args` container.  It may be a dict (e.g., parameters
    # passed by keyword) or an argparse.Namespace/any object with attributes.
    missing = []
    for name in required:
        if isinstance(args, dict):
            # For dict-based arguments, None is considered missing.
            if name not in args or args[name] is None:
                missing.append(name)
        else:
            # For attribute-based objects, attribute must exist and not be None.
            if not hasattr(args, name) or getattr(args, name) is None:
                missing.append(name)

    if missing:
        # Raise a descriptive error to aid debugging.
        raise ValueError(f"Missing required argument(s): {', '.join(missing)}")

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # If the class defines a list/tuple of required argument names, use it
    required = getattr(self, 'required', None)
    if not required:
        # Nothing to validate
        return

    # Dictionary case: keys must contain all required names and values non‑None
    if isinstance(args, dict):
        missing = [name for name in required if name not in args]
        if missing:
            raise ValueError(f"Missing required argument(s): {', '.join(missing)}")
        none_vals = [name for name in required if args.get(name) is None]
        if none_vals:
            raise ValueError(f"Argument(s) cannot be None: {', '.join(none_vals)}")
        return

    # Sequence case: assume args follows the order of required names
    try:
        if len(args) < len(required):
            raise ValueError("Not enough arguments provided")
        none_vals = [required[i] for i, val in enumerate(args[:len(required)]) if val is None]
        if none_vals:
            raise ValueError(f"Argument(s) cannot be None: {', '.join(none_vals)}")
    except TypeError:
        # args is neither dict nor sequence; cannot validate
        raise ValueError("Unsupported argument type for validation")

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    matched = []
    if not options_spec:
        return matched

    # Normalize command_name & args for matching
    try:
        cmd = str(command_name)
    except Exception:
        cmd = None

    # Ensure args is a mapping if possible; otherwise keep as is
    try:
        args_mapping = dict(args)
    except Exception:
        args_mapping = None

    for opt in options_spec or []:
        # option may be a dict or object with attributes
        # Attempt to fetch name and required_when
        name = None
        req_when = None
        if isinstance(opt, dict):
            name = opt.get("name")
            req_when = opt.get("required_when")
        else:
            # Fallback to attribute access
            name = getattr(opt, "name", None)
            req_when = getattr(opt, "required_when", None)

        # Skip if no name or no condition
        if not name or req_when is None:
            continue

        # Determine if condition matches
        try:
            if callable(req_when):
                # Call with command_name and args (or mapping if provided)
                if args_mapping is not None:
                    result = req_when(cmd, args_mapping)
                else:
                    result = req_when(cmd, args)
            elif isinstance(req_when, (list, tuple, set)):
                # Condition is a list of command names
                result = cmd in req_when
            elif isinstance(req_when, dict):
                # Condition is a dict of required options; all must be present in args
                # e.g., {'opt_a': True, 'opt_b': False}
                # A key with truthy value means required only when that option
                # is present and truthy in args
                result = True
                for k, v in req_when.items():
                    if args_mapping is None:
                        result = False
                        break
                    val = args_mapping.get(k)
                    if bool(val) != bool(v):
                        result = False
                        break
            else:
                # Direct truthy value
                result = bool(req_when)
        except Exception:
            result = False

        if result:
            matched.append(name)

    return matched

def _get_conditionally_required_args(self, command_name, options_spec,
                                         args):
        """List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when``
            condition
        """
        # Basic validation
        if not isinstance(options_spec, (list, tuple)):
            raise TypeError("options_spec must be a list or tuple of specs")
        if not isinstance(args, dict):
            raise TypeError("args must be a dict of received arguments")

        required = []
        # Iterate over each option specification
        for spec in options_spec:
            # The destination name used internally (usually stored under 'arg')
            # If 'arg' not present, fall back to 'name' or ignore.
            name = spec.get('arg') or spec.get('name')
            if name is None:
                continue  # cannot determine name, skip

            if 'required_when' not in spec:
                continue  # no condition, not conditionally required

            cond = spec['required_when']
            try:
                satisfied = False
                # Callable condition
                if callable(cond):
                    try:
                        satisfied = bool(cond(args))
                    except Exception:
                        # If callable fails, treat as not satisfied
                        satisfied = False
                # Dictionary specifying required values
                elif isinstance(cond, dict):
                    satisfied = True
                    for key, expected in cond.items():
                        if args.get(key) != expected:
                            satisfied = False
                            break
                # Boolean or other truthy value
                else:
                    satisfied = bool(cond)
            except Exception:
                satisfied = False  # any error means condition not satisfied

            if satisfied:
                required.append(name)

        return required

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    matched_names = []
    for opt in options_spec:
        name = opt.get('name')
        if not name:
            continue
        cond = opt.get('required_when')
        if cond is None:
            continue
        try:
            if callable(cond):
                # Assume function signature (command_name, args)
                if cond(command_name, args):
                    matched_names.append(name)
            elif isinstance(cond, (list, tuple, set)):
                # List/tuple/set of command names that make this required
                if command_name in cond:
                    matched_names.append(name)
            elif isinstance(cond, dict):
                # Mapping of command_name to condition/value
                val = cond.get(command_name)
                if callable(val):
                    if val(args):
                        matched_names.append(name)
                elif val is not None:
                    if bool(val):
                        matched_names.append(name)
            else:
                # Direct truthy value
                if bool(cond):
                    matched_names.append(name)
        except Exception:
            # If condition test fails, treat as not matched
            continue
    return matched_names

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    # Normalize input arguments
    if args is None:
        args = {}
    if not isinstance(args, dict):
        raise TypeError("args must be a mapping from argument names to values")

    required = []

    for opt in options_spec:
        # Skip if not a mapping
        if not isinstance(opt, dict):
            continue

        # Determine the option name that will be returned
        # Preference: 'name', then 'arg', then the key if opt was a dict entry (not in this layout)
        opt_name = opt.get('name') or opt.get('arg')
        if not opt_name:
            # if the option itself is the key in a parent dict, we can't determine name
            continue

        cond = opt.get('required_when')
        if cond is None:
            continue

        # Evaluate the condition
        matched = False
        if callable(cond):
            try:
                matched = bool(cond(args))
            except Exception:
                matched = False
        elif isinstance(cond, dict):
            # All key/value pairs must match in args
            matched = True
            for key, expected in cond.items():
                if key not in args or args[key] != expected:
                    matched = False
                    break
        elif isinstance(cond, (list, tuple, set)):
            # All specified keys must be present in args
            matched = all(k in args for k in cond)
        else:
            # Treat single key: check presence and optional truthiness when value is bool
            key = cond
            if key in args:
                val = args[key]
                # If the expected value is a bool, check truthiness
                if isinstance(val, bool):
                    matched = val
                else:
                    matched = True
            else:
                matched = False

        if matched:
            required.append(opt_name)

    return required

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    required = []
    if args is None:
        args = {}
    for opt in options_spec:
        name = None
        cond = None
        # handle dict entries
        if isinstance(opt, dict):
            name = opt.get('name')
            cond = opt.get('required_when')
        # handle tuple/list entries like (name, spec)
        elif isinstance(opt, (tuple, list)) and len(opt) >= 2:
            name = opt[0]
            spec = opt[1]
            if isinstance(spec, dict):
                cond = spec.get('required_when')
            else:
                cond = getattr(spec, 'required_when', None)
        # handle objects with attributes
        else:
            name = getattr(opt, 'name', None)
            if name is None:
                name = getattr(opt, 'dest', None)
            cond = getattr(opt, 'required_when', None)
        if not name or cond is None:
            continue
        matched = False
        if callable(cond):
            try:
                matched = bool(cond(args))
            except Exception:  # pragma: no cover
                try:
                    matched = bool(cond(command_name, args))
                except Exception:
                    continue
        else:
            matched = bool(cond)
        if matched:
            required.append(name)
    return required

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments, either a mapping of argument names
        to values or a list of mappings one per argument.
    :raises ValueError: If an argument value exceeds its specified maximum
        length or if the input format is invalid.
    """
    # Resolve the runtime argument mapping
    if isinstance(args, dict):
        arg_items = list(args.items())
    elif isinstance(args, list):
        arg_items = []
        for i, item in enumerate(args):
            if isinstance(item, dict):
                if len(item) != 1:
                    raise ValueError(
                        f"Argument dict at index {i} contains {len(item)} keys; "
                        "expected exactly one"
                    )
                key, value = next(iter(item.items()))
                arg_items.append((key, value))
            else:
                raise TypeError(
                    f"Unsupported argument format at index {i}: "
                    f"{type(item).__name__}"
                )
    else:
        raise TypeError(
            f"Expected args to be a dict or a list of dicts; got {type(args).__name__}"
        )

    # Retrieve the specified limits from the parsed configuration
    spec = self.parsed_yaml.get("args", {})
    if not isinstance(spec, dict):
        raise TypeError(
            f"The 'args' specification should be a dict; got {type(spec).__name__}"
        )

    for arg_name, value in arg_items:
        arg_spec = spec.get(arg_name)
        if not isinstance(arg_spec, dict):
            continue  # No specific spec to validate against

        max_len = arg_spec.get("length")
        if max_len is None:
            continue  # No length constraint defined

        # Value must support len()
        try:
            actual_len = len(value)
        except Exception:
            # If len() is not supported, skip length validation for this value
            continue

        if not isinstance(max_len, int):
            raise TypeError(
                f"Length constraint for argument '{arg_name}' must be an int; "
                f"got {type(max_len).__name__}"
            )
        if actual_len > max_len:
            raise ValueError(
                f"Argument '{arg_name}' length {actual_len} exceeds "
                f"maximum allowed {max_len}"
            )

def validate_length_args(self, args):
    """
    Check if value of arguments is not longer than length specified.

    :param args: The received arguments. Usually a dict or a list of
                 dicts. Each argument value may contain a ``max_length``
                 key that indicates the maximum allowed length of the
                 associated ``value``.  If an argument does not have a
                 ``max_length`` key the length of its value is ignored.
    :raises TypeError: If ``args`` is not a dict or list, or if a
        ``max_length`` cannot be interpreted as an integer.
    :raises ValueError: If an argument value exceeds its ``max_length``.
    :return: ``True`` if all arguments satisfy their length limits.
    """
    # Validate container type
    if not isinstance(args, (dict, list)):
        raise TypeError("args must be a dict or a list")

    # Helper to validate a single argument specification
    def _check_arg_spec(arg_name, spec):
        # Spec may be a dict containing 'value' and optional 'max_length'
        if isinstance(spec, dict):
            if 'max_length' not in spec:
                # No length constraint – nothing to check
                return True
            max_len = spec['max_length']
            value = spec.get('value')
            # If there is no value yet to check, skip
            if value is None:
                return True
        elif isinstance(spec, tuple) and len(spec) == 2:
            value, max_len = spec
        else:
            # Unsupported spec format – ignore it
            return True

        # Ensure max_len is an integer
        if max_len is None:
            return True
        if not isinstance(max_len, int):
            try:
                max_len = int(max_len)
            except Exception:
                raise TypeError(
                    f"max_length for argument '{arg_name}' must be an "
                    f"int-like value, got {type(max_len).__name__}"
                )
        # Only string or bytes values are length checked
        if isinstance(value, (str, bytes)):
            if len(value) > max_len:
                raise ValueError(
                    f"argument '{arg_name}' exceeds its maximum length "
                    f"({max_len}): {len(value)}"
                )
        # Non-string values are implicitly valid
        return True

    # Handle dict case
    if isinstance(args, dict):
        for arg_name, spec in args.items():
            _check_arg_spec(arg_name, spec)
    else:
        # List case – each element is expected to be a dict with a single key
        for item in args:
            if not isinstance(item, dict):
                raise TypeError(
                    f"list item must be a dict with a single key, got "
                    f"{type(item).__name__}"
                )
            if len(item) != 1:
                raise ValueError(
                    f"each dict in args list must contain exactly one "
                    f"argument definition, got {len(item)} items"
                )
            for arg_name, spec in item.items():
                _check_arg_spec(arg_name, spec)

    return True

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # The `args` parameter can be either a dict mapping argument names
    # to their attributes, or a list of single-key dictionaries.
    # We normalise it to an iterable of (name, attrs) tuples.
    if isinstance(args, dict):
        arg_items = list(args.items())
    elif isinstance(args, list):
        arg_items = []
        for item in args:
            if not isinstance(item, dict):
                continue
            if len(item) != 1:
                continue
            arg_items.append(tuple(item.items())[0])
    else:
        raise TypeError("`args` must be a dict or a list of dicts")

    for arg_name, arg_attrs in arg_items:
        # Skip non-dict attribute containers
        if not isinstance(arg_attrs, dict):
            continue

        # Determine the length limit for the argument.  The limit can be
        # encoded under a few common keys; we support `max_length`, `length`,
        # and `size`.
        limit = (
            arg_attrs.get("max_length")
            or arg_attrs.get("length")
            or arg_attrs.get("size")
        )

        if limit is None:
            # No explicit length restriction – nothing to validate.
            continue

        # Obtain the value to test.  The value might be stored under
        # `value`, `default`, or directly as the argument mapping (see the
        # helper logic above).
        value = arg_attrs.get("value", arg_attrs.get("default"))

        # If the value is absent we cannot evaluate its length.
        if value is None:
            continue

        # Some values are scalars – only containers with a length are
        # validated.  We skip scalars to avoid raising False alarms.
        try:
            current_len = len(value)
        except Exception:
            # Not a sized object – silently skip.
            continue

        if current_len > limit:
            raise AssertionError(
                f"argument '{arg_name}' length ({current_len}) "
                f"exceeds the maximum allowed ({limit})"
            )

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    :raises ValueError: If an argument's value exceeds the specified maximum length.
    :raises TypeError: If provided lengths or values are of unexpected types.
    """
    # If args is a list, iterate over each item assuming dict with 'name' and 'value' keys
    if isinstance(args, list):
        for item in args:
            if not isinstance(item, dict):
                raise TypeError(
                    f"Expected a dict inside args list, got {type(item).__name__}"
                )
            name = item.get("name")
            value = item.get("value")
            max_len = item.get("max")
            if name is None or value is None or max_len is None:
                raise ValueError(
                    f"Argument dict must contain 'name', 'value', and 'max': {item}"
                )
            if not isinstance(max_len, int) or max_len < 0:
                raise TypeError(
                    f"Maximum length for argument '{name}' must be a non‑negative integer, "
                    f"got {max_len}"
                )
            if isinstance(value, (str, list, tuple)):
                if len(value) > max_len:
                    raise ValueError(
                        f"Argument '{name}' length {len(value)} exceeds maximum {max_len}"
                    )
            # For other types, no length check is performed
        return

    # If args is a dict, each key maps to a value or a dict containing value/length
    if isinstance(args, dict):
        for name, value in args.items():
            # If the value itself is a dict with 'value' and 'max'
            if isinstance(value, dict):
                if "value" not in value or "max" not in value:
                    raise ValueError(
                        f"Argument dict for '{name}' must contain 'value' and 'max': {value}"
                    )
                v = value["value"]
                max_len = value["max"]
            else:
                # Use value directly and try to look for a length spec in an implicit
                # attribute of the instance if available (`max_<name>`)
                v = value
                max_len = getattr(self, f"max_{name}", None)

            if max_len is None:
                # No length specification means nothing to validate
                continue

            if not isinstance(max_len, int) or max_len < 0:
                raise TypeError(
                    f"Maximum length for argument '{name}' must be a non‑negative integer, "
                    f"got {max_len}"
                )

            if isinstance(v, (str, list, tuple)):
                if len(v) > max_len:
                    raise ValueError(
                        f"Argument '{name}' length {len(v)} exceeds maximum {max_len}"
                    )
            # For other types, no length check is necessary
        return

    raise TypeError(
        f"Expected 'args' to be a dict or list, got {type(args).__name__}"
    )

def validate_choices_args(self, args):
    """
    Check if value of choice arguments is one of the available choices.

    :param args: The received arguments (mapping of argument names to values).
    :raises ValueError: If an argument value is not a permitted choice.
    """
    # Retrieve the mapping of argument names to available choices.
    # The containing class is expected to expose the mapping in an attribute
    # named either ``choices`` or ``arg_choices`` (common patterns).
    choices_map = getattr(self, "choices", None) or getattr(self, "arg_choices", None)

    # If no choices map is defined, nothing to validate.
    if not choices_map:
        return

    # Accept either a dict or a list of (name, value) tuples.
    if isinstance(args, dict):
        items = args.items()
    elif isinstance(args, list):
        items = args
    else:
        raise TypeError(
            f"Invalid type for args: expected dict or list, got {type(args).__name__}"
        )

    for item in items:
        # For list case, each item should be a (name, value) tuple.
        if isinstance(item, tuple):
            if len(item) != 2:
                raise ValueError(
                    f"Choice argument item {item!r} should be a two‑element tuple"
                )
            arg_name, value = item
        else:
            # In dict case, item is already a (name, value) pair.
            arg_name, value = item

        # Only validate arguments that have a defined choice list.
        if arg_name in choices_map:
            allowed = choices_map[arg_name]
            if value not in allowed:
                raise ValueError(
                    f"Invalid choice for argument '{arg_name}': {value!r}. "
                    f"Expected one of {allowed!r}."
                )

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Determine the mapping of choice arguments to their allowed values.
    # Prefer a `choices` attribute; fall back to the private `_choices`.
    choices = getattr(self, 'choices', getattr(self, '_choices', {}))
    if not isinstance(choices, dict):
        raise TypeError("The `choices` mapping must be a dictionary of "
                        "argument names to iterables of allowed values.")

    for arg_name, allowed in choices.items():
        # Skip validation if the argument was not provided.
        if arg_name not in args:
            continue

        value = args[arg_name]

        # If the value is a string but the allowed set contains multiple
        # entries, treat it as a single choice. String-like containers
        # that are iterable (bytes, str) should not be treated as a
        # collection of choices.
        def _is_iterable_except_str(obj):
            return isinstance(obj, (list, tuple, set, frozenset))

        if _is_iterable_except_str(value):
            # For container values, all items must be in the allowed list.
            for subval in value:
                if subval not in allowed:
                    raise ValueError(
                        f"Invalid choice for argument '{arg_name}': "
                        f"{subval!r}. Allowed: {allowed!r}."
                    )
        else:
            if value not in allowed:
                raise ValueError(
                    f"Invalid choice for argument '{arg_name}': {value!r}. "
                    f"Allowed: {allowed!r}."
                )

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Ensure we have a mapping of argument names to allowed choices.
    choices_map = getattr(self, 'choices', {})
    if not isinstance(args, dict):
        raise TypeError("args must be a dict")
    for name, value in args.items():
        # Skip if this argument has no choice restriction.
        if name not in choices_map:
            continue
        allowed = choices_map[name]
        if allowed is None:
            continue
        # Ignore unset values.
        if value is None or value == '':
            continue
        # If the value is a sequence, validate each element.
        if isinstance(value, (list, tuple, set)):
            for elem in value:
                if elem not in allowed:
                    msg = (
                        f"Invalid choice for argument '{name}': {elem!r}. "
                        f"Allowed choices are: {allowed}"
                    )
                    raise ValueError(msg)
        else:
            if value not in allowed:
                msg = (
                    f"Invalid choice for argument '{name}': {value!r}. "
                    f"Allowed choices are: {allowed}"
                )
                raise ValueError(msg)

def validate_choices_args(self, args):
    """
    Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Ensure the arguments are a dictionary
    if not isinstance(args, dict):
        raise TypeError(f"args must be a dict, got {type(args).__name__}")

    # Locate the stored argument definitions (common patterns)
    arg_defs = None
    if hasattr(self, "parsed_yaml"):
        arg_defs = getattr(self, "parsed_yaml", {}).get("args")
    if arg_defs is None and hasattr(self, "arguments"):
        arg_defs = getattr(self, "arguments", {})

    if arg_defs is None:
        raise AttributeError(
            "Unable to find 'args' definition on this object "
            "(expected 'parsed_yaml.args' or 'arguments')"
        )

    # Normalise into a list for easier iteration
    if isinstance(arg_defs, dict):
        items = [arg_defs]
    elif isinstance(arg_defs, list):
        items = arg_defs
    else:
        raise TypeError(f"Argument definitions should be dict or list, got {type(arg_defs).__name__}")

    for definition in items:
        if not isinstance(definition, (dict, list)):
            raise TypeError(f"Each argument definition should be dict or list, got {type(definition).__name__}")

        # Handle both dict and list forms
        if isinstance(definition, dict):
            for arg_name, arg_attrs in definition.items():
                if isinstance(arg_attrs, dict) and "choices" in arg_attrs:
                    choices = arg_attrs["choices"]
                    if not isinstance(choices, (list, tuple, set)):
                        raise TypeError(
                            f"choices for argument '{arg_name}' must be a list/tuple/set, "
                            f"got {type(choices).__name__}"
                        )
                    if arg_name in args and args[arg_name] not in choices:
                        raise ValueError(
                            f"Argument '{arg_name}' has value {args[arg_name]!r} which "
                            f"is not within the allowed choices {list(choices)}"
                        )
        else:  # list of items
            for item in definition:
                if isinstance(item, dict):
                    for arg_name, arg_attrs in item.items():
                        if isinstance(arg_attrs, dict) and "choices" in arg_attrs:
                            choices = arg_attrs["choices"]
                            if not isinstance(choices, (list, tuple, set)):
                                raise TypeError(
                                    f"choices for argument '{arg_name}' must be a list/tuple/set, "
                                    f"got {type(choices).__name__}"
                                )
                            if arg_name in args and args[arg_name] not in choices:
                                raise ValueError(
                                    f"Argument '{arg_name}' has value {args[arg_name]!r} which "
                                    f"is not within the allowed choices {list(choices)}"
                                )
    # No error -> args are valid with respect to defined choices
    return None

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Ensure args behaves like a mapping (e.g., dict)
    if not hasattr(args, "items"):
        raise TypeError("args must be a mapping of argument names to values")

    # Retrieve per-argument or global min/max limits from the instance, if they exist
    bounds_min = getattr(self, "min", {})
    bounds_max = getattr(self, "max", {})

    for name, value in args.items():
        # Determine the lower bound for this argument
        if isinstance(bounds_min, dict):
            min_val = bounds_min.get(name)
        else:
            min_val = bounds_min

        # Determine the upper bound for this argument
        if isinstance(bounds_max, dict):
            max_val = bounds_max.get(name)
        else:
            max_val = bounds_max

        # Validate against minimum
        if min_val is not None:
            try:
                if value < min_val:
                    raise ValueError(
                        f"Argument {name!r}={value} is less than minimum {min_val}"
                    )
            except TypeError as exc:
                raise TypeError(
                    f"Cannot compare value of argument {name!r} with minimum {min_val}"
                ) from exc

        # Validate against maximum
        if max_val is not None:
            try:
                if value > max_val:
                    raise ValueError(
                        f"Argument {name!r}={value} is greater than maximum {max_val}"
                    )
            except TypeError as exc:
                raise TypeError(
                    f"Cannot compare value of argument {name!r} with maximum {max_val}"
                ) from exc

    return args

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments. Each argument can be a tuple/list of
                 length three (value, min, max) or a dictionary with keys
                 'value', 'min', and 'max'. All values are expected to be
                 comparable (e.g., numeric). Raises :class:`ValueError` if any
                 value is outside its specified bounds.
    """
    if args is None:
        raise ValueError("args must not be None")

    # Ensure we are dealing with an iterable sequence
    try:
        iterator = iter(args)
    except TypeError:
        raise TypeError("args must be an iterable sequence")

    for idx, item in enumerate(iterator):
        # Determine the value, min, and max from the item
        try:
            if isinstance(item, (tuple, list)):
                if len(item) != 3:
                    raise ValueError
                value, min_val, max_val = item
            elif isinstance(item, dict):
                if not all(k in item for k in ('value', 'min', 'max')):
                    raise ValueError
                value, min_val, max_val = item['value'], item['min'], item['max']
            else:
                raise ValueError
        except ValueError:
            raise TypeError(
                f"Argument at index {idx} must be a tuple/list of length 3 "
                f"or a dict with keys 'value', 'min', and 'max'")

        # None checks
        if min_val is None or max_val is None:
            raise ValueError(
                f"Argument at index {idx} has None for min or max bounds")

        # Basic comparable check: try comparisons
        try:
            if not (min_val <= value <= max_val):
                raise ValueError
        except Exception as e:
            raise ValueError(
                f"Unable to compare values for argument at index {idx}: {e}")

    # All arguments validated successfully
    return args

def validate_min_max_args(self, args):
    """
    Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    :raises ValueError: If any argument is out of the defined bounds.
    """
    # The class is expected to define ``min_`` and/or ``max_`` attributes.
    min_val = getattr(self, "min_", None)
    max_val = getattr(self, "max_", None)

    if min_val is None and max_val is None:
        raise ValueError(
            "Instance must provide at least one of 'min_' or 'max_' attributes to validate arguments")

    for idx, val in enumerate(args):
        try:
            if min_val is not None and val < min_val:
                raise ValueError(
                    f"Argument at position {idx} with value {val} is less than minimum allowed {min_val}"
                )
            if max_val is not None and val > max_val:
                raise ValueError(
                    f"Argument at position {idx} with value {val} exceeds maximum allowed {max_val}"
                )
        except TypeError as exc:
            # In case the value or bounds are not comparable.
            raise TypeError(
                f"Argument at position {idx} with value {val} is not comparable with the provided bounds"
            ) from exc

    return True

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: Iterable of arguments. Each argument can be either a
        dictionary with keys ``value``, ``min`` and ``max`` or a tuple of
        three elements (value, min, max). The function validates that
        ``min <= value <= max`` for each item. If a value is out of range,
        a :class:`ValueError` is raised.
    """
    # Accept any iterable; if it's a single mapping treat it as a single argument
    if not hasattr(args, "__iter__") or isinstance(args, (str, bytes)):
        args = (args,)

    for idx, item in enumerate(args):
        # Determine value, min, max
        if isinstance(item, dict):
            try:
                value = item["value"]
                min_val = item["min"]
                max_val = item["max"]
            except KeyError as exc:
                raise ValueError(f"Argument dict at position {idx} "
                                 f"missing required key: {exc.args[0]}")
        elif isinstance(item, (list, tuple)) and len(item) == 3:
            value, min_val, max_val = item
        else:
            raise TypeError(f"Unsupported argument format at position {idx}: "
                            f"{type(item).__name__}")

        # Validate bounds
        try:
            if value < min_val:
                raise ValueError(f"Argument value {value} below minimum "
                                 f"({min_val}) at position {idx}")
            if value > max_val:
                raise ValueError(f"Argument value {value} above maximum "
                                 f"({max_val}) at position {idx}")
        except TypeError as exc:
            # Compatible types not comparable
            raise TypeError(f"Cannot compare value {value} with bounds "
                            f"{min_val}..{max_val} at position {idx}: "
                            f"{exc}")

    return args

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Validate that the instance defines the needed bounds
    try:
        min_val = self.min_value
        max_val = self.max_value
    except AttributeError as exc:
        raise AttributeError(
            "Instance must define 'min_value' and 'max_value' attributes."
        ) from exc

    if min_val > max_val:
        raise ValueError(
            f"Minimum value ({min_val}) cannot be greater than maximum value ({max_val})."
        )

    # Ensure we are working with an iterable of values; if a single non-iterable is passed, treat it as a one-element list
    if hasattr(args, "__iter__") and not isinstance(args, (str, bytes)):
        values = list(args)
    else:
        values = [args]

    for idx, val in enumerate(values):
        if not isinstance(val, (int, float)):
            raise TypeError(f"Argument {idx} ({val!r}) is not a numeric type.")
        if val < min_val or val > max_val:
            raise ValueError(
                f"Argument {idx} ({val}) is out of range [{min_val}, {max_val}]."
            )
    return values

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                    spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Basic validation of the provided arguments
    if not isinstance(subcommand, str):
        raise TypeError("subcommand must be a string")
    if not isinstance(type_name, str):
        raise TypeError("type_name must be a string")
    if not isinstance(option_name, str):
        raise TypeError("option_name must be a string")
    if not isinstance(spec_option, dict):
        raise TypeError("spec_option must be a dictionary")

    # Build a namespace for the new type.
    # Start with the core identifiers
    namespace = {
        "_subcommand": subcommand,
        "_option_name": option_name,
        "_spec_option": spec_option,
    }

    # If spec_option contains any key/value pairs that represent attributes
    # for the complex type, include them in the namespace.
    for key, value in spec_option.items():
        if key not in ("fields", "_subcommand", "_option_name", "_spec_option"):
            namespace[key] = value

    # Dynamically create a new type (class) with the given name.
    # The class inherits from object so it behaves like a plain Python object.
    try:
        ComplexType = type(type_name, (object,), namespace)
    except TypeError as exc:
        # In case the name is invalid or the namespace cannot be used
        raise TypeError(f"Failed to create type '{type_name}': {exc}") from exc

    # Return an instance of the newly created type
    return ComplexType()

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                    spec_option):
        """Build the complex argument type

        :param subcommand: the command name
        :param type_name: the complex type name
        :param option_name: the option name
        :param spec_option: option's specifications
        :return: the complex type instance
        """
        # Ensure spec_option is a mapping; copy to avoid side effects
        try:
            mapping = dict(spec_option) if spec_option is not None else {}
        except (TypeError, AttributeError):
            raise ValueError(
                f"spec_option must be a mapping for option '{option_name}' "
                f"on subcommand '{subcommand}', got {type(spec_option).__name__}"
            ) from None

        # If the mapping does not already specify a type, use the provided type_name
        if "__type__" not in mapping:
            if not type_name:
                raise ValueError(
                    f"Unable to determine type for option '{option_name}' "
                    f"on subcommand '{subcommand}': missing '__type__' and type_name"
                )
            mapping["__type__"] = type_name

        # Attach context information for better diagnostics or debugging
        mapping.setdefault("subcommand", subcommand)
        mapping.setdefault("option_name", option_name)

        # Delegate construction to the class's factory mechanism
        try:
            return self.construct(mapping)
        except Exception as exc:
            # Wrap any exception to provide context
            raise ValueError(
                f"Failed to create complex argument type '{type_name}' for "
                f"subcommand '{subcommand}', option '{option_name}': {exc}"
            ) from exc

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                    spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    if not subcommand or not type_name or not option_name:
        raise ValueError("subcommand, type_name, and option_name must be non‑empty")
    if spec_option is None or not isinstance(spec_option, dict):
        raise TypeError("spec_option must be a dictionary")

    # Construct a unique class name for the complex type
    class_name = f"{subcommand}_{type_name}_{option_name}".replace('-', '_')

    # Strip private keys from spec_option to use as class attributes
    attrs = {k: v for k, v in spec_option.items() if not k.startswith('_')}

    try:
        ComplexType = type(class_name, (object,), attrs)
    except Exception as exc:
        raise TypeError(f"Could not create complex type '{class_name}': {exc}") from exc

    # Instantiate the complex type. Prefer __init_kwargs__ if present.
    init_kwargs = spec_option.get('__init_kwargs__', {})
    try:
        instance = ComplexType(**init_kwargs)
    except Exception:
        # Fall back to a simple no‑arg constructor; if that fails, re‑raise.
        try:
            instance = ComplexType()
        except Exception as exc:
            raise RuntimeError(f"Failed to instantiate complex type '{class_name}': {exc}") from exc

    return instance

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Accept a dict or a list/iterable of (key, value) pairs
    if args is None:
        return {}, {}
    if isinstance(args, list) or isinstance(args, tuple):
        args = dict(args)
    if not isinstance(args, dict):
        raise TypeError(f"Expected dict or list of pairs, got {type(args).__name__}")
    control_args = {}
    nested_args = {}
    # Try to infer control keys from instance attributes if available
    control_keys = getattr(self, "control_keys", None)
    nested_keys = getattr(self, "nested_keys", None)
    # If no explicit lists, use heuristic: keys prefixed with '_' are control
    if control_keys is None:
        control_keys = {k for k in args if isinstance(k, str) and k.startswith("_")}
    if nested_keys is None:
        nested_keys = set(args) - control_keys
    for key, value in args.items():
        if key in control_keys:
            control_args[key] = value
        else:
            # All other keys are considered nested; custom args will be
            # included here as they are simply treated as normal nested
            # arguments that can override defaults.
            nested_args[key] = value
    return control_args, nested_args

def get_nested_custom_and_control_args(self, args):
    """
    Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected dict of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    if args is None:
        return {}, {}

    if not isinstance(args, dict):
        raise TypeError(f"Expected args to be a dict, got {type(args).__name__}")

    # Define keys that are considered control arguments. These should not
    # propagate into the playbook spec. Adjust this list as necessary for
    # the framework's requirements.
    control_keys = {
        "action", "destroy", "subcommand", "target", "list", "login",
        "matrix", "quiet", "debug", "help", "version", "force",
        "dry_run", "retry", "skip", "config", "run", "skip_verify"
    }

    control_args = {}
    nested_args = {}

    for key, value in args.items():
        if key in control_keys:
            control_args[key] = value
        else:
            nested_args[key] = value

    return control_args, nested_args

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}

    if args is None:
        return control_args, nested_args

    # Helper to normalize items to (key, value) tuples
    def normalize_items(collection):
        items = []
        for item in collection:
            if isinstance(item, (tuple, list)) and len(item) == 2:
                key, val = item
            elif isinstance(item, str) and '=' in item:
                key, val = item.split('=', 1)
            elif isinstance(item, str):
                # treat bare flag as boolean True
                key, val = item.strip(), True
            else:
                continue
            if isinstance(key, str):
                key = key.strip()
                items.append((key, val))
        return items

    try:
        if isinstance(args, dict):
            items = list(args.items())
        elif isinstance(args, list):
            items = normalize_items(args)
        else:
            # Attempt to iterate as generic iterable
            items = normalize_items(list(args))
    except Exception:
        # In case of any issue, return empty dicts
        return control_args, nested_args

    for key, value in items:
        if isinstance(key, str) and 'control' in key.lower():
            control_args[key] = value
        else:
            nested_args[key] = value

    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars (each item should be a dict)

    :return: The updated dict ``vars_dict``
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")

    if not extra_vars:
        return vars_dict

    # If a single dict was supplied instead of a list, handle it
    if isinstance(extra_vars, dict):
        extra_items = [extra_vars]
    elif isinstance(extra_vars, (list, tuple)):
        extra_items = extra_vars
    else:
        # Allow any iterable of dict-like objects
        try:
            extra_items = list(extra_vars)
        except TypeError:
            raise TypeError("extra_vars must be a dict or list/tuple of dicts")

    for item in extra_items:
        if isinstance(item, dict):
            vars_dict.update(item)
        else:
            # Ignore non-dict items to be tolerant
            continue

    return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
    """
    Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    :return: The updated vars_dict
    """
    if vars_dict is None or not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")
    if extra_vars is None:
        return vars_dict

    # Normalize extra_vars to a list
    if isinstance(extra_vars, dict):
        extra_vars_list = [extra_vars]
    elif isinstance(extra_vars, (list, tuple)):
        extra_vars_list = list(extra_vars)
    else:
        # Unsupported type: ignore it
        return vars_dict

    for item in extra_vars_list:
        if isinstance(item, dict):
            vars_dict.update(item)
        elif isinstance(item, (tuple, list)) and len(item) == 2:
            key, value = item
            vars_dict[key] = value
        else:
            # Skip invalid entries silently
            continue
    return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not isinstance(vars_dict, dict):
        raise ValueError("vars_dict must be a dictionary")
    # If no extra variables provided, just return the original dictionary
    if extra_vars is None:
        return vars_dict
    # Convert the list of dictionaries into a single dictionary
    if isinstance(extra_vars, list):
        merged_extra = {}
        for item in extra_vars:
            if isinstance(item, dict):
                merged_extra.update(item)
            else:
                raise ValueError("Each item in extra_vars must be a dictionary")
    elif isinstance(extra_vars, dict):
        merged_extra = extra_vars
    else:
        raise ValueError("extra_vars must be either a list of dictionaries or a dictionary")
    # Merge the dictionaries, overriding any overlapping keys
    new_dict = vars_dict.copy()
    new_dict.update(merged_extra)
    return new_dict

def merge_extra_vars(vars_dict, extra_vars=None):
    """
    Extend ``vars_dict`` with ``extra-vars``.

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    :return: The merged dictionary.
    """
    if not isinstance(vars_dict, dict):
        raise ValueError("vars_dict must be a dictionary")

    if not extra_vars:
        return vars_dict

    if isinstance(extra_vars, dict):
        vars_dict.update(extra_vars)
        return vars_dict

    if not isinstance(extra_vars, (list, tuple, set)):
        raise ValueError("extra_vars must be a dict or an iterable of dicts")

    for idx, item in enumerate(extra_vars):
        if not isinstance(item, dict):
            raise ValueError(f"Item at index {idx} of extra_vars is not a dict")
        vars_dict.update(item)

    return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """
    Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    # Resolve playbook path: use as provided; if relative it will be interpreted
    # relative to current working directory.
    if not os.path.isabs(playbook_path):
        playbook_path = os.path.abspath(playbook_path)

    if not os.path.exists(playbook_path):
        raise FileNotFoundError(f"Playbook file '{playbook_path}' does not exist")

    cmd = ['ansible-playbook']

    # Handle verbosity
    if verbose is not None:
        try:
            # if an integer is given, construct -v, -vv, etc.
            v_level = int(verbose)
            if v_level > 0:
                cmd.append('-' + 'v' * v_level)
        except Exception:
            # assume verbose is a string like '-vv' or '--verbose'
            if isinstance(verbose, str) and verbose.startswith('-'):
                cmd.append(verbose)

    # Append any extra ansible arguments
    if ansible_args:
        for key, value in ansible_args.items():
            flag = f'--{key}'
            if isinstance(value, bool):
                if value:
                    cmd.append(flag)
                else:
                    continue
            else:
                cmd.extend([flag, str(value)])

    # Append extra-vars if provided
    if extra_vars:
        try:
            ev_string = json.dumps(extra_vars)
        except Exception:
            ev_string = str(extra_vars)
        cmd.extend(['--extra-vars', ev_string])

    # Add the playbook path
    cmd.append(playbook_path)

    # Execute the command
    try:
        result = subprocess.run(
            cmd,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            check=False
        )
    except FileNotFoundError as fne:
        raise RuntimeError("The 'ansible-playbook' executable was not found.") from fne

    # Raise an error if ansible reported a failure
    if result.returncode != 0:
        raise RuntimeError(
            f"Ansible execution failed with return code {result.returncode}:\n{result.stderr}"
        )

    return result.stdout

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict in place.
    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict with arguments
    :return: The modified dictionary (in place, also returned for convenience)
    """
    # Helper to try integer conversion
    def _try_int(val):
        try:
            return int(val)
        except (ValueError, TypeError):
            return None

    # Helper to try float conversion
    def _try_float(val):
        try:
            return float(val)
        except (ValueError, TypeError):
            return None

    # Boolean interpretation
    bool_true = {"true", "yes", "1", "on"}
    bool_false = {"false", "no", "0", "off"}

    # If the object itself knows about option converters for this parser,
    # attempt to use them first.  This allows the caller to supply custom
    # conversion logic while still falling back to the generic heuristics.
    converters = None
    try:
        # Expected that a `get_option_converter` method exists.
        converters = getattr(self, "get_option_converter", lambda p, n: None)(parser_name, None)
        # If the method returned a dict mapping option names to conversion callables,
        # use it.  We ignore it if conversion cannot be applied.
    except Exception:
        converters = None

    for key, val in list(values_dict.items()):
        # Skip if value is already a non-string type
        if not isinstance(val, str):
            continue

        # Strip whitespace
        txt = val.strip()
        # Preserve empty strings as empty string
        if txt == "":
            values_dict[key] = ""
            continue

        # Boolean detection
        lower = txt.lower()
        if lower in bool_true:
            values_dict[key] = True
            continue
        if lower in bool_false:
            values_dict[key] = False
            continue

        # Custom converter from parser if available
        if converters and key in converters:
            try:
                values_dict[key] = converters[key](txt)
                continue
            except Exception:
                # fall back to generic conversion
                pass

        # Try integer conversion
        int_val = _try_int(txt)
        if int_val is not None and str(int_val) == txt:
            values_dict[key] = int_val
            continue

        # Try float conversion
        float_val = _try_float(txt)
        if float_val is not None and str(float_val) == txt:
            values_dict[key] = float_val
            continue

        # Treat as comma‑separated list
        if "," in txt:
            # split and strip each item
            values_dict[key] = [item.strip() for item in txt.split(",")]
            continue

        # Default: keep as string (but normalise spacing)
        values_dict[key] = txt

    return values_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    :return: The modified dict with converted values
    """
    if not isinstance(values_dict, dict):
        return values_dict

    def _convert_value(v):
        """Attempt to convert a single value to int, float, bool or keep as str."""
        if isinstance(v, str):
            stripped = v.strip()
            # Boolean values
            lower = stripped.lower()
            if lower in ("true", "yes", "1"):
                return True
            if lower in ("false", "no", "0"):
                return False
            # Attempt numeric conversions
            try:
                if "." in stripped or "e" in stripped.lower():
                    return float(stripped)
                return int(stripped)
            except ValueError:
                # Keep original string if conversion fails
                return v
        # For non-string types, return as is
        return v

    for key, val in list(values_dict.items()):
        if isinstance(val, list):
            values_dict[key] = [_convert_value(v) for v in val]
        else:
            values_dict[key] = _convert_value(val)

    return values_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Get the parser configuration if it exists
    parser_cfg = getattr(self, "parsers", {}).get(parser_name, {})
    # If there is no configuration, nothing to convert
    if not parser_cfg:
        return

    for opt_name, opt_cfg in parser_cfg.items():
        # Skip options that are not present in the provided dict
        if opt_name not in values_dict:
            continue
        raw_val = values_dict[opt_name]
        # Skip if value is already None
        if raw_val is None:
            continue
        # Determine the desired type; default to str if unspecified
        desired_type = opt_cfg.get("type", str)
        try:
            if desired_type is bool:
                # Handle common string representations of booleans
                if isinstance(raw_val, str):
                    lowered = raw_val.lower()
                    if lowered in ("1", "true", "yes", "on"):
                        raw_val = True
                    elif lowered in ("0", "false", "no", "off"):
                        raw_val = False
                    else:
                        raise ValueError(f"Invalid boolean value: {raw_val}")
                else:
                    raw_val = bool(raw_val)
            else:
                raw_val = desired_type(raw_val)
        except Exception as exc:
            raise ValueError(
                f"Failed to convert argument '{opt_name}' to {desired_type.__name__}"
            ) from exc
        values_dict[opt_name] = raw_val

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    def _cast(value):
        # Preserve non-string values
        if not isinstance(value, str):
            return value
        v = value.strip()
        # Boolean conversion
        bool_map = {"true": True, "false": False,
                    "yes": True, "no": False,
                    "1": True, "0": False}
        low = v.lower()
        if low in bool_map:
            return bool_map[low]
        # Integer conversion
        try:
            # Handles optional leading sign
            if v.lstrip("-").isdigit():
                return int(v)
        except Exception:  # pragma: no cover
            pass
        # Float conversion
        try:
            return float(v)
        except Exception:  # pragma: no cover
            pass
        # Return original string if no conversion succeeded
        return value

    # Convert each value in place
    for key, val in list(values_dict.items()):
        if val is not None:
            values_dict[key] = _cast(val)

    return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    _possible_spec_files = [
        'plugin.yaml', 'plugin.yml',
        'spec.yaml', 'spec.yml',
        'plugin.json'
    ]

    spec_path = None
    for fname in _possible_spec_files:
        potential = os.path.join(plugin_dir, fname)
        if os.path.isfile(potential):
            spec_path = potential
            break

    if spec_path is None:
        # No spec file found; return empty dict
        return {}

    # Load the spec content
    data = None
    try:
        if spec_path.lower().endswith('.json'):
            with open(spec_path, 'r', encoding='utf-8') as f:
                data = json.load(f)
        else:
            # Try to load YAML; fall back to plain text if pyyaml not available
            try:
                import yaml
                with open(spec_path, 'r', encoding='utf-8') as f:
                    data = yaml.safe_load(f)
            except Exception:
                # If YAML is not available or parsing fails, treat as empty
                data = None
    except Exception:
        # On any parsing error, return an empty dict
        return {}

    if not isinstance(data, dict):
        # If the spec does not start with a dict, return empty dict
        return {}

    # Helper to flatten nested dictionaries and lists
    def _flatten(current, parent_key='', result=None):
        if result is None:
            result = {}
        if isinstance(current, dict):
            for k, v in current.items():
                new_key = f"{parent_key}.{k}" if parent_key else k
                _flatten(v, new_key, result)
        elif isinstance(current, list):
            for idx, item in enumerate(current):
                new_key = f"{parent_key}[{idx}]" if parent_key else f"[{idx}]"
                _flatten(item, new_key, result)
        else:
            result[parent_key] = current
        return result

    return _flatten(data)

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    try:
        import os
        import json
    except Exception as exc:
        # If we cannot import required standard libraries, return empty dict
        return {}

    if not isinstance(plugin_dir, str):
        raise TypeError("plugin_dir must be a string path")
    if not os.path.isdir(plugin_dir):
        raise NotADirectoryError(f"'{plugin_dir}' is not a valid directory")

    # Try to locate the spec file
    spec_file = None
    for fname in ("plugin.json", "plugin.yaml", "plugin.yml"):
        candidate = os.path.join(plugin_dir, fname)
        if os.path.isfile(candidate):
            spec_file = candidate
            break

    if spec_file is None:
        # No spec file found
        raise FileNotFoundError(
            f"No plugin spec file found in directory '{plugin_dir}'. "
            "Expected 'plugin.json', 'plugin.yaml', or 'plugin.yml'."
        )

    # Load spec content
    def _load_json(path):
        with open(path, "r", encoding="utf-8") as f:
            return json.load(f)

    def _load_yaml(path):
        try:
            import yaml
        except ImportError:
            raise RuntimeError(
                "PyYAML is required to load YAML spec files. "
                "Install it via `pip install pyyaml`."
            )
        with open(path, "r", encoding="utf-8") as f:
            return yaml.safe_load(f)

    try:
        if spec_file.endswith(".json"):
            spec_data = _load_json(spec_file)
        else:
            spec_data = _load_yaml(spec_file)
    except Exception as exc:
        raise ValueError(f"Failed to load plugin spec from '{spec_file}': {exc}")

    if not isinstance(spec_data, dict):
        raise ValueError(f"Plugin spec must be a dictionary, got {type(spec_data).__name__}")

    # Helper to flatten nested dicts
    def _flatten(d, parent_key="", sep="."):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    flat_dict = _flatten(spec_data)
    return flat_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import json, os

    # Determine the spec file path (support common names)
    possible_filenames = ['plugin.json', 'spec.json', 'plugin.yaml', 'spec.yaml']
    spec_path = None
    for fn in possible_filenames:
        path = os.path.join(plugin_dir, fn)
        if os.path.isfile(path):
            spec_path = path
            break

    if spec_path is None:
        raise FileNotFoundError(f"No plugin spec file found in {plugin_dir}")

    try:
        with open(spec_path, 'r', encoding='utf-8') as f:
            if spec_path.endswith(('.yaml', '.yml')):
                # Attempt to load YAML if yaml module available; otherwise raise
                try:
                    import yaml
                except ImportError:
                    raise ImportError("YAML specification requires PyYAML library")
                spec = yaml.safe_load(f)
            else:
                spec = json.load(f)
    except Exception as exc:
        raise ValueError(f"Error loading plugin spec from {spec_path}: {exc}") from exc

    def _flatten(current, parent_key=''):
        items = {}
        for k, v in current.items():
            new_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key))
            else:
                items[new_key] = v
        return items

    if not isinstance(spec, dict):
        raise ValueError(f"Plugin spec file must contain a JSON object, got {type(spec).__name__}")

    return _flatten(spec)

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    def _flatten(obj, parent_key='', sep='.'):
        items = {}
        for k, v in obj.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    if not os.path.isdir(plugin_dir):
        raise FileNotFoundError(f"Directory not found: {plugin_dir}")

    spec_path_json = os.path.join(plugin_dir, 'plugin.json')
    if not os.path.isfile(spec_path_json):
        raise FileNotFoundError(f"plugin.json not found in {plugin_dir}")

    try:
        with open(spec_path_json, 'r', encoding='utf-8') as f:
            spec_data = json.load(f)
    except Exception as exc:
        raise ValueError(f"Error loading JSON from {spec_path_json}: {exc}") from exc

    if not isinstance(spec_data, dict):
        raise ValueError(f"Plugin spec at {spec_path_json} is not a dictionary")

    return _flatten(spec_data)

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    try:
        import yaml
    except ImportError:
        yaml = None

    if not plugin_dir or not os.path.isdir(plugin_dir):
        raise ValueError(f"'{plugin_dir}' is not a valid directory")

    # Locate a spec file – prioritize JSON, then YAML
    spec_file = None
    for filename in ("plugin.json", "plugin.yaml", "plugin.yml"):
        candidate = os.path.join(plugin_dir, filename)
        if os.path.isfile(candidate):
            spec_file = candidate
            break

    if spec_file is None:
        raise FileNotFoundError(f"No plugin spec file found in {plugin_dir}")

    # Read the spec
    if spec_file.endswith(".json"):
        with open(spec_file, "r", encoding="utf-8") as fh:
            spec_data = json.load(fh)
    else:
        if yaml is None:
            raise ImportError("PyYAML is required to parse YAML plugin specs")
        with open(spec_file, "r", encoding="utf-8") as fh:
            spec_data = yaml.safe_load(fh)

    # Flatten nested dictionaries using dot notation
    def _flatten(current, parent_key=""):
        result = {}
        for k, v in current.items():
            full_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                result.update(_flatten(v, full_key))
            else:
                result[full_key] = v
        return result

    return _flatten(spec_data)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    env_var = getattr(self, 'config_env_var', 'CONFIG_PATH')
    if env_var in os.environ:
        return
    config_value = None
    if hasattr(self, 'config_path') and self.config_path is not None:
        config_value = str(self.config_path)
    elif hasattr(self, 'config_file') and self.config_file is not None:
        config_value = str(self.config_file)
    if config_value is not None:
        os.environ[env_var] = config_value
        try:
            logger.debug("Injected config path into %s: %s", env_var, config_value)
        except Exception:
            pass  # logger may not be available
    else:
        # No config path available; nothing to inject
        pass

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    env_var = getattr(self, "CONFIG_ENV_VAR", "CONFIG_PATH")
    # If the environment variable is already set, nothing to do
    if env_var in os.environ:
        return os.environ[env_var]
    # Determine the path to configure
    try:
        path = str(self.config_path)
    except AttributeError:
        logger.warning(
            "Cannot inject config: 'config_path' attribute is missing."
        )
        return None
    # Set the environment variable only if the path exists
    if os.path.exists(path):
        os.environ[env_var] = path
        logger.debug(f"Set environment variable {env_var} = {path}")
        return path
    else:
        logger.warning(
            "Cannot inject config: path '%s' does not exist.", path
        )
        return None

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    import os
    # Determine the environment variable name to use; default to 'CONFIG_PATH'
    env_var = getattr(self, 'config_env_var', 'CONFIG_PATH')
    # If the environment variable is already set, do nothing
    if env_var in os.environ:
        return
    # Retrieve the configuration path from the instance; must be set
    if not hasattr(self, 'config_path'):
        raise AttributeError(
            "Instance lacks 'config_path' attribute and no environment "
            f"variable '{env_var}' is defined."
        )
    config_path = self.config_path
    # If the config path is a pathlib.Path, convert it to string
    try:
        config_path_str = str(config_path)
    except Exception as exc:
        raise ValueError(
            f"Invalid config_path value: {config_path!r}"
        ) from exc
    # Write the path to the environment
    try:
        os.environ[env_var] = config_path_str
    except Exception as exc:
        raise RuntimeError(
            f"Failed to set environment variable '{env_var}' with value "
            f"'{config_path_str}'."
        ) from exc
    return

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    env_var = 'CONFIG_PATH'
    try:
        # Only set the environment variable if it is currently undefined
        # and if a config path is available on the instance.
        if env_var not in os.environ and getattr(self, 'config_path', None):
            os.environ[env_var] = str(self.config_path)
    except Exception as exc:
        # Avoid raising during injection; silently ignore any errors.
        # Optionally, a logger could record the exception if available.
        pass

def extend_cli(self, root_subparsers):
    """
    Adds the spec cli options to the main entry point.

    :param root_subparsers: The argparse parser or subparsers object to extend.
    """
    if root_subparsers is None:
        return
    # If this is an argparse.ArgumentParser we add a '--spec' optional argument.
    try:
        if hasattr(root_subparsers, "add_argument"):
            root_subparsers.add_argument(
                "--spec",
                help="Path to the spec file to process",
                required=False,
            )
            return
    except Exception:
        pass
    # If this is a SubParsersAction object add a subcommand named 'spec'.
    try:
        if hasattr(root_subparsers, "add_parser"):
            spec_parser = root_subparsers.add_parser(
                "spec", help="Process a specification file"
            )
            spec_parser.add_argument(
                "spec_file",
                help="Path to the specification file",
                type=str,
            )
            return
    except Exception:
        pass

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("Both path and root must be strings")

    # Normalize paths to absolute forms
    norm_path = os.path.normpath(os.path.abspath(path))
    norm_root = os.path.normpath(os.path.abspath(root))

    # Ensure both paths are on the same drive (Windows specific)
    try:
        common = os.path.commonpath([norm_path, norm_root])
    except ValueError:
        raise ValueError(f"Path '{path}' and root '{root}' are on different drives or are invalid")

    if common != norm_root:
        raise ValueError(f"Root '{root}' is not a prefix of path '{path}'")

    # Compute relative path
    stripped = os.path.relpath(norm_path, norm_root)

    # If the path is exactly the root, relpath returns '.'
    if stripped == os.curdir:
        return ''
    return stripped

def strip_root(path, root):
    """
    Remove root from path, throw exception on failure.
    """
    import os
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("Both path and root must be strings")
    norm_path = os.path.normpath(path)
    norm_root = os.path.normpath(root)
    if not norm_root:
        raise ValueError("Root cannot be empty")
    try:
        common = os.path.commonpath([norm_root, norm_path])
    except ValueError:
        raise ValueError(f"Cannot determine common path for '{root}' and '{path}'")
    if common != norm_root:
        raise ValueError(f"Root '{root}' is not a prefix of path '{path}'")
    rel = os.path.relpath(norm_path, norm_root)
    return '' if rel == '.' else rel
